window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0113", [{"word":"thermodynamics","ipa_uk":"/ˌθɜːməʊdaɪˈnæmɪks/","ipa_us":"/ˌθɜːrmoʊdaɪˈnæmɪks/","definition_zh":"热力学；研究热、功与能量相互转换的物理学分支","definition_en":"the branch of physics that studies heat, work and the conversion between them","core_image":"一只蒸汽机的汽缸里，热气推着活塞向前滑动，热量被换算成推动机器的功","scene":"物理实验室里，老师指着蒸汽机模型讲解活塞的运动，说 Thermodynamics explains why the piston moves when steam expands.","sceneCN":"这里 thermodynamics 指「研究热与功相互转换的物理学分支」（第 1 个义项：把热、功与能量放进同一套规律）；句意为热力学解释了蒸汽膨胀时活塞为何移动。图中可辨识物件：蒸汽机模型、活塞、压力表、温度计。","pos":[{"tag":"n.","zh":"热力学（学科名，不可数，作主语时谓语用单数）"},{"tag":"n.","zh":"某套热力学分析或能量账目（引申用法）"}],"collocations":[{"phrase":"the laws of thermodynamics","zh":"热力学定律"},{"phrase":"the first law of thermodynamics","zh":"热力学第一定律"},{"phrase":"the second law of thermodynamics","zh":"热力学第二定律"},{"phrase":"engineering thermodynamics","zh":"工程热力学"},{"phrase":"chemical thermodynamics","zh":"化学热力学"},{"phrase":"thermodynamic equilibrium","zh":"热力学平衡"}],"forms":[{"label":"学科名（不可数，无复数）","form":"thermodynamics"},{"label":"形容词","form":"thermodynamic"},{"label":"副词","form":"thermodynamically"},{"label":"研究者名词","form":"thermodynamicist"},{"label":"相关形容词（热的）","form":"thermal"},{"label":"相关仪器","form":"thermometer"}],"derivatives":[{"word":"thermodynamic","pos":"adj.","zh":"热力学的；与热和功的转换有关的"},{"word":"thermodynamical","pos":"adj.","zh":"热力学的（较少用的形容词变体）"},{"word":"thermodynamically","pos":"adv.","zh":"从热力学角度看；在热力学意义上"},{"word":"thermodynamicist","pos":"n.","zh":"热力学研究者"}],"senses":[{"no":"01","title":"The science of heat and work","titleCN":"研究热与功相互转换的物理学分支","definition":"the branch of physics that deals with heat, work and the conversion between them","definitionCN":"研究热、功以及二者相互转换的物理学分支","example":"The steam engine gave nineteenth-century physicists their first practical problem in thermodynamics.","exampleCN":"蒸汽机给十九世纪的物理学家提供了第一个热力学实际问题。","why":"Greek thermē 'heat' plus dynamis 'power' names the field that turns heat into usable work.","whyCN":"希腊语 thermē「热」加 dynamis「力」，命名的正是把热变成可用功的学问。"},{"no":"02","title":"Energy is conserved in every process","titleCN":"第一定律：能量守恒","definition":"the principle that energy can change form but can neither be created nor destroyed in an isolated system","definitionCN":"在一个孤立系统中，能量可以改变形式，但既不能凭空产生也不能凭空消失","example":"The first law of thermodynamics rules out any machine that produces work from nothing.","exampleCN":"热力学第一定律排除了任何凭空产生功的机器。","why":"The law is an accounting rule: heat added, work done and internal energy must balance to zero.","whyCN":"这条定律是一本账：加入的热、对外做的功与内能变化必须收支相抵。"},{"no":"03","title":"Processes run in one direction","titleCN":"第二定律：熵增与过程的不可逆","definition":"the principle that entropy in an isolated system never decreases, so spontaneous processes have a preferred direction","definitionCN":"孤立系统的熵永不减少，因此自发过程具有固定的进行方向","example":"The second law of thermodynamics explains why heat never flows by itself from a cold cup to a hot one.","exampleCN":"热力学第二定律解释了热量为何不会自己从冷杯子流向热杯子。","why":"Once energy is spread out, gathering it back would require extra work, and the law states that this cannot happen on its own.","whyCN":"能量一旦散开，重新聚拢就需要额外做功，而这条定律正是说它不会自行发生。"},{"no":"04","title":"Analysis of engines and efficiency","titleCN":"热机循环与效率分析","definition":"the applied study of cycles that convert heat into mechanical work and of the limits on their efficiency","definitionCN":"研究把热转换为机械功的循环过程及其效率上限的应用学问","example":"Engineers use thermodynamics to decide how much of a turbine's heat can become electricity.","exampleCN":"工程师用热力学来判断涡轮机里的热量能有多少变成电能。","why":"The field grew from the practical need to measure how much work a boiler and piston could deliver.","whyCN":"这门学问起源于实际需要：测量锅炉与活塞究竟能输出多少功。"},{"no":"05","title":"Heat changes in chemical reactions","titleCN":"化学热力学：反应热与反应方向","definition":"the branch that predicts the heat released or absorbed by chemical reactions and the direction they can take","definitionCN":"预测化学反应放出或吸收的热量，以及反应可进行方向的分支","example":"Chemical thermodynamics tells chemists whether a reaction will warm the flask or chill it.","exampleCN":"化学热力学告诉化学家一个反应会让烧瓶变热还是变冷。","why":"When reactions replaced steam as the main source of questions, the same energy accounting was applied to bonds.","whyCN":"当化学反应取代蒸汽成为主要问题来源，同一套能量账目被套用到化学键上。"},{"no":"06","title":"From molecules to bulk properties","titleCN":"统计热力学：从微观粒子推出宏观性质","definition":"the branch that derives temperature, pressure and entropy from the statistical behaviour of very many particles","definitionCN":"由大量粒子的统计行为推出温度、压强与熵的分支","example":"Statistical thermodynamics links the average speed of molecules to the pressure on a container wall.","exampleCN":"统计热力学把分子的平均速率与容器壁受到的压强联系起来。","why":"Temperature is not a property of one molecule but of a crowd, so the laws are rebuilt from counting arrangements.","whyCN":"温度不是单个分子的属性，而是一群分子的属性，因此定律要从排列组合的计数重建。"},{"no":"07","title":"A ledger of gains and losses","titleCN":"比喻义：把任何系统当作能量或精力的账本","definition":"a way of describing any system as a balance of energy or effort coming in and going out","definitionCN":"把任何系统描述为能量或精力进出相抵的一种说法","example":"The coach treated the team's season as a lesson in thermodynamics, counting every ounce of fatigue.","exampleCN":"教练把球队的赛季当成一堂热力学课，把每一分疲劳都记在账上。","why":"The figurative use keeps the accounting core: nothing enters or leaves the ledger unnoticed.","whyCN":"比喻用法保留了记账这一核心：没有任何投入或损耗能不被记下。"},{"no":"08","title":"A course or textbook subject","titleCN":"作为课程或教材的学科名","definition":"the academic subject taught under this name, usually alongside mechanics and chemistry","definitionCN":"以此命名的学校课程，通常与力学、化学并列开设","example":"Thermodynamics is a required course for students of mechanical engineering.","exampleCN":"热力学是机械工程专业学生的必修课。","why":"As a discipline name ending in -ics, it is treated as singular and takes a singular verb.","whyCN":"作为以 -ics 结尾的学科名，它被当作单数，谓语动词也用单数。"}],"etymology":{"intro":{"en":"Thermodynamics is a nineteenth-century scientific compound built from two Greek nouns, thermē 'heat' and dynamis 'power', plus the subject suffix -ics. It has no inherited Latin ancestor; the Latin-looking ending is only the international scientific convention.","cn":"thermodynamics 是 19 世纪的科学复合词，由两个希腊名词 thermē「热」与 dynamis「力」加学科后缀 -ics 构成。它没有拉丁语祖传形式，看似拉丁的词尾只是国际科学命名惯例。"},"items":[{"era":"GREEK THERMĒ","en":"Thermē meant 'heat' and is related to thermos 'warm, hot'. Its origin before Greek is not established, so any older Indo-European form offered for it is a reconstruction.","cn":"thermē 意为「热」，与 thermos「温暖的、热的」相关。它在希腊语之前的来源未得到证明，凡为其提出的更早印欧形式均属重构形式。"},{"era":"GREEK DYNAMIS","en":"Dynamis meant 'power, force, capacity', from dynasthai 'to be able'. The same root gives English dynamic and dynamite.","cn":"dynamis 意为「力量、能力」，来自 dynasthai「能够」。同一词根还给出英语 dynamic 与 dynamite。"},{"era":"SCIENTIFIC COMPOUND","en":"The compound thermo- plus dynamics follows the pattern of other nineteenth-century subject names and means literally 'the study of heat-power'.","cn":"由 thermo- 加 dynamics 构成的复合词沿用了 19 世纪其他学科名的造词方式，字面意思是「研究热与力的学问」。"},{"era":"COINAGE 1849","en":"James Thomson is generally credited with the English term in 1849, and Thomson and Kelvin spread it through their work on heat engines. The exact first printing is a detail on which sources differ.","cn":"一般认为英语术语由 James Thomson 于 1849 年提出，并经他与开尔文的热机研究传播开来。最早的确切印刷出处各家记载不一，属仅首见年代存疑。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root and first date): the pre-Greek origin of thermē is unsettled and the earliest citation is not firmly fixed, so neither should be stated as fact.","cn":"来源不确定（更深词根与首见年代）：thermē 在希腊语之前的来源无定论，最早书证也未完全确定，两者都不宜当作定论陈述。"}]},"similar":{"note":{"en":"Group one holds look-alike words that share the Greek thermo- or dynam- element but name different things; group two holds neighbouring sciences with a different scope.","cn":"第一组是共享希腊 thermo- 或 dynam- 成分但所指不同的形近词；第二组是范围不同、彼此相邻的学科名。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dynamic","ipa":"/daɪˈnæmɪk/","tag":"shares dynamis only","definition":"From Greek dynamis 'power' but with no thermo- element: it describes force, energy or constant change, not the science of heat.","definitionCN":"只共享希腊 dynamis「力」，不含 thermo- 成分：形容力量、活力或不断变化，并非研究热的学科。"},{"word":"dynamics","ipa":"/daɪˈnæmɪks/","tag":"force, not heat","definition":"The study of forces and motion; thermodynamics is a separate subject that adds heat to the accounting.","definitionCN":"研究力与运动的学科；热力学是另一门学科，在账目里加入了热。"},{"word":"thermometer","ipa":"/θəˈmɒmɪtə/","tag":"same prefix, instrument","definition":"Thermo- plus metron 'measure': an instrument for reading temperature, not a branch of physics.","definitionCN":"thermo- 加 metron「测量」：读温度的仪器，不是物理学分支。"},{"word":"thermal","ipa":"/ˈθɜːml/","tag":"adjective only","definition":"An adjective meaning 'relating to heat', built on the same thermē root; it cannot name the discipline.","definitionCN":"由同一 thermē 词根构成的形容词，意为「热的、热量的」，不能用来指这门学科。"}]},{"heading":"NEAR MEANING","entries":[{"word":"physics","ipa":"/ˈfɪzɪks/","tag":"wider field","definition":"The whole science of matter, energy and motion; thermodynamics is one of its branches.","definitionCN":"研究物质、能量与运动的整个学科；热力学只是它的一个分支。"},{"word":"mechanics","ipa":"/mɪˈkænɪks/","tag":"motion, not heat","definition":"The study of forces and motion without the heat accounting that thermodynamics adds.","definitionCN":"研究力与运动的学问，不含热力学加入的热量账目。"},{"word":"calorimetry","ipa":"/ˌkæləˈrɪmətri/","tag":"measurement only","definition":"The practice of measuring heat exchanged in a process; it supplies data rather than the general laws.","definitionCN":"测量过程中热交换量的实务；它提供数据，而非普遍定律。"},{"word":"energetics","ipa":"/ˌenəˈdʒetɪks/","tag":"energy in general","definition":"The broad study of energy transformations in physical and chemical systems, of which thermodynamics is the strict heat-and-work core.","definitionCN":"研究物理与化学系统中能量转换的宽泛学问，热力学是其严格处理热与功的核心部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的希腊语构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"thermo- 'heat' + dynamics 'power': the study of heat becoming power.","cn":"thermo-「热」+ dynamics「动力」：研究热如何变成动力的学问。"},{"en":"The pair of laws is the backbone: the first keeps the books balanced, the second fixes the direction.","cn":"两条定律是骨架：第一定律让账目平衡，第二定律定下方向。"},{"en":"Fixed phrases mark the field: laws of thermodynamics, engineering thermodynamics, chemical thermodynamics.","cn":"固定搭配标出领域：热力学定律、工程热力学、化学热力学。"},{"en":"Shared morphemes appear in thermometer, thermal and dynamic.","cn":"共享的构词成分出现在 thermometer、thermal 与 dynamic 中。"},{"en":"The subject name ends in -ics and takes a singular verb, like physics and economics.","cn":"学科名以 -ics 结尾，谓语用单数，与 physics、economics 一样。"}],"abstract":[{"en":"Picture a sealed ledger in which every joule entering must be written on the other page as work or heat.","cn":"想象一本密封的账本，每进一焦耳，就必须在另一页记成功或热。"},{"en":"Picture a hill that a ball can roll down for free but can never roll up without being pushed.","cn":"想象一个斜坡，球可以自己滚下去，却不可能不被推就滚上来。"},{"en":"Picture a room full of scattered papers that will never gather back into neat stacks by themselves.","cn":"想象一屋子散落的纸页，永远不会自己重新叠成整齐的几摞。"}]},"examples":[{"en":"The whole plant is designed around the second law of thermodynamics.","cn":"整座工厂的设计都以热力学第二定律为依据。"},{"en":"Her lecture made thermodynamics feel like a branch of bookkeeping.","cn":"她的讲座让热力学听起来像会计学的一个分支。"},{"en":"No thermodynamics course can avoid the problem of wasted heat.","cn":"任何热力学课程都绕不开废热的问题。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「热」加「动力」再加学科词尾——研究热如何变成动力的学问，就是热力学","word":"thermodynamics"},"root":"希腊 thermē「热」+ dynamis「力、能力」+ 学科后缀 -ics；19 世纪按科学命名惯例构成，一般认为由 James Thomson 于 1849 年提出英语术语。thermē 在希腊语之前的来源不确定，不作印欧构拟；该词无拉丁语祖传同族词。","sensesIntro":{"en":"Eight senses follow one line: heat is treated as something that can be booked and moved, from the general science to its two laws, then to engines, reactions, crowds of molecules, a figurative ledger and finally a classroom subject.","cn":"八个义项沿一条线索展开：把热当成可以记账、可以搬运的东西，从总学科到两条定律，再到热机、化学反应、分子群体、比喻账本，最后落到课堂上的学科名。"},"semanticMap":{"core":{"en":"CORE IMAGE: steam pushing a piston, heat turned into measurable work.","cn":"核心意象：蒸汽推动活塞，热被换算成可测量的功。"},"chain":["HEAT AND WORK","ENERGY CONSERVED","ENTROPY RISES","ENGINE EFFICIENCY","REACTION HEAT","MOLECULAR STATISTICS"],"branches":[{"senses":"02 · 03","en":"THE TWO LAWS: one keeps the total, the other fixes the direction of change.","cn":"两条定律：一条守住总量，一条定下变化的方向。"},{"senses":"04","en":"MACHINES: the laws are applied to boilers, turbines and the ceiling on efficiency.","cn":"机器：定律被用于锅炉、涡轮机与效率上限。"},{"senses":"05","en":"REACTIONS: the same accounting is moved from steam to chemical bonds.","cn":"反应：同一套账目从蒸汽搬到化学键上。"},{"senses":"06","en":"CROWDS OF MOLECULES: temperature becomes a statistical fact about many particles.","cn":"分子群体：温度成为关于大量粒子的统计事实。"},{"senses":"01 · 07 · 08","en":"LEDGER, NAME AND FIELD: the accounting image spreads to daily effort, then to the course label, and the whole discipline bears that name.","cn":"账本、名称与学科：记账的意象扩展到日常精力，再落到课程名目，整个学科也以此命名。"}]},"affixes":{"intro":{"en":"Thermodynamics can be read as three pieces: the combining form thermo-, the root dynam-, and the subject suffix -ics; the same pieces build several everyday English words.","cn":"thermodynamics 可以拆成三块：组合成分 thermo-、词根 dynam- 与学科后缀 -ics；这三块还构成若干日常英语词。"},"latinIntro":{"en":"Both roots are Greek, and Latin has no inherited forms of this compound; the modern Latinized spelling is only a later borrowing for international use, so no Latin entries are listed.","cn":"两个词根都来自希腊语，拉丁语没有这个复合词的祖传形式；现代拉丁化拼写只是后来为国际通用而借用的形式，因此不列拉丁词条。"},"items":[{"word":"thermo-","structure":"thermo- (Greek combining form, from thermē 'heat')","meaning":"heat; temperature","meaningCN":"热；温度","example":"A thermometer measures heat with a column of liquid.","exampleCN":"温度计用一段液柱测量热度。"},{"word":"dynam-","structure":"dynam- (Greek root, from dynamis 'power')","meaning":"power; force","meaningCN":"力；力量","example":"A dynamo turns motion into electric power.","exampleCN":"发电机把运动转化为电力。"},{"word":"-ics","structure":"-ics (Greek suffix, 'the study or practice of')","meaning":"a branch of study","meaningCN":"某一学科或学问","example":"Physics and economics both end in the same suffix.","exampleCN":"physics 与 economics 都以同一后缀结尾。"},{"word":"thermodynamic","structure":"thermodynamics + -ic (relating to)","meaning":"relating to heat and work","meaningCN":"与热和功相关的","example":"The thermodynamic limit caps the efficiency.","exampleCN":"热力学极限给效率设了上限。"},{"word":"thermodynamically","structure":"thermodynamic + -ally (in a manner)","meaning":"in terms of heat and work","meaningCN":"从热力学角度；在热力学上","example":"The reaction is thermodynamically favourable.","exampleCN":"这个反应在热力学上是有利的。"},{"word":"thermodynamicist","structure":"thermodynamic + -ist (person who practises)","meaning":"a specialist in thermodynamics","meaningCN":"热力学专家","example":"The thermodynamicist modelled the cooling tower.","exampleCN":"这位热力学专家对冷却塔做了建模。"},{"word":"thermometer","structure":"thermo- + -meter (measuring device)","meaning":"an instrument for measuring temperature","meaningCN":"测量温度的仪器","example":"The thermometer on the wall read twenty degrees.","exampleCN":"墙上的温度计读数是二十度。"},{"word":"dynamic","structure":"dynam- + -ic (relating to)","meaning":"full of force or constant change","meaningCN":"有力量的；不断变化的","example":"The market stayed dynamic all year.","exampleCN":"市场整年都保持活跃变化。"},{"word":"thermal","structure":"therm- + -al (relating to)","meaning":"relating to heat","meaningCN":"与热有关的","example":"Thermal gloves keep the fingers warm.","exampleCN":"保暖手套让手指保持温暖。"}],"latinEntries":[]}},{"word":"heat","ipa_uk":"/hiːt/","ipa_us":"/hiːt/","definition_zh":"热；热量；高温天气；热度；（食物的）辣味；激烈程度；预赛；加热","definition_en":"the quality or state of being hot, or the energy that produces warmth; also to make something warm","core_image":"炉火把锅底烧红，锅里的油开始冒起细小的气泡，热气向上升腾","scene":"厨房里，厨师把平底锅放到灶火上，说 Heat the oil before you add the onions.","sceneCN":"这里 heat 是动词「加热」（第 8 个义项：把食物或液体加热到可以烹饪的温度）；句意为先把油烧热，再下洋葱。图中可辨识物件：平底锅、灶火、油、洋葱。","pos":[{"tag":"n.","zh":"热；热量；高温天气；热度；辣味；激烈程度；预赛"},{"tag":"vt.","zh":"加热；把……温热"},{"tag":"vi.","zh":"变热；升温"}],"collocations":[{"phrase":"heat wave","zh":"热浪"},{"phrase":"body heat","zh":"体温；体热"},{"phrase":"heat source","zh":"热源"},{"phrase":"heat up","zh":"加热；升温"},{"phrase":"heat loss","zh":"热量损失"},{"phrase":"heat transfer","zh":"热传递"}],"forms":[{"label":"三单（he/she/it）","form":"heats"},{"label":"过去式","form":"heated"},{"label":"过去分词","form":"heated"},{"label":"现在分词","form":"heating"},{"label":"名词复数","form":"heats"},{"label":"形容词（加热的；激烈的）","form":"heated"}],"derivatives":[{"word":"heated","pos":"adj.","zh":"加热的；热烈的；激烈的"},{"word":"heater","pos":"n.","zh":"加热器；暖气设备"},{"word":"heating","pos":"n./adj.","zh":"供暖；加热的"},{"word":"heatwave","pos":"n.","zh":"热浪；持续高温期"},{"word":"preheat","pos":"v.","zh":"预热"}],"senses":[{"no":"01","title":"Thermal energy in physics","titleCN":"物理学意义上的热、热能","definition":"the energy that transfers from a warmer body to a cooler one, measured in joules","definitionCN":"从较热物体传向较冷物体的能量，以焦耳计量","example":"The experiment measured how much heat the metal bar absorbed.","exampleCN":"实验测量了金属棒吸收了多少热量。","why":"The physical sense is the modern, countable-in-laboratory version of the old quality 'being hot'.","whyCN":"物理义是旧义「热的性质」在实验室里可计量的现代版本。"},{"no":"02","title":"Hot weather","titleCN":"高温天气、暑热","definition":"a period of unusually high air temperature, especially in summer","definitionCN":"气温异常偏高的一段时间，尤指夏季","example":"The heat kept the whole town indoors until evening.","exampleCN":"高温让全镇的人一直躲在家里直到傍晚。","why":"Weather talk applied the mass noun to the air itself, so 'the heat' became a way to name a hot spell.","whyCN":"谈天气时把这个不可数名词用到了空气上，「the heat」便成了指一段暑热的说法。"},{"no":"03","title":"A source of warmth","titleCN":"供暖；炉火或暖气带来的温暖","definition":"warmth supplied by a fire, radiator or heating system","definitionCN":"由炉火、暖气片或供暖系统提供的温暖","example":"They sat close to the stove because the heat reached only the front room.","exampleCN":"他们坐得离炉子很近，因为热气只到得了前屋。","why":"A fire is both the hot thing and the warmth it gives off, so the same noun names the source and the effect.","whyCN":"火既是热的东西，也是它散发的温暖，因此同一个名词兼指来源与效果。"},{"no":"04","title":"Body temperature and fever","titleCN":"体温；发热","definition":"the warmth of a living body, especially when it is higher than normal","definitionCN":"活体的温度，尤指高于正常水平时","example":"The nurse checked the child for heat around the forehead.","exampleCN":"护士摸了摸孩子的额头，看有没有发热。","why":"Living bodies produce warmth, so the noun moved from the fire to the body and then to illness.","whyCN":"活体自己产生热量，名词便从炉火移到身体，再移到疾病上。"},{"no":"05","title":"Pungency in food","titleCN":"食物的辣味、辛辣","definition":"the sharp burning sensation given by chilli, pepper or mustard","definitionCN":"辣椒、胡椒或芥末带来的尖锐灼烧感","example":"The heat of the sauce surprised everyone at the table.","exampleCN":"酱汁的辣度让桌上所有人都吃了一惊。","why":"The sensation is literally a burning warmth on the tongue, so the temperature word was borrowed for taste.","whyCN":"那种感觉本就是舌头上的灼热，于是温度词被借去形容味道。"},{"no":"06","title":"Intensity of feeling or pressure","titleCN":"情绪或局势的激烈程度","definition":"the most intense part of an activity, argument or period of pressure","definitionCN":"活动、争论或压力最激烈的阶段","example":"In the heat of the debate, nobody noticed the clock.","exampleCN":"辩论最激烈的时候，没人去看钟。","why":"Strong feeling was pictured as a fire burning at its hottest, so 'in the heat of' marks the peak.","whyCN":"强烈情绪被想象成烧得最旺的火，因此「in the heat of」标出最炽烈的顶点。"},{"no":"07","title":"A preliminary race","titleCN":"体育比赛的预赛","definition":"one of several earlier races whose winners go on to the final","definitionCN":"决赛之前举行的若干场比赛，胜者进入决赛","example":"She won her heat and advanced to the final.","exampleCN":"她赢下了自己的预赛，进入决赛。","why":"Each preliminary race was felt to 'heat up' the competitors; the sporting sense is a separate branch of the same noun.","whyCN":"每场预赛都被看作让选手「热起来」的环节；这一体育义是同一名词的另一条分支。"},{"no":"08","title":"To make something warm","titleCN":"动词：加热","definition":"to raise the temperature of something so that it becomes warm or ready to use","definitionCN":"提高某物的温度，使其变热或可以使用","example":"He heated the soup until it steamed.","exampleCN":"他把汤加热到冒热气。","why":"The verb is the plain causative of the noun: to heat something is to put heat into it.","whyCN":"动词是名词的普通使役形式：给某物加热，就是把热放进某物里。"}],"etymology":{"intro":{"en":"Heat is a native English word, not a borrowing. Old English had hǣtu 'heat' beside hāt 'hot', and the noun has kept the same shape in meaning for a thousand years.","cn":"heat 是英语本族词，不是借词。古英语在 hāt「热的」之外还有 hǣtu「热」，这个名词的含义千年来基本未变。"},"items":[{"era":"OLD ENGLISH HǢTU","en":"Hǣtu meant 'heat, warmth, the quality of being hot' and was formed from hāt 'hot'.","cn":"hǣtu 意为「热、温暖、热的性质」，由 hāt「热的」构成。"},{"era":"GERMANIC FAMILY","en":"The same stock appears in Old High German heizī and modern German Hitze, so the word is shared across the Germanic languages.","cn":"同一词源出现在古高地德语 heizī 与现代德语 Hitze，说明这个词在日耳曼语族内共用。"},{"era":"INDO-EUROPEAN ROOT","en":"The usual reconstruction is the root *kai- 'heat', but this is a reconstructed form, not a recorded word.","cn":"通常把词根构拟为 *kai-「热」，但这是重构形式，不是有记录的实际词。"},{"era":"SCIENTIFIC SENSE","en":"From the nineteenth century heat became a technical term for transferred thermal energy, and the older everyday senses remained beside it.","cn":"从 19 世纪起，heat 成为指传递热能的术语，而更早的日常义仍与它并存。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root only): the pre-Germanic origin rests on a reconstruction, and the first date of the sporting sense is recorded only loosely.","cn":"来源不确定（仅更深词根）：日耳曼语之前的来源建立在重构之上；体育义的最早年代也只有粗略记载。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close to heat but come from other roots; group two holds words for warmth or temperature that differ in scope.","cn":"第一组是形近或音近但词根不同的词；第二组是表示温暖或温度、范围有别的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"wheat","ipa":"/wiːt/","tag":"different word","definition":"The grain, from Old English hwǣte; it contains the letters of heat but has no connection to warmth.","definitionCN":"指小麦，来自古英语 hwǣte；字母与 heat 相近，但与「热」毫无关系。"},{"word":"hit","ipa":"/hɪt/","tag":"short vowel","definition":"To strike something, from Old English hittan; the vowel and the meaning both keep it apart from heat.","definitionCN":"指击打，来自古英语 hittan；元音与词义都使它不同于 heat。"},{"word":"heed","ipa":"/hiːd/","tag":"same sound, other root","definition":"To pay attention to something, from Old English hēdan 'to guard, observe'; it is not related to heat.","definitionCN":"指留意、注意，来自古英语 hēdan「看守、观察」；与 heat 不同源。"},{"word":"heathen","ipa":"/ˈhiːðn/","tag":"looks like heat","definition":"An old word for a non-Christian pagan, from Old English hǣthen; the shared letters hide a different origin.","definitionCN":"旧时指非基督教的异教徒，来自古英语 hǣthen；相同的字母掩盖了不同的来源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"warmth","ipa":"/wɔːmθ/","tag":"pleasant mild heat","definition":"A moderate, comfortable degree of heat; heat itself can be far more intense or technical.","definitionCN":"温和舒适的热度；heat 本身可以强烈得多，也可以作为技术术语。"},{"word":"temperature","ipa":"/ˈtemprətʃə/","tag":"measured level","definition":"The measured degree of hotness of a body or place, rather than the energy or the sensation.","definitionCN":"物体或场所被测出的冷热程度，而非能量本身或主观感受。"},{"word":"fever","ipa":"/ˈfiːvə/","tag":"abnormal body heat","definition":"A body temperature above normal caused by illness; heat is the wider word for any warmth.","definitionCN":"疾病引起的异常体温升高；heat 是泛指一切热度的更宽泛的词。"},{"word":"fire","ipa":"/ˈfaɪə/","tag":"the source, not the quality","definition":"The flame itself that produces heat; heat names the warmth or energy that the fire gives off.","definitionCN":"指产生热的火焰本身；heat 指火焰释放出的温暖或能量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real native root, real compounds and real collocations, not invented rhymes.","cn":"正常联想：真实的英语本族词根、真实复合词与真实搭配，而非编造的顺口溜。"},"normal":[{"en":"Old English hǣtu 'heat' stands beside hāt 'hot', so the noun and the adjective have always travelled together.","cn":"古英语 hǣtu「热」与 hāt「热的」并立，名词与形容词一直同行。"},{"en":"Compounds mark the senses: heat wave, body heat, heat source, heat loss, heat transfer.","cn":"复合词标出各义项：热浪、体温、热源、热量损失、热传递。"},{"en":"The verb family runs heat, heats, heated, heating, heater.","cn":"动词词族包括 heat、heats、heated、heating、heater。"},{"en":"The phrase 'in the heat of' always points to the most intense moment of an activity.","cn":"「in the heat of」这一短语总是指活动最激烈的那一刻。"},{"en":"Sporting heats are early races that heat up the competition before the final.","cn":"体育中的 heat 是决赛前让竞争「热起来」的预赛。"}],"abstract":[{"en":"Picture a kettle that keeps singing until the whole kitchen feels warm.","cn":"想象一只一直鸣响的水壶，直到整个厨房都暖起来。"},{"en":"Picture an argument that gets hotter the longer it lasts, until words are all sparks.","cn":"想象一场越吵越热的争论，最后每句话都成了火星。"},{"en":"Picture a single coal carried from a fire into a cold room, still glowing in the hand.","cn":"想象一块从火里带到冷屋的炭，仍在手心发着光。"}]},"examples":[{"en":"The heat from the radiator dried the wet coats overnight.","cn":"暖气片的热量一夜之间把湿外套烘干了。"},{"en":"Add the spices only after the oil begins to heat.","cn":"等油开始变热后再下香料。"},{"en":"The runners were assigned to different heats by their qualifying times.","cn":"选手按资格赛成绩被分到不同的预赛组。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「热特」——把东西放到火上热一热，热就出来了","word":"heat"},"root":"古英语 hǣtu「热」，由 hāt「热的」构成，属日耳曼语族，与古高地德语 heizī、现代德语 Hitze 同源；更深词根通常重构为 *kai-「热」，属重构形式，非实际记录词。无拉丁语同族来源。","sensesIntro":{"en":"Eight senses follow one line: warmth is first a physical quantity, then the weather, a fire, a body, a burning taste, a peak of feeling, a preliminary race, and finally the act of making something warm.","cn":"八个义项沿一条线索展开：热先是物理量，然后是天气、炉火、身体、灼烧的味觉、情绪的顶点、预赛，最后是给东西加热的动作。"},"semanticMap":{"core":{"en":"CORE IMAGE: a red stove bottom with oil beginning to bubble above it.","cn":"核心意象：烧红的锅底，上面的油开始冒泡。"},"chain":["THERMAL ENERGY","HOT WEATHER","WARMTH FROM FIRE","BODY WARMTH","BURNING TASTE","PEAK INTENSITY"],"branches":[{"senses":"01","en":"MEASURED ENERGY: physics turns the old quality into joules that can be counted.","cn":"可计量的能量：物理学把旧时的性质变成可数的焦耳。"},{"senses":"02 · 03","en":"WEATHER AND FIRE: the same noun names a hot spell and the warmth a stove gives out.","cn":"天气与炉火：同一个名词既指一段暑热，也指炉子散出的温暖。"},{"senses":"04 · 05","en":"BODY AND TONGUE: warmth becomes fever, then the burning of chilli.","cn":"身体与舌头：热变成发热，再变成辣椒的灼烧。"},{"senses":"06 · 07","en":"PEAK AND PRELIMINARY: feeling and sport both use heat for the stage that burns brightest.","cn":"顶点与预赛：情绪与体育都用 heat 指烧得最旺的阶段。"},{"senses":"08","en":"THE CAUSATIVE VERB: to heat is simply to put heat into something.","cn":"使役动词：加热就是把热放进某物。"}]},"affixes":{"intro":{"en":"Heat is a free English root that combines with particles and suffixes; the derived family is large and mostly transparent.","cn":"heat 是一个自由英语词根，可与小品词和后缀组合；派生词族庞大且大多一目了然。"},"latinIntro":{"en":"The word is native Germanic and has no Latin source; Latin calor and its family are semantic parallels only, so no Latin entries are listed.","cn":"这个词是日耳曼本族词，没有拉丁语来源；拉丁语 calor 及其词族只是语义上的平行词，因此不列拉丁词条。"},"items":[{"word":"heated","structure":"heat + -ed (past participle and adjective)","meaning":"made warm; also emotionally intense","meaningCN":"被加热的；也可指情绪激烈的","example":"A heated debate followed the announcement.","exampleCN":"公告之后是一场激烈的辩论。"},{"word":"heater","structure":"heat + -er (device or person that acts)","meaning":"a device that produces warmth","meaningCN":"产生暖气的装置","example":"The heater clicked on at midnight.","exampleCN":"半夜里取暖器咔哒一声启动了。"},{"word":"heating","structure":"heat + -ing (action or system)","meaning":"the process or system of warming a building","meaningCN":"供暖的过程或系统","example":"Heating costs rose with the cold snap.","exampleCN":"寒潮一来，供暖费用就上涨了。"},{"word":"heatwave","structure":"heat + wave (compound noun)","meaning":"a long period of very hot weather","meaningCN":"持续高温的一段时间","example":"The heatwave lasted eleven days.","exampleCN":"这波热浪持续了十一天。"},{"word":"preheat","structure":"pre- 'before' + heat","meaning":"to warm an oven before using it","meaningCN":"使用前先把烤箱预热","example":"Preheat the oven to two hundred degrees.","exampleCN":"把烤箱预热到两百度。"},{"word":"overheat","structure":"over- 'too much' + heat","meaning":"to become or make too hot","meaningCN":"过热；使过热","example":"The engine overheated on the long climb.","exampleCN":"发动机在长坡上过热了。"},{"word":"reheat","structure":"re- 'again' + heat","meaning":"to warm cooked food again","meaningCN":"把熟食重新加热","example":"She reheated the rice for lunch.","exampleCN":"她把米饭重新热了一下当午饭。"},{"word":"heatproof","structure":"heat + proof (compound adjective, 'resisting')","meaning":"able to resist high temperature","meaningCN":"耐高温的","example":"Use a heatproof mat under the pan.","exampleCN":"锅下面垫一块耐热垫。"}],"latinEntries":[]}},{"word":"heating","ipa_uk":"/ˈhiːtɪŋ/","ipa_us":"/ˈhiːtɪŋ/","definition_zh":"供暖；供暖系统；加热过程；加热的；供暖的","definition_en":"the process or system of making a place or object warm","core_image":"冬夜里暖气片慢慢变烫，窗玻璃上结着霜，屋里的空气一点点暖起来","scene":"冬天的客厅里，住户把温控器调高了一档，说 The heating comes on at six every morning.","sceneCN":"这里 heating 指「建筑物里的供暖系统」（第 1 个义项：由锅炉或热泵把热量送进房间的一整套设备）；句意为暖气每天早上六点启动。图中可辨识物件：暖气片、温控器、结霜的窗玻璃。","pos":[{"tag":"n.","zh":"供暖；供暖系统；加热过程（不可数）"},{"tag":"adj.","zh":"加热的；供暖的"}],"collocations":[{"phrase":"central heating","zh":"集中供暖"},{"phrase":"heating system","zh":"供暖系统"},{"phrase":"heating bill","zh":"供暖费账单"},{"phrase":"heating element","zh":"加热元件"},{"phrase":"global heating","zh":"全球变暖（强调人为加热）"},{"phrase":"turn on the heating","zh":"打开暖气"}],"forms":[{"label":"名词（不可数，通常无复数）","form":"heating"},{"label":"形容词","form":"heating"},{"label":"动词（heat 的现在分词）","form":"heating"},{"label":"相关动词原形","form":"heat"},{"label":"相关名词（加热器）","form":"heater"}],"derivatives":[{"word":"reheating","pos":"n.","zh":"重新加热；复热"},{"word":"overheating","pos":"n.","zh":"过热"},{"word":"preheating","pos":"n.","zh":"预热"},{"word":"heater","pos":"n.","zh":"加热器；取暖设备"},{"word":"heated","pos":"adj.","zh":"加热的；激烈的"}],"senses":[{"no":"01","title":"The system that warms a building","titleCN":"建筑物里的供暖系统","definition":"the equipment, such as a boiler or heat pump, that supplies warmth to rooms","definitionCN":"向房间供应暖气的设备，如锅炉或热泵","example":"The heating failed during the coldest night of the year.","exampleCN":"一年中最冷的那个夜里，供暖系统坏了。","why":"The gerund names an activity, but a household turns that activity into a permanent installation, so 'the heating' became the system itself.","whyCN":"动名词本指一项活动，但家庭把这项活动变成常设设备，于是「the heating」就指系统本身。"},{"no":"02","title":"The process of raising temperature","titleCN":"加热过程","definition":"the act or process of making something warmer, especially in a controlled way","definitionCN":"使某物变暖的动作或过程，尤指受控地进行","example":"Gentle heating keeps the mixture from separating.","exampleCN":"缓慢加热可以防止混合物分层。","why":"This is the plain verbal noun: any instance of the verb heat plus the action suffix -ing.","whyCN":"这是最普通的动词名词化：动词 heat 加表示动作的后缀 -ing。"},{"no":"03","title":"The cost or fuel of warmth","titleCN":"供暖开销或所用燃料","definition":"the money spent on, or the energy consumed by, warming a home","definitionCN":"为住宅供暖花掉的钱或消耗的能源","example":"Heating accounts for half of their winter bills.","exampleCN":"供暖占他们冬季账单的一半。","why":"Once 'the heating' means the system, its running cost is metonymically called heating too.","whyCN":"一旦「the heating」指系统，它的运行开销也就以借代方式同样叫作 heating。"},{"no":"04","title":"Global heating","titleCN":"全球变暖（强调人为加热）","definition":"the ongoing rise in global temperature caused by human greenhouse-gas emissions","definitionCN":"由人类温室气体排放引起的全球气温持续上升","example":"Some scientists prefer 'global heating' because it names an active process.","exampleCN":"一些科学家更愿意用「全球加热」，因为它点明这是一个主动过程。","why":"The climate term was coined to stress that the change is driven by people, not by a natural cycle.","whyCN":"这一气候术语的造词意图是强调变化由人推动，而不是自然循环。"},{"no":"05","title":"Industrial process heating","titleCN":"工业加热","definition":"the use of furnaces, induction or steam to bring materials to a required temperature in manufacturing","definitionCN":"制造业中用炉窑、感应或蒸汽把材料升到所需温度","example":"Induction heating hardens the metal without distorting it.","exampleCN":"感应加热能在不变形的情况下使金属硬化。","why":"Industry borrowed the household word for a technical process because the aim is the same: controlled warmth.","whyCN":"工业借用了家庭里的词来指技术过程，因为目的相同：受控的加热。"},{"no":"06","title":"A heating element","titleCN":"加热元件","definition":"the part of an appliance that converts electricity or gas into heat","definitionCN":"把电或燃气转化为热的器具部件","example":"The heating element glowed orange behind the fan.","exampleCN":"风扇后面的加热元件发出橙色的光。","why":"Shortened from 'heating element', the participle works as a modifier: the part whose job is heating.","whyCN":"由 heating element 缩略而来，分词作定语：职责就是加热的那个部件。"},{"no":"07","title":"Designed to warm something","titleCN":"形容词：用于加热的","definition":"used before a noun to describe a device or surface whose purpose is to supply warmth","definitionCN":"置于名词前，说明某装置或表面的用途是供热","example":"She plugged in the heating pad and put it on her back.","exampleCN":"她插上电热垫，把它放在背上。","why":"The participle keeps its verbal force: a heating pad is literally a pad for heating.","whyCN":"分词保留了动词意味：heating pad 字面就是「用来加热的垫子」。"},{"no":"08","title":"Laboratory heating","titleCN":"实验室加热","definition":"the controlled use of a burner or hot plate to warm a substance in an experiment","definitionCN":"实验中用本生灯或加热板受控地加热物质","example":"The label warns against direct heating of the sealed tube.","exampleCN":"标签警告不要直接加热密封管。","why":"Laboratory usage keeps the process sense pure: no installation, no bill, only a controlled rise in temperature.","whyCN":"实验室用法保留了纯粹的过程义：没有设备系统，也没有账单，只有受控的升温。"}],"etymology":{"intro":{"en":"Heating is a transparent English formation: the native noun and verb heat plus the old Germanic suffix -ing. Nothing in it is borrowed.","cn":"heating 是透明的英语构词：本族名词兼动词 heat 加古老的日耳曼后缀 -ing，没有任何借词成分。"},"items":[{"era":"OLD ENGLISH HEAT","en":"Heat goes back to Old English hǣtu, formed from hāt 'hot'; the verb hatian 'to make hot' existed beside it.","cn":"heat 上溯古英语 hǣtu，由 hāt「热的」构成；旁边已有动词 hatian「使变热」。"},{"era":"GERMANIC SUFFIX -ING","en":"The suffix -ing (in Old English also -ung) turned verbs into nouns of action, as it still does in heating and cooling.","cn":"后缀 -ing（古英语中亦作 -ung）把动词变成表示动作的名词，heating 与 cooling 至今如此。"},{"era":"MIDDLE ENGLISH NOUN","en":"From the Middle English period the -ing form served both as a participle and as a noun naming an ongoing action.","cn":"从中古英语时期起，-ing 形式既作分词，也作名词指正在进行的动作。"},{"era":"DOMESTIC SYSTEM","en":"With central heating in the nineteenth century, 'the heating' shifted from an action to the installed equipment of a house.","cn":"19 世纪出现集中供暖后，「the heating」从一项动作转指住宅里已安装的设备。"},{"era":"CLIMATE TERM","en":"Global heating is a late twentieth-century coinage; its exact first use is recorded only loosely, so the date is uncertain.","cn":"global heating 是 20 世纪晚期的造词；确切的最早使用只有粗略记载，因此首见年代存疑。"}]},"similar":{"note":{"en":"Group one holds forms of the same family that are easy to swap by mistake; group two holds words about warmth and air control with a different scope.","cn":"第一组是同一词族中极易误换的形式；第二组是涉及温暖与空气调节、范围不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"heat","ipa":"/hiːt/","tag":"the noun or verb","definition":"The bare noun or verb for warmth itself; heating adds the suffix and names the process or the installation.","definitionCN":"指热本身的名词或动词原形；heating 加了后缀，指过程或设备。"},{"word":"heated","ipa":"/ˈhiːtɪd/","tag":"past participle","definition":"The participle or adjective meaning 'made warm' or 'emotionally intense', not the ongoing system.","definitionCN":"分词或形容词，意为「被加热的」或「情绪激烈的」，不是正在运行的供暖系统。"},{"word":"heater","ipa":"/ˈhiːtə/","tag":"device noun","definition":"A countable device that produces warmth, such as a room heater; heating is the system or process as a whole.","definitionCN":"可数的产热装置，如房间取暖器；heating 指整体系统或过程。"},{"word":"heathen","ipa":"/ˈhiːðn/","tag":"different root","definition":"An old word for a pagan, from Old English hǣthen; it only looks as if it belonged to the heat family.","definitionCN":"旧时指异教徒的词，来自古英语 hǣthen；只是看起来像属于 heat 词族。"}]},{"heading":"NEAR MEANING","entries":[{"word":"warming","ipa":"/ˈwɔːmɪŋ/","tag":"gentle rise","definition":"A gradual, often pleasant increase in temperature; heating is usually deliberate and mechanical.","definitionCN":"逐渐且常令人舒适的温度上升；heating 通常是有意为之、由设备完成的。"},{"word":"cooling","ipa":"/ˈkuːlɪŋ/","tag":"opposite process","definition":"The removal of heat, the mirror image of heating; the two are studied together in thermodynamics.","definitionCN":"移走热量，是 heating 的镜像过程；两者在热力学中一起研究。"},{"word":"ventilation","ipa":"/ˌventɪˈleɪʃn/","tag":"air movement","definition":"The supply of fresh air to a space; it may cool a room but does not itself generate heat.","definitionCN":"向空间供给新鲜空气；它可能让房间变凉，但本身不产生热。"},{"word":"insulation","ipa":"/ˌɪnsjuˈleɪʃn/","tag":"keeping heat in","definition":"Material that slows heat loss; it works with heating rather than replacing it.","definitionCN":"减缓热量散失的材料；它与供暖配合，而不是替代供暖。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real suffix, real compounds and real household collocations, not invented rhymes.","cn":"正常联想：真实的后缀、真实的复合词与真实的家庭搭配，而非编造的顺口溜。"},"normal":[{"en":"heat + -ing: the suffix turns the action into a noun, exactly as in cooling and warming.","cn":"heat + -ing：后缀把动作变成名词，与 cooling、warming 完全一样。"},{"en":"Household phrases mark the system sense: central heating, heating system, heating bill.","cn":"家庭搭配标出系统义：集中供暖、供暖系统、供暖账单。"},{"en":"The same family runs heat, heated, heater, heating.","cn":"同一词族包括 heat、heated、heater、heating。"},{"en":"Global heating is the climate variant of global warming, chosen to stress human cause.","cn":"global heating 是 global warming 的气候变体，选它为了强调人为原因。"},{"en":"The heating comes on and goes off with the thermostat, like a switchable noun.","cn":"暖气随温控器开合，就像这个可切换的名词。"}],"abstract":[{"en":"Picture a metal radiator ticking as it expands, the sound of a house waking up.","cn":"想象金属暖气片受热膨胀时发出轻响，那是一栋房子醒来的声音。"},{"en":"Picture a blanket of warm air settling over a room while frost climbs the window.","cn":"想象一层暖空气落满房间，而霜正爬满窗户。"},{"en":"Picture a kettle's coil turning from grey to orange, doing nothing but making warmth.","cn":"想象水壶的线圈从灰变橙，只做一件事：制造温暖。"}]},"examples":[{"en":"They turned the heating down before leaving for the holidays.","cn":"出门度假前他们把暖气调低了。"},{"en":"Slow heating preserves the flavour of the sauce.","cn":"缓慢加热能保住酱汁的风味。"},{"en":"The new building uses solar heating instead of gas.","cn":"这栋新楼用太阳能供暖，而不是燃气。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「热厅」——把大厅热起来，靠的就是供暖","word":"heating"},"root":"英语本族构词：heat（古英语 hǣtu，由 hāt「热的」构成）加日耳曼语动作后缀 -ing。表示「供暖系统」的用法在 19 世纪集中供暖普及后固定下来；global heating 为 20 世纪晚期造词，最早书证年代存疑。无拉丁语来源。","sensesIntro":{"en":"Eight senses follow one line: the act of warming something is first a process, then the equipment that performs it, then its cost, its industrial and laboratory forms, its climate scale and finally its use as a modifier.","cn":"八个义项沿一条线索展开：加热先是过程，然后是执行它的设备、它的开销，再到工业与实验室形态、气候尺度，最后作定语使用。"},"semanticMap":{"core":{"en":"CORE IMAGE: a radiator warming a cold room while frost covers the window.","cn":"核心意象：暖气片把冷屋子烘暖，窗上结着霜。"},"chain":["PROCESS OF WARMING","INSTALLED SYSTEM","RUNNING COST","GLOBAL SCALE","INDUSTRIAL USE","LABORATORY USE"],"branches":[{"senses":"01 · 03","en":"SYSTEM AND BILL: once the installation is called heating, its running cost takes the same name.","cn":"系统与账单：设备一旦叫作 heating，运行开销也沿用同名。"},{"senses":"02 · 08","en":"PURE PROCESS: both the general act and the laboratory version name only a controlled rise in temperature.","cn":"纯过程：一般动作与实验室用法都只指受控升温。"},{"senses":"04","en":"PLANETARY SCALE: the same word is stretched to the whole climate system.","cn":"行星尺度：同一个词被扩展到整个气候系统。"},{"senses":"05 · 06","en":"INDUSTRY AND PARTS: furnaces and glowing elements are the technical face of the process.","cn":"工业与部件：炉窑与发光的元件是这一过程的技术面目。"},{"senses":"07","en":"MODIFIER: as an adjective the word simply marks a device whose job is warmth.","cn":"定语：作形容词时只标明某装置的职责是供热。"}]},"affixes":{"intro":{"en":"Heating is heat plus the productive suffix -ing; the suffix and the root both recur across the language.","cn":"heating 是 heat 加能产后缀 -ing；词根与后缀在英语中反复出现。"},"latinIntro":{"en":"Both parts are Germanic, so there are no Latin cognates to list; Latin calefactio is only a semantic equivalent.","cn":"两个成分都属日耳曼语，因此没有拉丁同族词可列；拉丁语 calefactio 只是语义对应词。"},"items":[{"word":"-ing","structure":"-ing (Germanic suffix forming nouns of action)","meaning":"the act or process of doing something","meaningCN":"做某事的动作或过程","example":"Cooling follows heating in the cycle.","exampleCN":"在这个循环里，冷却跟在加热之后。"},{"word":"heat","structure":"heat (native noun and verb)","meaning":"warmth; to make warm","meaningCN":"热；使变热","example":"Heat the plate before serving.","exampleCN":"上桌前把盘子热一下。"},{"word":"heated","structure":"heat + -ed (past participle)","meaning":"made warm","meaningCN":"被加热的","example":"The heated pool stays open all winter.","exampleCN":"温水泳池整个冬天都开放。"},{"word":"heater","structure":"heat + -er (agent or device)","meaning":"a device that warms","meaningCN":"加热装置","example":"The heater hummed beside the desk.","exampleCN":"取暖器在桌边嗡嗡作响。"},{"word":"reheating","structure":"re- 'again' + heating","meaning":"warming food a second time","meaningCN":"把食物再次加热","example":"Reheating rice can dry it out.","exampleCN":"米饭重新加热会变干。"},{"word":"preheating","structure":"pre- 'before' + heating","meaning":"warming something in advance","meaningCN":"提前加热","example":"Preheating the mould prevents cracks.","exampleCN":"预热模具可以防止开裂。"},{"word":"overheating","structure":"over- 'too much' + heating","meaning":"heating beyond a safe level","meaningCN":"加热过度","example":"Overheating ruined the bearing.","exampleCN":"过热损坏了轴承。"},{"word":"heating element","structure":"heating + element (compound noun)","meaning":"the part that produces heat","meaningCN":"产生热的部件","example":"The heating element needs replacing.","exampleCN":"加热元件需要更换。"}],"latinEntries":[]}},{"word":"cooling","ipa_uk":"/ˈkuːlɪŋ/","ipa_us":"/ˈkuːlɪŋ/","definition_zh":"冷却；降温；冷却系统；冷却的；使凉爽的","definition_en":"the process or system of removing heat and making something cooler","core_image":"刚出炉的蛋糕放在铁架上，白色的热气一缕缕升起又散开，表面慢慢变凉","scene":"夏天的厨房里，厨师把刚出炉的蛋糕放在架子上，说 Let the cake go through slow cooling before you cut it.","sceneCN":"这里 cooling 指「热量被移走、温度下降的过程」（第 1 个义项：物体把热散给周围空气而逐渐变凉）；句意为让蛋糕慢慢冷却后再切。图中可辨识物件：蛋糕、铁架、上升的热气、切刀。","pos":[{"tag":"n.","zh":"冷却；降温；冷却系统（不可数）"},{"tag":"adj.","zh":"冷却的；使凉爽的"}],"collocations":[{"phrase":"cooling system","zh":"冷却系统"},{"phrase":"cooling tower","zh":"冷却塔"},{"phrase":"cool down","zh":"冷却下来；冷静下来"},{"phrase":"cooling effect","zh":"冷却效果"},{"phrase":"evaporative cooling","zh":"蒸发冷却"},{"phrase":"cooling-off period","zh":"冷静期"}],"forms":[{"label":"名词（不可数，通常无复数）","form":"cooling"},{"label":"形容词","form":"cooling"},{"label":"动词（cool 的现在分词）","form":"cooling"},{"label":"原形（形容词或动词）","form":"cool"},{"label":"比较级","form":"cooler"},{"label":"最高级","form":"coolest"}],"derivatives":[{"word":"cooler","pos":"n./adj.","zh":"冷却器；冷藏箱 / 更凉的"},{"word":"coolant","pos":"n.","zh":"冷却液；冷却剂"},{"word":"cooled","pos":"adj.","zh":"已冷却的"},{"word":"overcooling","pos":"n.","zh":"过度冷却"},{"word":"precooling","pos":"n.","zh":"预冷却"}],"senses":[{"no":"01","title":"The removal of heat","titleCN":"移走热量的冷却过程","definition":"the process by which heat is taken away from a body, so that its temperature falls","definitionCN":"热量从物体被带走、使其温度下降的过程","example":"Rapid cooling can harden steel unevenly.","exampleCN":"快速冷却可能使钢材硬化不均匀。","why":"Cooling is the plain verbal noun of cool, and its core is simply the reverse of heating.","whyCN":"cooling 是 cool 的普通动词名词化，其核心不过是 heating 的反向过程。"},{"no":"02","title":"An installed cooling system","titleCN":"冷却系统、冷却设备","definition":"the pumps, pipes and fans that keep an engine, reactor or building within a safe temperature","definitionCN":"使发动机、反应堆或建筑维持在安全温度内的泵、管道与风扇","example":"The reactor shut down when the cooling stopped working.","exampleCN":"冷却系统停止工作时，反应堆自动停堆。","why":"As with heating, the action word became the name of the permanent installation that performs it.","whyCN":"与 heating 一样，表示动作的词变成了执行该动作的常设设备之名。"},{"no":"03","title":"Letting food cool","titleCN":"食物放凉","definition":"the stage in cooking when hot food is left to lose heat before being cut, stored or served","definitionCN":"烹饪中让热食先散掉热量、再切、存放或上桌的阶段","example":"Cooling on a wire rack keeps the bread crust crisp.","exampleCN":"在网架上放凉能让面包外壳保持酥脆。","why":"The kitchen keeps the literal process sense: nothing is mechanical, the food simply gives its heat to the air.","whyCN":"厨房保留了字面过程义：没有机械，食物只是把热交给空气。"},{"no":"04","title":"Relief from hot weather","titleCN":"缓解暑热的凉意","definition":"a flow of air or shade that makes a hot place feel more comfortable","definitionCN":"使炎热场所变得舒适的气流或阴凉","example":"The evening cooling made the walk pleasant.","exampleCN":"傍晚的凉意让散步变得舒服。","why":"Here cooling names the pleasant result rather than a technical process, an everyday extension of the same idea.","whyCN":"这里的 cooling 指令人舒适的结果而非技术过程，是同一想法的日常延伸。"},{"no":"05","title":"Easing of tension","titleCN":"紧张关系的缓和","definition":"a reduction in anger, excitement or political tension","definitionCN":"愤怒、激动或政治紧张的减弱","example":"A week of cooling followed the angry exchange.","exampleCN":"激烈的交锋之后是一周的缓和。","why":"Hot feelings are pictured as heat, so cooling means letting the emotional temperature fall.","whyCN":"热烈的情绪被想象成热，因此 cooling 就是让情绪的温度降下来。"},{"no":"06","title":"Slowing of an economy","titleCN":"经济降温、增速放缓","definition":"a deliberate or natural slowdown in economic activity after a period of rapid growth","definitionCN":"快速增长之后经济活动有意或自然地放缓","example":"The report described a cooling in the housing market.","exampleCN":"报告描述了房地产市场的降温。","why":"Economists borrowed the temperature metaphor: an overheated market is one that needs cooling.","whyCN":"经济学家借用了温度比喻：过热的市场就是需要降温的市场。"},{"no":"07","title":"Cooling of the early universe","titleCN":"早期宇宙的冷却","definition":"the fall in temperature of the universe as it expanded, which allowed particles to combine","definitionCN":"宇宙膨胀时温度的下降，这一过程使粒子得以结合","example":"Cosmologists date the first atoms to a period of rapid cooling.","exampleCN":"宇宙学家把第一批原子的形成定位于一段快速冷却期。","why":"The physical process sense is scaled up to cosmology, where expansion itself does the cooling.","whyCN":"物理过程义被放大到宇宙学尺度，在那里膨胀本身就完成了冷却。"},{"no":"08","title":"Serving as a modifier","titleCN":"形容词：起冷却作用的","definition":"placed before a noun to describe a device, surface or period whose function is to lower temperature","definitionCN":"置于名词前，说明某装置、表面或时段的功用是降温","example":"A cooling fan kept the processor from slowing down.","exampleCN":"一个散热风扇让处理器不至于降速。","why":"The participle keeps its verbal force, so a cooling fan is literally a fan for cooling.","whyCN":"分词保留了动词意味，因此 cooling fan 字面就是「用来冷却的风扇」。"}],"etymology":{"intro":{"en":"Cooling is the native adjective and verb cool plus the Germanic suffix -ing. The root is shared with cold, and Latin has genuine cognates such as gelu 'frost', though they are parallels rather than sources.","cn":"cooling 是本族形容词兼动词 cool 加日耳曼后缀 -ing。这个词根与 cold 共享，拉丁语也有真正的同源词如 gelu「霜」，但它们只是平行同源，不是来源。"},"items":[{"era":"OLD ENGLISH CŌL","en":"Cōl meant 'not warm, moderately cold' and also 'calm'; the verb cēlan 'to make cool' stood beside it.","cn":"cōl 意为「不暖的、微冷的」，也指「平静的」；旁边有动词 cēlan「使变冷」。"},{"era":"GERMANIC *KOLUZ","en":"The adjective goes back to a Germanic form reconstructed as *koluz, the source of Dutch koel and German kühl.","cn":"这个形容词上溯到重构的日耳曼形式 *koluz，也是荷兰语 koel 与德语 kühl 的来源。"},{"era":"INDO-EUROPEAN *GEL-","en":"The deeper root is usually reconstructed as *gel- 'cold', which also underlies English cold and Latin gelu; all such forms are reconstructions.","cn":"更深的词根通常重构为 *gel-「冷」，它也是英语 cold 与拉丁语 gelu 的基础；这类形式均为重构。"},{"era":"SUFFIX -ING","en":"The Germanic suffix -ing turns the verb into a noun of action, giving cooling the sense 'the act of making cool'.","cn":"日耳曼后缀 -ing 把动词变成动作名词，使 cooling 获得「使变凉的动作」这一意思。"},{"era":"TECHNICAL AND FIGURATIVE SENSES","en":"The engineering sense belongs to the industrial age, while the economic and emotional senses are later still; their exact first dates are uncertain.","cn":"工程义属于工业时代，经济义与情绪义更晚；它们的确切首见年代不确定。"}]},"similar":{"note":{"en":"Group one holds forms built on the same cool root that are easily confused; group two holds other ways of lowering temperature with a different mechanism.","cn":"第一组是同出 cool 词根、容易混淆的形式；第二组是机制不同、同样降低温度的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cool","ipa":"/kuːl/","tag":"base form","definition":"The bare adjective or verb: moderately cold, or to make something less warm.","definitionCN":"形容词或动词原形：微冷的，或使某物不那么热。"},{"word":"cooler","ipa":"/ˈkuːlə/","tag":"comparative or device","definition":"Either the comparative of cool or a countable container or device that keeps things cold.","definitionCN":"既可是 cool 的比较级，也可是可数的保冷容器或装置。"},{"word":"coolant","ipa":"/ˈkuːlənt/","tag":"substance, not process","definition":"A fluid that carries heat away; the -ant suffix names the substance, while cooling names the process.","definitionCN":"把热带走的流体；-ant 后缀指物质，而 cooling 指过程。"},{"word":"cold","ipa":"/kəʊld/","tag":"related but distinct","definition":"A different formation from the same deep root, meaning 'very low temperature'; it is not the source of cooling.","definitionCN":"同一深层词根的另一构词形式，意为「低温」；它不是 cooling 的来源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"refrigeration","ipa":"/rɪˌfrɪdʒəˈreɪʃn/","tag":"active chilling","definition":"Cooling by machine to a low temperature for storage; cooling alone can be passive and mild.","definitionCN":"用机器把温度降到很低以便储存；cooling 本身可以是被动而温和的。"},{"word":"chilling","ipa":"/ˈtʃɪlɪŋ/","tag":"strong cooling","definition":"Making something noticeably cold, often quickly; it is more forceful than ordinary cooling.","definitionCN":"使某物明显变冷，往往很快；比一般的 cooling 更强。"},{"word":"freezing","ipa":"/ˈfriːzɪŋ/","tag":"to the solid point","definition":"Cooling a liquid until it becomes solid; it is the extreme end of the cooling range.","definitionCN":"把液体冷却到凝固；是冷却范围的极端一端。"},{"word":"ventilation","ipa":"/ˌventɪˈleɪʃn/","tag":"air exchange","definition":"Supplying fresh air to a space; it can cool a room but its primary purpose is air quality.","definitionCN":"向空间供给新鲜空气；它能降温，但首要目的是空气质量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Germanic root, real compounds and real everyday collocations, not invented rhymes.","cn":"正常联想：真实的日耳曼词根、真实复合词与真实日常搭配，而非编造的顺口溜。"},"normal":[{"en":"cool + -ing: the suffix makes the action a noun, as in heating and warming.","cn":"cool + -ing：后缀把动作变成名词，与 heating、warming 一样。"},{"en":"The root is shared with cold, and Latin gelu is a distant cognate rather than a source.","cn":"词根与 cold 共享，拉丁语 gelu 是远亲同源词而非来源。"},{"en":"Engineering phrases mark the system sense: cooling system, cooling tower, coolant.","cn":"工程搭配标出系统义：冷却系统、冷却塔、冷却液。"},{"en":"The same family runs cool, cooler, coolest, cooled, cooling.","cn":"同一词族包括 cool、cooler、coolest、cooled、cooling。"},{"en":"A cooling-off period is literally time allowed for tempers to cool.","cn":"cooling-off period 字面上就是让火气冷却下来的一段时间。"}],"abstract":[{"en":"Picture a pie on a windowsill, steam curling away into the evening air.","cn":"想象窗台上的一块派，热气卷着散进傍晚的空气。"},{"en":"Picture two people who stop shouting and simply sit down, the room going quiet.","cn":"想象两个停止喊叫的人坐下来，房间安静下来。"},{"en":"Picture a white-hot metal bar dimming from orange to grey as it cools.","cn":"想象一根白热的金属棒从橙色暗成灰色。"}]},"examples":[{"en":"The engine's cooling kept the temperature below the limit.","cn":"发动机的冷却系统把温度控制在限值以下。"},{"en":"Leave the pie on the rack for an hour of cooling.","cn":"把派放在架子上冷却一小时。"},{"en":"A sea breeze brings welcome cooling to the coast.","cn":"海风给海岸带来宜人的凉意。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「酷冷」——把热气赶走，东西就凉下来了","word":"cooling"},"root":"英语本族构词：cool（古英语 cōl「微冷的、平静的」，动词 cēlan「使变冷」）加日耳曼动作后缀 -ing。形容词可上溯重构的日耳曼形式 *koluz，更深词根通常重构为 *gel-「冷」，与 cold 及拉丁语 gelu 同源；经济义与情绪义的首见年代不确定。","sensesIntro":{"en":"Eight senses follow one line: heat is removed, whether from a cake, a reactor, a room, a temper, a market or the early universe, and the word finally becomes a modifier for anything whose job is to remove it.","cn":"八个义项沿一条线索展开：热被移走，无论对象是蛋糕、反应堆、房间、火气、市场还是早期宇宙，最后这个词作定语指任何以移走热为职责的东西。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hot cake on a wire rack, steam rising and fading into the air.","cn":"核心意象：网架上的热蛋糕，热气升起又散入空气。"},"chain":["REMOVE HEAT","INSTALLED SYSTEM","FOOD COOLS","RELIEF FROM HEAT","TENSION FALLS","ECONOMY SLOWS"],"branches":[{"senses":"01 · 02","en":"PROCESS AND PLANT: the action and the equipment share one name, as with heating.","cn":"过程与设备：动作与设备共用一名，与 heating 一样。"},{"senses":"03 · 04","en":"EVERYDAY COOLNESS: food and evening air cool without any machine.","cn":"日常凉意：食物与傍晚的空气无需机器也会变凉。"},{"senses":"05 · 06","en":"METAPHORICAL TEMPERATURE: tempers and markets both cool down.","cn":"比喻温度：火气与市场都会降温。"},{"senses":"07","en":"COSMIC SCALE: expansion cools the whole universe.","cn":"宇宙尺度：膨胀让整个宇宙冷却。"},{"senses":"08","en":"MODIFIER: a cooling fan or tower is defined by its job of removing heat.","cn":"定语：散热风扇或冷却塔以移走热为职责。"}]},"affixes":{"intro":{"en":"Cooling is cool plus -ing, and the root also takes -er, -ant and prefix forms such as precool and overcool.","cn":"cooling 是 cool 加 -ing，这个词根还能加 -er、-ant，并与 pre-、over- 等前缀组合。"},"latinIntro":{"en":"The root is Germanic. Latin gelu 'frost' and gelidus 'cold' are genuine cognates from the same deep root, but they are parallels, not the source of the English word.","cn":"这个词根属日耳曼语。拉丁语 gelu「霜」与 gelidus「冷的」是同出深层词根的真实同源词，但它们是平行同源，不是英语词的来源。"},"items":[{"word":"-ing","structure":"-ing (Germanic suffix forming action nouns)","meaning":"the act or process of doing something","meaningCN":"做某事的动作或过程","example":"Heating and cooling balance in the cycle.","exampleCN":"加热与冷却在循环中相互平衡。"},{"word":"cooler","structure":"cool + -er (comparative or agent)","meaning":"more cool; or a container that keeps things cold","meaningCN":"更凉的；或保冷容器","example":"Put the bottles in the cooler.","exampleCN":"把瓶子放进冷藏箱。"},{"word":"coolant","structure":"cool + -ant (substance that performs an action)","meaning":"a fluid that carries heat away","meaningCN":"把热带走的流体","example":"Check the coolant level before the trip.","exampleCN":"出发前检查冷却液液位。"},{"word":"cooled","structure":"cool + -ed (past participle)","meaning":"made less warm","meaningCN":"已变凉的","example":"The cooled sample was weighed again.","exampleCN":"冷却后的样品又被称了一次。"},{"word":"precool","structure":"pre- 'before' + cool","meaning":"to cool something in advance","meaningCN":"预先冷却","example":"Precool the flask in an ice bath.","exampleCN":"把烧瓶放在冰浴里预冷。"},{"word":"overcool","structure":"over- 'too much' + cool","meaning":"to cool beyond the desired point","meaningCN":"冷却过度","example":"Overcooling makes the oil too viscous.","exampleCN":"过度冷却会让油变得太黏。"},{"word":"cooling tower","structure":"cooling + tower (compound noun)","meaning":"a large structure that removes waste heat","meaningCN":"排出废热的大型构筑物","example":"Steam rose from the cooling tower.","exampleCN":"蒸汽从冷却塔升起。"},{"word":"cooling-off","structure":"cooling + off (compound modifier)","meaning":"a period allowed for emotions to settle","meaningCN":"让情绪平复的一段时间","example":"The contract has a ten-day cooling-off period.","exampleCN":"合同有十天的冷静期。"}],"latinEntries":[{"word":"gelu","structure":"gelu, gelus (n., fourth declension; cognate, not source)","meaning":"frost, cold","meaningCN":"霜；寒冷"},{"word":"gelidus","structure":"gelidus, gelida, gelidum (adj.; cognate, not source)","meaning":"ice-cold, frosty","meaningCN":"冰冷的；结霜的"}]}},{"word":"convection","ipa_uk":"/kənˈvekʃn/","ipa_us":"/kənˈvekʃən/","definition_zh":"对流；靠流体流动传递热量；对流环流","definition_en":"the transfer of heat by the movement of a fluid such as air or water","core_image":"锅底受热的水向上涌起，表面的冷水下沉，形成一圈不断滚动的环流","scene":"厨房里，热空气在烤箱内被风扇推着循环，厨师说 In a convection oven, moving air carries heat to every shelf.","sceneCN":"这里 convection 指「靠流体流动把热从一个地方带到另一个地方」（第 4 个义项：烤箱内用风扇制造强制对流，使各层受热均匀）；句意为在对流烤箱里，流动的空气把热送到每一层架子。图中可辨识物件：烤箱、风扇、热气流箭头、烤盘。","pos":[{"tag":"n.","zh":"对流；流体传热（不可数）"}],"collocations":[{"phrase":"convection oven","zh":"对流烤箱"},{"phrase":"convection current","zh":"对流环流"},{"phrase":"natural convection","zh":"自然对流"},{"phrase":"forced convection","zh":"强制对流"},{"phrase":"mantle convection","zh":"地幔对流"},{"phrase":"convection zone","zh":"对流层（恒星内部）"}],"forms":[{"label":"名词（不可数，通常无复数）","form":"convection"},{"label":"形容词","form":"convective"},{"label":"副词","form":"convectively"},{"label":"动词","form":"convect"},{"label":"名词（对流单体）","form":"convection cell"}],"derivatives":[{"word":"convective","pos":"adj.","zh":"对流的；与对流有关的"},{"word":"convect","pos":"v.","zh":"使对流；靠对流传递"},{"word":"convectional","pos":"adj.","zh":"对流性的（如对流雨）"},{"word":"convected","pos":"adj.","zh":"被对流带动的"}],"senses":[{"no":"01","title":"Heat carried by a moving fluid","titleCN":"流体流动带走热量的传热方式","definition":"heat transfer in which the heated fluid itself moves and carries thermal energy with it","definitionCN":"受热的流体本身发生移动，并把热能一起带走的传热方式","example":"Water at the bottom of the pot warms and rises by convection.","exampleCN":"锅底的水受热后靠对流上升。","why":"Latin convehere means 'to carry together', so convection is literally heat being carried along by a moving medium.","whyCN":"拉丁语 convehere 意为「一起搬运」，因此对流字面上就是热被流动的介质带着走。"},{"no":"02","title":"Rising air in the atmosphere","titleCN":"大气对流、上升气流","definition":"the vertical movement of warm, moist air that rises and cools, often forming clouds","definitionCN":"暖湿空气上升并冷却的垂直运动，常形成云","example":"Afternoon convection built a tall column of cloud over the hills.","exampleCN":"午后的对流在山丘上空堆起一根高高的云柱。","why":"The atmosphere is a fluid, so the same physical process is watched on a weather-chart scale.","whyCN":"大气也是流体，因此同一物理过程被放在天气图的尺度上观察。"},{"no":"03","title":"Slow flow inside the Earth","titleCN":"地幔对流","definition":"the very slow circulation of hot rock in the mantle that helps drive plate motion","definitionCN":"地幔中炽热岩石的极缓慢环流，它推动板块运动","example":"Mantle convection is too slow to see but strong enough to move continents.","exampleCN":"地幔对流慢到看不见，却强到足以移动大陆。","why":"The medium here is solid rock behaving like an extremely viscous fluid over geological time.","whyCN":"这里的介质是岩石，只是在漫长的地质时间里表现得像极黏稠的流体。"},{"no":"04","title":"Forced convection in appliances","titleCN":"设备中的强制对流","definition":"convection driven by a fan or pump rather than by temperature differences alone","definitionCN":"由风扇或泵而非单纯温差驱动的对流","example":"The convection oven finishes the roast in less time than a still oven.","exampleCN":"对流烤箱比普通静置烤箱更快把肉烤好。","why":"Adding a fan turns a natural tendency into an engineered process, but the name of the process stays the same.","whyCN":"加一个风扇把自然趋势变成工程过程，但过程的名称不变。"},{"no":"05","title":"A circulating loop of fluid","titleCN":"对流环流、循环流动","definition":"a closed loop in which warm fluid rises at one place and cool fluid sinks at another","definitionCN":"暖流体在一处上升、冷流体在另一处下沉所形成的闭合环路","example":"A convection current in the room kept the smoke moving toward the door.","exampleCN":"房间里的对流环流让烟一直朝门口飘。","why":"The loop is the visible shape the process takes, so the same word names the circulation and its cause.","whyCN":"这个环路是过程呈现出的可见形状，因此同一个词既指环流也指其成因。"},{"no":"06","title":"Rain produced by rising air","titleCN":"对流雨","definition":"heavy rain that falls when warm air rises quickly, cools and condenses in a tall cloud","definitionCN":"暖空气迅速上升、冷却并在高云中凝结后落下的大雨","example":"Convection brought a short, violent storm just after noon.","exampleCN":"对流在刚过正午时带来一场短促的暴雨。","why":"Meteorology names the rainfall after its cause, so convection stands for the whole convective weather event.","whyCN":"气象学以成因给降雨命名，因此 convection 也代表整个对流性天气事件。"},{"no":"07","title":"Figurative spread of feeling or ideas","titleCN":"比喻义：情绪或思想的涌动传播","definition":"the spreading of excitement, anger or ideas through a group as if carried by a rising current","definitionCN":"兴奋、愤怒或思想像被上升气流带着一样在群体中扩散","example":"A convection of rumour moved through the office before lunch.","exampleCN":"午饭前，一股谣言的暗流在办公室里涌动。","why":"The metaphor keeps the physics: something hot rises and carries other things with it.","whyCN":"这个比喻保留了物理内核：热的东西上升，并带走别的东西。"},{"no":"08","title":"The convective layer of a star","titleCN":"恒星内部的对流层","definition":"the outer region of a star where energy is carried outward by rising and sinking gas","definitionCN":"恒星外部由气体升降把能量向外输送的区域","example":"The Sun's convection zone churns plasma beneath the visible surface.","exampleCN":"太阳的对流层在可见表面之下翻搅着等离子体。","why":"Astrophysics applies the terrestrial fluid process to gas on a stellar scale.","whyCN":"天体物理学把地球上的流体过程套用到恒星尺度的气体上。"}],"etymology":{"intro":{"en":"Convection comes from Latin convehere 'to carry together', built on com- 'together' and vehere 'to carry'. The noun convectio existed in Latin, and English first used the word for conveying before it became a term of physics.","cn":"convection 来自拉丁语 convehere「一起搬运」，由 com-「一起」与 vehere「搬运」构成。拉丁语本有名词 convectio；英语最初用它表示「传送」，后来才成为物理术语。"},"items":[{"era":"LATIN VEHERE","en":"Vehere meant 'to carry, convey', with the past participle vectus; it is the source of vehicle and vector.","cn":"vehere 意为「搬运、运送」，过去分词为 vectus；它是 vehicle 与 vector 的来源。"},{"era":"LATIN CONVEHERE","en":"Com- 'together' plus vehere produced convehere 'to carry or bring together'.","cn":"com-「一起」加 vehere 构成 convehere「一起搬运、聚集」。"},{"era":"LATIN CONVECTIO","en":"The action noun convectio 'a bringing together, conveyance' supplied the shape of the English word.","cn":"动作名词 convectio「聚拢、运送」提供了英语词的形态。"},{"era":"ENGLISH SEVENTEENTH CENTURY","en":"English borrowed the word in the seventeenth century in the general sense of conveying; the physical sense developed later.","cn":"英语在 17 世纪借入这个词，泛指「传送」；物理义后来才发展出来。"},{"era":"SCIENTIFIC SENSE","en":"The heat-transfer sense belongs to the nineteenth century, when heat was studied as a fluid-like quantity; the exact first use is uncertain.","cn":"传热义属于 19 世纪，当时热被当作类流体来研究；确切的最早使用不确定。"}]},"similar":{"note":{"en":"Group one holds words that resemble convection in form but come from other roots; group two holds the other modes of heat transfer and related circulation terms.","cn":"第一组是形式相近但词根不同的词；第二组是其他传热方式与相关的环流词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"convention","ipa":"/kənˈvenʃn/","tag":"same prefix, other root","definition":"From Latin convenire 'to come together', built on venire 'to come', not vehere 'to carry'; it means a custom or a meeting.","definitionCN":"来自拉丁 convenire「聚到一起」，词根是 venire「来」而非 vehere「搬运」；意为惯例或会议。"},{"word":"conversion","ipa":"/kənˈvɜːʃn/","tag":"vertere, not vehere","definition":"From convertere 'to turn around', with the root vertere 'to turn'; it names a change of form or belief.","definitionCN":"来自 convertere「转向」，词根为 vertere「转」；指形式或信仰的改变。"},{"word":"convex","ipa":"/ˈkɒnveks/","tag":"different root","definition":"From convexus 'arched', with no carrying element at all; it describes a surface curving outward.","definitionCN":"来自 convexus「拱起的」，完全没有「搬运」成分；形容向外凸起的表面。"},{"word":"convey","ipa":"/kənˈveɪ/","tag":"shares vehere","definition":"Through Old French from Latin convehere: to carry something or to communicate an idea, but not the scientific process.","definitionCN":"经古法语来自拉丁 convehere：搬运某物或传达想法，但不是科学过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"conduction","ipa":"/kənˈdʌkʃn/","tag":"through contact","definition":"Heat passing through a solid by direct contact between particles, with no bulk movement of the material.","definitionCN":"热通过粒子间的直接接触穿过固体，物质本身不发生整体移动。"},{"word":"radiation","ipa":"/ˌreɪdiˈeɪʃn/","tag":"by waves","definition":"Heat travelling as electromagnetic waves, needing no medium at all.","definitionCN":"热以电磁波形式传播，完全不需要介质。"},{"word":"advection","ipa":"/ədˈvekʃn/","tag":"horizontal transport","definition":"The horizontal carrying of heat or moisture by wind; convection is mainly vertical, advection mainly horizontal.","definitionCN":"风把热或水汽水平搬运；对流主要是垂直的，平流主要是水平的。"},{"word":"circulation","ipa":"/ˌsɜːkjəˈleɪʃn/","tag":"the loop itself","definition":"The movement of a fluid around a closed path; it is the shape convection takes, not the heat-transfer mechanism.","definitionCN":"流体沿闭合路径的运动；它是对流呈现的形状，而非传热机制本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin morphemes, real compounds and real physics collocations, not invented rhymes.","cn":"正常联想：真实的拉丁构词成分、真实复合词与真实物理搭配，而非编造的顺口溜。"},"normal":[{"en":"con- 'together' + vehere 'carry': the fluid carries heat along with it.","cn":"con-「一起」+ vehere「搬运」：流体把热一起带走。"},{"en":"The same root appears in convey, vehicle and vector.","cn":"同一词根出现在 convey、vehicle 与 vector 中。"},{"en":"Physics pairs it with conduction and radiation as the three modes of heat transfer.","cn":"物理学把它与 conduction、radiation 并列为三种传热方式。"},{"en":"Fixed phrases mark the fields: convection oven, convection current, mantle convection.","cn":"固定搭配标出领域：对流烤箱、对流环流、地幔对流。"},{"en":"The adjective is convective and the verb is convect, both built on the same stem.","cn":"形容词是 convective，动词是 convect，都基于同一词干。"}],"abstract":[{"en":"Picture a pot of soup where the hot part climbs and the cool part dives, over and over.","cn":"想象一锅汤，热的部分往上爬，冷的部分往下沉，周而复始。"},{"en":"Picture a rumour rising in one office and drifting down into the next.","cn":"想象一则谣言在一间办公室升起，又飘进下一间。"},{"en":"Picture a slow stone river under the continents, moving a centimetre a year.","cn":"想象大陆之下一条缓慢的石河，一年只移动一厘米。"}]},"examples":[{"en":"Convection carries heat from the radiator to the far side of the room.","cn":"对流把热从暖气片带到房间的另一头。"},{"en":"The storm was fuelled by strong convection over warm water.","cn":"暖水面上强烈的对流给这场风暴提供了能量。"},{"en":"Geologists model mantle convection to explain continental drift.","cn":"地质学家模拟地幔对流来解释大陆漂移。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「一起背」——热和水汽一起被背着往上走，就是对流","word":"convection"},"root":"拉丁 convehere「一起搬运」= com-「一起」+ vehere「搬运、运送」，动作名词 convectio。英语 17 世纪借入时泛指「传送」，19 世纪才固定为传热术语；该物理义的最早书证不确定。","sensesIntro":{"en":"Eight senses follow one line: a moving fluid picks up heat and carries it away, whether in a pot, the sky, the mantle, an oven, a room, a storm, a crowd or a star.","cn":"八个义项沿一条线索展开：流动的流体带走热量，无论在锅里、天空、地幔、烤箱、房间、风暴、人群中还是恒星里。"},"semanticMap":{"core":{"en":"CORE IMAGE: warm water rising at the bottom of a pot while cooler water sinks.","cn":"核心意象：锅底的热水上升，较冷的水下沉。"},"chain":["FLUID CARRIES HEAT","AIR RISES","MANTLE FLOWS","FAN FORCES AIR","LOOP FORMS","CLOUD AND RAIN"],"branches":[{"senses":"01 · 05","en":"PROCESS AND LOOP: the same word names the carrying and the circulating shape it makes.","cn":"过程与环路：同一个词既指搬运，也指它形成的环流形状。"},{"senses":"02 · 06","en":"WEATHER: rising air builds cloud and then releases rain.","cn":"天气：上升的空气堆起云，随后落下雨。"},{"senses":"03 · 08","en":"DEEP AND HIGH: the process works in mantle rock and in stellar gas.","cn":"深处与高处：这一过程既发生在地幔岩石里，也发生在恒星气体里。"},{"senses":"04","en":"ENGINEERED AIR: a fan turns natural convection into a controlled oven process.","cn":"工程气流：风扇把自然对流变成可控的烤箱过程。"},{"senses":"07","en":"SOCIAL CURRENT: excitement and rumour rise and spread like warm air.","cn":"社会气流：兴奋与谣言像暖空气一样上升扩散。"}]},"affixes":{"intro":{"en":"Convection is a Latin prefix, root and suffix laid end to end: con- plus vehere plus -tion. The same pieces build convey and convection's scientific relatives.","cn":"convection 是拉丁前缀、词根与后缀依次相接：con- 加 vehere 加 -tion。相同的成分还构成 convey 与对流的相关科学词。"},"latinIntro":{"en":"Latin vehere gives a real family: vehere itself, the compound convehere, the action noun convectio, and the participle vectus.","cn":"拉丁 vehere 给出一个真实的词族：vehere 本身、复合词 convehere、动作名词 convectio 以及分词 vectus。"},"items":[{"word":"con-","structure":"com- (Latin prefix, 'together')","meaning":"together; with","meaningCN":"一起；共同","example":"The prefix joins the carrying action to a group.","exampleCN":"这个前缀把搬运动作收拢到一个整体里。"},{"word":"vehere","structure":"vehere (Latin verb, third conjugation)","meaning":"to carry, convey","meaningCN":"搬运；运送","example":"The root underlies vehicle and vector.","exampleCN":"这个词根是 vehicle 与 vector 的基础。"},{"word":"-tion","structure":"-tion (Latin suffix forming action nouns)","meaning":"the act or result of an action","meaningCN":"动作或其结果","example":"The suffix turns convect into the name of a process.","exampleCN":"这个后缀把 convect 变成过程之名。"},{"word":"convect","structure":"con- + vehere (back-formed verb)","meaning":"to move heat by fluid motion","meaningCN":"靠流体运动输送热量","example":"The fan convects warm air through the room.","exampleCN":"风扇让暖空气在房间里对流。"},{"word":"convective","structure":"convection + -ive (tending to)","meaning":"relating to convection","meaningCN":"对流的","example":"Convective clouds grow tall in the afternoon.","exampleCN":"对流的云在午后长得高大。"},{"word":"convectively","structure":"convective + -ly (in a manner)","meaning":"by means of convection","meaningCN":"以对流方式","example":"The layer is convectively unstable.","exampleCN":"这一层在对流上是不稳定的。"},{"word":"convectional","structure":"convection + -al (relating to)","meaning":"produced by convection, as of rainfall","meaningCN":"由对流产生的（如降雨）","example":"Convectional rain fell in the early afternoon.","exampleCN":"对流雨在午后早些时候落下。"},{"word":"convey","structure":"con- + vehere via Old French","meaning":"to carry or communicate","meaningCN":"搬运；传达","example":"The letter conveyed the news quietly.","exampleCN":"这封信平静地传达了消息。"}],"latinEntries":[{"word":"vehere","structure":"vehere, vexi, vectum (verb, third conjugation)","meaning":"to carry, convey","meaningCN":"搬运；运送"},{"word":"convehere","structure":"convehere, convexi, convectum (verb, third conjugation)","meaning":"to carry or bring together","meaningCN":"一起搬运；聚集"},{"word":"convectio","structure":"convectio, convectionis (f., third declension)","meaning":"a bringing together, conveyance","meaningCN":"聚拢；运送"},{"word":"vectus","structure":"vectus, vecta, vectum (perfect participle)","meaning":"carried, conveyed","meaningCN":"被搬运的；被运送的"}]}},{"word":"conduction","ipa_uk":"/kənˈdʌkʃn/","ipa_us":"/kənˈdʌkʃən/","definition_zh":"传导；热传导；导电；神经传导；（旧义）引导、管理","definition_en":"the movement of heat, electricity, sound or nerve signals through a material without the material itself moving","core_image":"一根金属棒的一端浸在热水里，另一端很快也变得烫手，热沿着棒身一路走过去","scene":"物理课上，学生把金属棒的一端放进热水，很快握住另一端的手也感到烫，老师说 Heat moves along the rod by conduction.","sceneCN":"这里 conduction 指「热在物质内部逐层传递、物质本身并不整体移动」（第 1 个义项：固体中的热传导）；句意为热沿着金属棒传导过来。图中可辨识物件：金属棒、热水杯、温度计、握住棒端的手。","pos":[{"tag":"n.","zh":"传导（热、电、声或神经冲动）；传导过程（不可数）"},{"tag":"n.","zh":"引导；管理（旧义，现代英语少用）"}],"collocations":[{"phrase":"heat conduction","zh":"热传导"},{"phrase":"electrical conduction","zh":"导电"},{"phrase":"thermal conduction","zh":"热传导"},{"phrase":"conduction band","zh":"导带"},{"phrase":"conduction electron","zh":"传导电子"},{"phrase":"nerve conduction","zh":"神经传导"}],"forms":[{"label":"名词（不可数，通常无复数）","form":"conduction"},{"label":"形容词","form":"conductive"},{"label":"名词（传导率）","form":"conductivity"},{"label":"动词","form":"conduct"},{"label":"名词（导体；指挥）","form":"conductor"}],"derivatives":[{"word":"conductive","pos":"adj.","zh":"导电的；导热的；有传导性的"},{"word":"conductivity","pos":"n.","zh":"传导率；导电性；导热性"},{"word":"conductor","pos":"n.","zh":"导体；指挥；售票员"},{"word":"conduct","pos":"v./n.","zh":"传导；进行；举止"},{"word":"conductance","pos":"n.","zh":"电导；传导能力"}],"senses":[{"no":"01","title":"Heat moving through a solid","titleCN":"固体中的热传导","definition":"the transfer of heat through a material by the vibration of particles, without the material moving as a whole","definitionCN":"热通过粒子的振动在材料内部传递，而材料整体并不移动","example":"Copper is used in cookware because its heat conduction is fast.","exampleCN":"铜被用于炊具，因为它的热传导很快。","why":"Latin conducere 'to lead along' gives the image of heat being led through the body of a material.","whyCN":"拉丁 conducere「沿着引导」给出一个意象：热被引导着穿过材料本身。"},{"no":"02","title":"Electric current through a material","titleCN":"导电","definition":"the flow of electric charge through a substance when a voltage is applied","definitionCN":"施加电压时电荷在物质中的流动","example":"The salt solution supports electrical conduction.","exampleCN":"盐溶液可以导电。","why":"Electricity was understood as a flow that is 'led' through a wire, so the same noun was reused.","whyCN":"电被理解为一种被「引导」通过导线的流动，于是沿用了同一个名词。"},{"no":"03","title":"Ionic conduction in solutions","titleCN":"溶液中的离子传导","definition":"charge transport by ions moving through a liquid or a solid electrolyte","definitionCN":"离子在液体或固体电解质中移动而完成的电荷输运","example":"Ionic conduction in the battery depends on how freely the ions move.","exampleCN":"电池中的离子传导取决于离子移动的自由程度。","why":"Here the carriers are whole ions rather than electrons, but the leading-through image is unchanged.","whyCN":"这里的载体是整个离子而非电子，但「引导穿过」的意象没有改变。"},{"no":"04","title":"Nerve signal conduction","titleCN":"神经冲动传导","definition":"the passage of an electrical impulse along a nerve fibre","definitionCN":"电冲动沿神经纤维的传递","example":"Damage to the sheath slows nerve conduction.","exampleCN":"髓鞘受损会减慢神经传导。","why":"Physiology borrowed the physics word because a signal also travels along a pathway without the pathway moving.","whyCN":"生理学借用了物理词，因为信号同样沿路径行进，而路径本身不动。"},{"no":"05","title":"Sound conduction","titleCN":"声音传导","definition":"the passing of sound vibrations through a solid, liquid or gas, especially through the ear","definitionCN":"声音振动通过固体、液体或气体传递，尤指经过耳部","example":"Bone conduction lets you hear a vibration through your skull.","exampleCN":"骨传导让你能通过颅骨听到振动。","why":"Vibration travelling through matter is another case of something being led along a medium.","whyCN":"振动穿过物质，同样是某物被沿着介质引导而行的情形。"},{"no":"06","title":"Leading or guidance","titleCN":"旧义：引导、管理","definition":"the act of leading, guiding or managing something, the earliest sense of the word in English","definitionCN":"引导、指导或管理某事的动作，这是该词进入英语时最早的意思","example":"The old text speaks of the conduction of a household.","exampleCN":"这份旧文献谈到对一个家庭的治理。","why":"The modern scientific senses all grow from this plain sense of leading: heat, charge and signals are all led along.","whyCN":"现代科学义都从「引导」这一朴素义生长出来：热、电荷与信号都是被引导着走的。"},{"no":"07","title":"Heat loss through a building","titleCN":"建筑围护结构的热传导","definition":"the rate at which heat passes through walls, windows and roofs into or out of a building","definitionCN":"热穿过墙体、窗户与屋顶进出建筑的速率","example":"Double glazing reduces conduction through the window.","exampleCN":"双层玻璃减少了通过窗户的热传导。","why":"Building science applies the solid-state process to the fabric of a house.","whyCN":"建筑科学把固体传热过程套用到房屋的围护结构上。"},{"no":"08","title":"Conduction in semiconductors","titleCN":"半导体中的传导","definition":"charge transport by electrons and holes in a material whose conductivity lies between a metal and an insulator","definitionCN":"在导电性介于金属与绝缘体之间的材料中，由电子与空穴完成的电荷输运","example":"Doping raises the conduction of silicon at room temperature.","exampleCN":"掺杂提高了硅在室温下的导电能力。","why":"The band model describes two kinds of carrier, but both are still conducted through the lattice.","whyCN":"能带模型描述了两种载流子，但两者都仍是穿过晶格被传导的。"}],"etymology":{"intro":{"en":"Conduction comes from Latin conducere 'to lead or bring together', built on com- 'together' and ducere 'to lead'. The word entered English first as 'guidance' and only later became a term for heat, charge and nerve signals.","cn":"conduction 来自拉丁 conducere「引导、聚拢」，由 com-「一起」与 ducere「引导」构成。它进入英语时先表示「引导」，后来才成为热、电荷与神经信号方面的术语。"},"items":[{"era":"LATIN DUCERE","en":"Ducere meant 'to lead, draw, guide', with the past participle ductus; it also gives duct, duke and induce.","cn":"ducere 意为「引导、拉、带领」，过去分词为 ductus；它还给出 duct、duke 与 induce。"},{"era":"LATIN CONDUCERE","en":"Com- 'together' plus ducere produced conducere 'to lead together, bring along, hire'.","cn":"com-「一起」加 ducere 构成 conducere「引导到一起、带来、雇用」。"},{"era":"LATIN CONDUCTIO","en":"The action noun conductio 'a leading, hiring' supplied the form that English borrowed.","cn":"动作名词 conductio「引导、雇用」提供了英语借入的形式。"},{"era":"MIDDLE ENGLISH","en":"In Middle English conduction meant leading or guidance; the scientific senses are much later additions.","cn":"在中古英语中，conduction 意为引导或管理；科学义是后来才加上的。"},{"era":"SCIENTIFIC SENSE","en":"The heat and electricity senses date from the nineteenth century; the exact first use in each field is uncertain.","cn":"热与电的义项始于 19 世纪；各领域确切的最早使用不确定。"}]},"similar":{"note":{"en":"Group one holds forms of the same Latin root that are easily confused; group two holds the other heat-transfer modes and related transport words.","cn":"第一组是同出拉丁词根、容易混淆的形式；第二组是其他传热方式与相关的输运词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conduct","ipa":"/kənˈdʌkt/","tag":"verb or behaviour noun","definition":"The verb meaning to lead, carry out or transmit, and the noun for a person's behaviour; conduction is only the process noun.","definitionCN":"动词意为引导、进行或传输，名词指人的行为；conduction 只是表示过程的名词。"},{"word":"conductor","ipa":"/kənˈdʌktə/","tag":"the thing that conducts","definition":"A material or person that conducts heat, electricity, sound or an orchestra; it names the agent, not the process.","definitionCN":"传导热、电、声的材料，或指挥乐队的人；它指施动者而非过程。"},{"word":"conductivity","ipa":"/ˌkɒndʌkˈtɪvəti/","tag":"measured property","definition":"The degree to which a material conducts heat or electricity, a quantity rather than the flow itself.","definitionCN":"材料传导热或电的程度，是一个量，而不是流动本身。"},{"word":"conduit","ipa":"/ˈkɒndjuɪt/","tag":"channel noun","definition":"A pipe or channel through which something passes, from the same root but naming the physical channel.","definitionCN":"让某物通过的管道或通道，同出该词根，但指实物通道。"}]},{"heading":"NEAR MEANING","entries":[{"word":"convection","ipa":"/kənˈvekʃn/","tag":"fluid carries heat","definition":"Heat transfer by a moving fluid; in conduction the material stays put while energy passes through it.","definitionCN":"由流动的流体传热；传导中材料本身不动，能量穿过它。"},{"word":"radiation","ipa":"/ˌreɪdiˈeɪʃn/","tag":"waves, no medium","definition":"Heat transfer by electromagnetic waves, needing no material medium at all.","definitionCN":"以电磁波传热，完全不需要物质介质。"},{"word":"transmission","ipa":"/trænzˈmɪʃn/","tag":"general passing","definition":"The general passing of energy, signals or disease from one place to another, without specifying the mechanism.","definitionCN":"能量、信号或疾病从一处传到另一处的泛称，不指明机制。"},{"word":"diffusion","ipa":"/dɪˈfjuːʒn/","tag":"particle spreading","definition":"The spreading of particles from high to low concentration; it moves matter itself rather than leading energy through a fixed lattice.","definitionCN":"粒子由高浓度向低浓度散开；它移动的是物质本身，而非让能量穿过固定晶格。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin root, a real word family and real physics collocations, not invented rhymes.","cn":"正常联想：真实的拉丁词根、真实词族与真实物理搭配，而非编造的顺口溜。"},"normal":[{"en":"con- 'together' + ducere 'lead': energy is led through the material.","cn":"con-「一起」+ ducere「引导」：能量被引导穿过材料。"},{"en":"The root family runs conduct, conductor, conductivity, conduit.","cn":"词根词族包括 conduct、conductor、conductivity、conduit。"},{"en":"Physics pairs it with convection and radiation as the three modes of heat transfer.","cn":"物理学把它与 convection、radiation 并列为三种传热方式。"},{"en":"Fixed phrases mark the fields: heat conduction, electrical conduction, conduction band.","cn":"固定搭配标出领域：热传导、导电、导带。"},{"en":"The oldest sense is guidance; every later sense keeps the idea of something being led along.","cn":"最古老的义项是引导；后来每个义项都保留「某物被引导着前行」的意思。"}],"abstract":[{"en":"Picture a line of people passing buckets along until the last one gets water.","cn":"想象一排人依次传递水桶，直到最后一个人接到水。"},{"en":"Picture a whisper travelling down a row of seated students without anyone moving seats.","cn":"想象一句耳语沿一排坐着的学生传下去，没有人换座位。"},{"en":"Picture a copper spoon in a hot pot, its handle warming long before it is touched.","cn":"想象热锅里的铜勺，还没碰到，勺柄就已经暖了。"}]},"examples":[{"en":"Silver has excellent conduction, which is why it is used in some contacts.","cn":"银的导电性极好，因此被用于某些触点。"},{"en":"Thick insulation slows conduction through the walls.","cn":"厚保温层减缓了通过墙体的热传导。"},{"en":"The doctor ordered a test of nerve conduction in the arm.","cn":"医生安排了手臂神经传导的检查。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「肯导」——热肯沿着棒子一路导过去，就是传导","word":"conduction"},"root":"拉丁 conducere「引导、聚拢」= com-「一起」+ ducere「引导」，动作名词 conductio。英语先有「引导、管理」义，热、电、神经等科学义始于 19 世纪；各领域最早书证不确定。","sensesIntro":{"en":"Eight senses follow one line: something is led through a medium that itself stays still, whether that something is heat, charge, an ion, a nerve impulse, sound, or the older idea of guidance itself.","cn":"八个义项沿一条线索展开：某物被引导穿过本身不动的介质，无论那是热、电荷、离子、神经冲动、声音，还是更早的「引导」这一本义。"},"semanticMap":{"core":{"en":"CORE IMAGE: heat walking along a metal rod while the rod stays where it is.","cn":"核心意象：热沿着金属棒走过去，而棒子本身停在原处。"},"chain":["LEAD ALONG","HEAT THROUGH SOLID","CHARGE THROUGH METAL","IONS IN SOLUTION","NERVE IMPULSE","SOUND VIBRATION"],"branches":[{"senses":"01 · 07","en":"HEAT IN MATTER: the same process is measured in a rod and in a house wall.","cn":"物质中的热：同一过程既在金属棒上测量，也在房屋墙体上测量。"},{"senses":"02 · 03","en":"CHARGE CARRIERS: electrons and ions both conduct, though the carriers differ.","cn":"电荷载体：电子与离子都能传导，只是载体不同。"},{"senses":"04 · 05","en":"LIVING AND VIBRATING SIGNALS: nerves and sound repeat the same leading-through pattern.","cn":"生命与振动信号：神经与声音重复同样的引导模式。"},{"senses":"06","en":"THE ORIGINAL SENSE: guidance is the plain meaning from which the science grew.","cn":"本义：引导是科学义生长出来的朴素含义。"},{"senses":"08","en":"SEMICONDUCTORS: two kinds of carrier share one lattice.","cn":"半导体：两种载流子共用一套晶格。"}]},"affixes":{"intro":{"en":"Conduction is con- plus the root duc- plus -tion; the same three pieces build a large and very common family.","cn":"conduction 是 con- 加词根 duc- 再加 -tion；同样三块构成一个庞大而常见的词族。"},"latinIntro":{"en":"The Latin family is well recorded: ducere 'to lead', conducere 'to lead together', conductio 'a leading', and the participle ductus.","cn":"拉丁词族记载完整：ducere「引导」、conducere「引导到一起」、conductio「引导」以及分词 ductus。"},"items":[{"word":"con-","structure":"com- (Latin prefix, 'together')","meaning":"together; with","meaningCN":"一起；共同","example":"The prefix gathers the leading into one movement.","exampleCN":"这个前缀把引导收束为一次整体运动。"},{"word":"duc-","structure":"ducere (Latin verb, 'to lead')","meaning":"to lead, draw, guide","meaningCN":"引导；带领；拉","example":"The root also appears in induce and duct.","exampleCN":"这个词根也出现在 induce 与 duct 中。"},{"word":"-tion","structure":"-tion (Latin suffix forming action nouns)","meaning":"the act or result of an action","meaningCN":"动作或其结果","example":"The suffix turns the verb into the name of a process.","exampleCN":"这个后缀把动词变成过程之名。"},{"word":"conduct","structure":"con- + ducere (verb and noun)","meaning":"to lead, carry out or transmit","meaningCN":"引导；进行；传输","example":"Copper conducts electricity well.","exampleCN":"铜导电良好。"},{"word":"conductor","structure":"conduct + -or (one who or that which acts)","meaning":"a material that transmits heat or electricity","meaningCN":"传导热或电的材料","example":"A conductor carries charge to the ground.","exampleCN":"导体把电荷送到地面。"},{"word":"conductive","structure":"conduct + -ive (having the quality of)","meaning":"able to conduct heat or electricity","meaningCN":"能导热或导电的","example":"The gel is conductive and harmless to skin.","exampleCN":"这种凝胶导电且对皮肤无害。"},{"word":"conductivity","structure":"conductive + -ity (quality noun)","meaning":"the measured ability to conduct","meaningCN":"传导能力的量度","example":"Copper's conductivity is higher than iron's.","exampleCN":"铜的导电率高于铁。"},{"word":"conduit","structure":"con- + ductus (channel noun)","meaning":"a pipe or channel for passing something","meaningCN":"输送某物的管道或通道","example":"Water ran through the stone conduit.","exampleCN":"水从石制渠道中流过。"},{"word":"conductance","structure":"conduct + -ance (state or measure)","meaning":"the ease with which a component conducts","meaningCN":"元件导电的容易程度","example":"The circuit's conductance fell as it warmed.","exampleCN":"电路升温时其电导下降。"}],"latinEntries":[{"word":"ducere","structure":"ducere, duxi, ductum (verb, third conjugation)","meaning":"to lead, draw, guide","meaningCN":"引导；带领；拉"},{"word":"conducere","structure":"conducere, conduxi, conductum (verb, third conjugation)","meaning":"to lead together, bring along, hire","meaningCN":"引导到一起；带来；雇用"},{"word":"conductio","structure":"conductio, conductionis (f., third declension)","meaning":"a leading, hiring","meaningCN":"引导；雇用"},{"word":"ductus","structure":"ductus, ductus (m., fourth declension)","meaning":"a leading, channel","meaningCN":"引导；通道"}]}},{"word":"air current","ipa_uk":"/ˈeə ˈkʌrənt/","ipa_us":"/ˈer ˈkɜːrənt/","definition_zh":"气流；空气的流动；上升或下沉的气流；思潮（比喻义）","definition_en":"a moving stream of air, especially one that can be felt or that carries heat, moisture or particles","core_image":"门缝下钻进来的一线冷空气，贴着地面滑行，把桌上的薄纸轻轻掀起","scene":"清晨的走廊里，一张薄纸被看不见的流动推着滑过桌面，学生说 A cold air current slid under the door and lifted the paper.","sceneCN":"这里 air current 指「一股正在流动的空气」（第 1 个义项：可以感觉到、并能带动轻物的空气流）；句意为一股冷气流从门缝下钻进来，把纸掀了起来。图中可辨识物件：门缝、薄纸、桌面、气流箭头。","pos":[{"tag":"n.","zh":"气流；空气流（可数，复数 air currents）"}],"collocations":[{"phrase":"rising air current","zh":"上升气流"},{"phrase":"cold air current","zh":"冷气流"},{"phrase":"warm air current","zh":"暖气流"},{"phrase":"upper-level air current","zh":"高空气流"},{"phrase":"air current pattern","zh":"气流型态"},{"phrase":"a steady air current","zh":"一股稳定的气流"}],"forms":[{"label":"复数","form":"air currents"},{"label":"相关名词（空气）","form":"air"},{"label":"相关名词（水流、电流）","form":"current"},{"label":"相关复合词（空气流）","form":"airflow"},{"label":"相关形容词（通风的）","form":"airy"}],"derivatives":[{"word":"current","pos":"n./adj.","zh":"流；水流；电流 / 当前的"},{"word":"currently","pos":"adv.","zh":"目前；当前（由「当前」义而来）"},{"word":"airflow","pos":"n.","zh":"空气流；气流流量"},{"word":"airy","pos":"adj.","zh":"通风的；轻盈的"},{"word":"airless","pos":"adj.","zh":"无空气的；闷不透风的"}],"senses":[{"no":"01","title":"A moving stream of air","titleCN":"流动的空气、气流","definition":"a body of air that moves from one place to another and can be felt or can move light objects","definitionCN":"从一处移向另一处的空气，可以被感觉到，也能推动轻物","example":"A thin air current made the curtain sway by the open window.","exampleCN":"一股细微的气流让窗边的窗帘轻轻摆动。","why":"Current means 'running', so an air current is literally air that is running from place to place.","whyCN":"current 意为「奔跑的」，因此 air current 字面上就是「正在跑的空气」。"},{"no":"02","title":"A rising current","titleCN":"上升气流","definition":"a column of warm air that rises because it is lighter than the air around it","definitionCN":"因比周围空气轻而上升的一柱暖空气","example":"Gliders circle inside a rising air current to gain height.","exampleCN":"滑翔机在上升气流里盘旋以获取高度。","why":"The same phrase covers any moving air; meteorology adds the direction, which is upward for a thermal.","whyCN":"同一短语可指任何流动的空气；气象学加上方向，热气流的上升方向便是向上。"},{"no":"03","title":"A descending current","titleCN":"下沉气流","definition":"a flow of air that sinks toward the ground, often cool and dry","definitionCN":"向地面下沉的空气流，通常干而凉","example":"The descending air current cleared the sky behind the storm.","exampleCN":"下沉气流把风暴后方的天空清空了。","why":"Dense, cooled air falls, so meteorologists name the downward branch of a circulation an air current too.","whyCN":"变冷变密的空气下沉，气象学家便把环流的下行分支同样称为气流。"},{"no":"04","title":"A local horizontal flow","titleCN":"局地水平气流","definition":"a small-scale flow such as a sea breeze or a valley wind that runs roughly parallel to the ground","definitionCN":"海风或谷风这类大致沿地面平行的局部流动","example":"A sea air current cools the town every summer afternoon.","exampleCN":"每天夏日午后，一股海风气流让小镇凉快下来。","why":"Local circulations complete their loop horizontally, so the general phrase is used with a direction word.","whyCN":"局地环流在地面附近水平完成循环，因此这个泛称常与方向词连用。"},{"no":"05","title":"Indoor air movement","titleCN":"室内的空气流动","definition":"air set in motion inside a room by a fan, an open window or a temperature difference","definitionCN":"由风扇、开窗或温差在房间内带动的空气","example":"A weak air current from the vent kept the room from feeling stale.","exampleCN":"通风口送出的微弱气流让房间不至于闷。","why":"Buildings are small fluid systems, so the same two words describe ventilation on a room scale.","whyCN":"建筑是小尺度的流体系统，因此同样的两个词也描述房间尺度的通风。"},{"no":"06","title":"A high-altitude current","titleCN":"高空气流、急流","definition":"a fast, narrow band of air in the upper atmosphere that steers weather systems","definitionCN":"高层大气中快速而狭窄的空气带，它引导天气系统移动","example":"Aircraft save fuel by riding a strong high air current eastward.","exampleCN":"飞机借助强劲的高空气流向东飞行以节省燃料。","why":"At altitude the same moving air becomes a jet, and the general compound still serves as the plain description.","whyCN":"在高空，同样的流动空气变成急流，而这个泛称仍可作朴素描述。"},{"no":"07","title":"Turbulence in flight","titleCN":"飞行中遇到的气流颠簸","definition":"an uneven flow of air that shakes an aircraft as it passes through","definitionCN":"飞机穿过时使其颠簸的不均匀空气流","example":"The seatbelt sign came on as the plane hit a rough air current.","exampleCN":"飞机遇到强烈气流时，系好安全带指示灯亮了。","why":"For passengers the current is felt as a jolt, so the physical phrase also names the experience.","whyCN":"对乘客来说，气流表现为一阵颠簸，因此这个物理短语也指这种体验。"},{"no":"08","title":"A current of opinion","titleCN":"比喻义：思潮、舆论潮流","definition":"a widespread tendency of thinking or feeling that moves through a group or society","definitionCN":"在一群人乃至社会中移动扩散的思想或情绪倾向","example":"An air current of reform ran through the meeting.","exampleCN":"一股要求改革的思潮贯穿了整个会议。","why":"The metaphor treats public opinion as a fluid, so ideas can drift and carry others along.","whyCN":"这个比喻把舆论当成流体，于是思想可以漂移，并带着其他想法一起走。"}],"etymology":{"intro":{"en":"Air current is an English compound of two borrowings: air, which came through Old French from Latin aer and Greek aēr, and current, from Latin currere 'to run'. The phrase itself is a modern descriptive compound rather than a single inherited word.","cn":"air current 是由两个借词构成的英语复合短语：air 经古法语来自拉丁 aer 与希腊 aēr，current 来自拉丁 currere「跑」。这个短语本身是现代描述性组合，不是单一传承词。"},"items":[{"era":"GREEK AĒR","en":"Aēr meant the lower, misty air, as opposed to aithēr, the bright upper sky; the deeper origin of aēr is not established.","cn":"aēr 指低处朦胧的空气，与指明亮上天的 aithēr 相对；aēr 的更早来源未得到证明。"},{"era":"LATIN AER","en":"Latin aer 'air' was borrowed from Greek and passed through Old French into Middle English as air.","cn":"拉丁语 aer「空气」借自希腊语，再经古法语进入中古英语，成为 air。"},{"era":"LATIN CURRERE","en":"Currere meant 'to run', with the present participle currens 'running'; the noun current first named a running course, then water, air and electricity.","cn":"currere 意为「跑」，现在分词 currens 意为「奔跑的」；名词 current 先指奔流的路线，再指水、空气与电流。"},{"era":"ENGLISH COMPOUND","en":"Air and current were joined in English to describe moving air; the combination is transparent to any speaker and needs no separate etymology.","cn":"air 与 current 在英语中组合起来描述流动的空气；这个组合对任何使用者都一目了然，无需另立词源。"},{"era":"METEOROLOGICAL USE","en":"The phrase became common in nineteenth-century weather writing, but the exact first use and the period when it fixed as a term are uncertain.","cn":"这个短语在 19 世纪天气文献中变得常见，但确切的最早使用及其固定为术语的年代均不确定。"}]},"similar":{"note":{"en":"Group one holds other air-plus-noun compounds that look almost identical; group two holds plain wind words that differ in force or origin.","cn":"第一组是其他「空气 + 名词」的复合词，看起来几乎一样；第二组是表示风、力度或来源有别的普通词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"airstream","ipa":"/ˈeəstriːm/","tag":"one word, similar sense","definition":"A fast-moving stream of air, often written as one word; it stresses speed and continuity more than the general phrase.","definitionCN":"快速移动的空气流，常写作一个词；比泛称更强调速度与连续性。"},{"word":"airflow","ipa":"/ˈeəfləʊ/","tag":"rate or movement","definition":"The movement or measured volume of air through a system such as a duct or an engine.","definitionCN":"空气通过管道或发动机等系统的流动或其计量体积。"},{"word":"air jet","ipa":"/ˈeə dʒet/","tag":"focused blast","definition":"A concentrated, forceful stream of air blown from a nozzle.","definitionCN":"从喷嘴吹出的集中而有力的空气流。"},{"word":"air pocket","ipa":"/ˈeə pɒkɪt/","tag":"not a current","definition":"A region of descending or disturbed air that causes an aircraft to drop; it names the rough patch, not the flow itself.","definitionCN":"使飞机下坠的下沉或扰动空气区；它指那块颠簸区，而不是流动本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"wind","ipa":"/wɪnd/","tag":"natural outdoor air","definition":"Natural air moving outdoors, usually named by direction and strength; an air current can be indoor or local.","definitionCN":"户外自然流动的空气，常以方向和强度命名；air current 可以是室内的或局地的。"},{"word":"breeze","ipa":"/briːz/","tag":"gentle wind","definition":"A light, pleasant wind; it is a kind of air current with a low speed.","definitionCN":"轻柔宜人的风；是速度较低的一种气流。"},{"word":"gust","ipa":"/ɡʌst/","tag":"sudden blast","definition":"A brief, sudden increase in wind speed; it is an event, not a steady current.","definitionCN":"风速短暂而突然的增强；是一次事件，而非稳定的气流。"},{"word":"draft","ipa":"/drɑːft/","tag":"indoor draught","definition":"A current of cool air inside a building, often through a gap; the British spelling is draught.","definitionCN":"建筑内部常从缝隙进入的冷空气流；英式拼写为 draught。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real borrowed roots, real compounds and real weather collocations, not invented rhymes.","cn":"正常联想：两个真实的借词词根、真实复合词与真实天气搭配，而非编造的顺口溜。"},"normal":[{"en":"air from Greek aēr through Latin aer; current from Latin currere 'to run'.","cn":"air 经拉丁 aer 上溯希腊 aēr；current 来自拉丁 currere「跑」。"},{"en":"The phrase is transparent: air that is running, so direction and speed can always be added.","cn":"这个短语一目了然：正在跑的空气，因此总能再加方向和速度。"},{"en":"Weather writing adds the direction: rising, descending, upper-level air current.","cn":"天气文献加上方向：上升、下沉、高空气流。"},{"en":"The same current serves water and electricity, which is why the word feels familiar everywhere.","cn":"同一个 current 也用于水流与电流，所以这个词处处似曾相识。"},{"en":"A draft is the indoor cousin of an air current, usually colder and unwanted.","cn":"draft 是 air current 的室内亲戚，通常更冷、也更不受欢迎。"}],"abstract":[{"en":"Picture a paper boat carried across a pond without any hand touching it.","cn":"想象一只纸船横过池塘，没有任何手去碰它。"},{"en":"Picture a rumour entering a room through a single open door and leaving by another.","cn":"想象一则谣言从一扇门进房，又从另一扇门离开。"},{"en":"Picture a glider climbing in a silent column of warm air above a dark field.","cn":"想象滑翔机在暗色田野上方一柱无声的暖空气里爬升。"}]},"examples":[{"en":"The balloon drifted east on a steady air current.","cn":"气球借着一股稳定的气流向东飘去。"},{"en":"A downward air current kept the valley drier than the ridge.","cn":"下沉气流让山谷比山脊更干燥。"},{"en":"The engineer measured the air current at the outlet of the duct.","cn":"工程师测量了管道出口处的气流。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「空气跑」——空气一跑起来，就是气流","word":"air current"},"root":"复合短语：air 经古法语来自拉丁 aer、再上溯希腊 aēr「低层空气」，aēr 的更早来源不确定；current 来自拉丁 currere「跑」的现在分词 currens。短语在 19 世纪天气文献中常见，确切最早使用与固定为术语的年代不确定。","sensesIntro":{"en":"Eight senses follow one line: air that runs becomes a current, and the same phrase covers rising, sinking, horizontal, indoor, high and turbulent flow, until it finally carries opinions instead of dust.","cn":"八个义项沿一条线索展开：跑起来的空气成为气流，同一短语覆盖上升、下沉、水平、室内、高空与颠簸的流动，最后搬运的不再是灰尘而是观点。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thin cold line of air slipping under a door and lifting a sheet of paper.","cn":"核心意象：一线冷空气从门缝下钻进来，掀起一张纸。"},"chain":["MOVING AIR","RISING THERMAL","SINKING AIR","LOCAL BREEZE","INDOOR VENTILATION","HIGH-ALTITUDE JET"],"branches":[{"senses":"01 · 04","en":"PLAIN FLOW: the general phrase and the local breeze differ only in scale.","cn":"朴素流动：泛称与局地海风只在尺度上有别。"},{"senses":"02 · 03","en":"VERTICAL PAIR: warm air climbs and cool air sinks, two halves of one loop.","cn":"垂直成对：暖空气上升、冷空气下沉，是同一环流的两半。"},{"senses":"05","en":"ROOM SCALE: a fan or a gap turns the same phrase into ventilation.","cn":"房间尺度：风扇或缝隙把同一短语变成通风。"},{"senses":"06 · 07","en":"SKY AND CABIN: high fast air steers weather and shakes aircraft.","cn":"天空与机舱：高空快速气流既引导天气，也让飞机颠簸。"},{"senses":"08","en":"SOCIAL FLOW: ideas move like air and carry people along.","cn":"社会流动：思想像空气一样移动，并带动人群。"}]},"affixes":{"intro":{"en":"The phrase is built from two independent words, each with its own suffix history: air is a borrowed root, and current is a Latin participle turned noun.","cn":"这个短语由两个独立单词构成，各有自己的后缀史：air 是借来的词根，current 是拉丁分词变成的名词。"},"latinIntro":{"en":"Latin supplies both halves: aer 'air' (itself from Greek) and currere 'to run', whose participle currens means 'running'.","cn":"两半都来自拉丁语：aer「空气」（本身来自希腊语）与 currere「跑」，其分词 currens 意为「奔跑的」。"},"items":[{"word":"air","structure":"air (borrowed noun from Latin aer, Greek aēr)","meaning":"the mixture of gases we breathe","meaningCN":"我们呼吸的空气","example":"Cold air filled the corridor.","exampleCN":"冷空气充满了走廊。"},{"word":"curr-","structure":"currere (Latin verb, 'to run')","meaning":"to run, flow","meaningCN":"跑；流动","example":"The root also appears in cursor and excursion.","exampleCN":"这个词根也出现在 cursor 与 excursion 中。"},{"word":"-ent","structure":"-ent (Latin present-participle suffix)","meaning":"doing or being, as in 'running'","meaningCN":"正在做或正在是，如「奔跑的」","example":"Currens literally means 'running'.","exampleCN":"currens 字面意为「奔跑的」。"},{"word":"current","structure":"currere + -ent (participle become noun)","meaning":"a flow of water, air or electricity","meaningCN":"水、空气或电的流动","example":"The current carried the boat downstream.","exampleCN":"水流把船带向下游。"},{"word":"currently","structure":"current + -ly (adverb)","meaning":"at the present time","meaningCN":"目前；当前","example":"The office is currently closed.","exampleCN":"办公室目前关闭。"},{"word":"airflow","structure":"air + flow (compound noun)","meaning":"the movement of air through a system","meaningCN":"空气在系统中的流动","example":"Restricted airflow makes the engine hot.","exampleCN":"气流受限会让发动机过热。"},{"word":"airy","structure":"air + -y (having the quality of)","meaning":"full of fresh air; light and open","meaningCN":"通风的；轻盈开阔的","example":"The studio was bright and airy.","exampleCN":"这间工作室明亮又通风。"},{"word":"airless","structure":"air + -less (without)","meaning":"without fresh air; stuffy","meaningCN":"没有新鲜空气的；闷的","example":"The cellar felt airless in summer.","exampleCN":"夏天这地窖闷得没有一丝风。"}],"latinEntries":[{"word":"aer","structure":"aer, aeris (m., third declension; from Greek aēr)","meaning":"air, lower atmosphere","meaningCN":"空气；低层大气"},{"word":"currere","structure":"currere, cucurri, cursum (verb, third conjugation)","meaning":"to run, flow","meaningCN":"跑；流动"},{"word":"currens","structure":"currens, currentis (present participle)","meaning":"running, flowing","meaningCN":"奔跑的；流动的"}]}},{"word":"wind","ipa_uk":"/wɪnd/","ipa_us":"/wɪnd/","definition_zh":"风；风力；气息；风声、消息；趋势；（管乐器中的）管乐；使喘不过气；缠绕（读 /waɪnd/）","definition_en":"natural air moving across the earth's surface; also breath, a hint of news, a tendency, or to twist something around","core_image":"整片草叶被同一股力量压向一侧，沙粒贴着地面快速爬行，旗面被撑得笔直","scene":"海边的山坡上，草全部向同一方向倒伏，观察者说 The wind bends the grass flat against the hillside.","sceneCN":"这里 wind 指「在地表流动的自然空气」（第 1 个义项：能推动物体、改变植物形态的风）；句意为风把草压得贴向山坡。图中可辨识物件：倒伏的草、旗子、沙粒、远处的海面。","pos":[{"tag":"n.","zh":"风；风力；气息；风声；趋势；管乐器（读 /wɪnd/）"},{"tag":"vt.","zh":"使喘不过气；使气急（读 /wɪnd/）"},{"tag":"vt.","zh":"缠绕；上发条；使弯曲前进（同形异音，读 /waɪnd/）"}],"collocations":[{"phrase":"strong wind","zh":"强风"},{"phrase":"head wind","zh":"逆风"},{"phrase":"wind speed","zh":"风速"},{"phrase":"get wind of","zh":"听到……的风声"},{"phrase":"winds of change","zh":"变革之风"},{"phrase":"wind instrument","zh":"管乐器"}],"forms":[{"label":"名词复数","form":"winds"},{"label":"三单（he/she/it）","form":"winds"},{"label":"过去式（缠绕义，读 /waɪnd/）","form":"wound"},{"label":"过去分词（缠绕义）","form":"wound"},{"label":"现在分词（缠绕义）","form":"winding"},{"label":"过去式（使喘不过气义）","form":"winded"}],"derivatives":[{"word":"windy","pos":"adj.","zh":"有风的；风大的"},{"word":"windless","pos":"adj.","zh":"无风的；静止的"},{"word":"windward","pos":"adj./adv.","zh":"迎风的；向风一侧"},{"word":"windmill","pos":"n.","zh":"风车"},{"word":"windbreak","pos":"n.","zh":"防风林；挡风设施"}],"senses":[{"no":"01","title":"Natural air in motion","titleCN":"自然流动的风","definition":"air moving across the surface of the earth, usually named by the direction it comes from","definitionCN":"沿地表流动的空气，通常按来向命名","example":"A warm wind came off the desert at dusk.","exampleCN":"黄昏时一阵暖风从沙漠方向吹来。","why":"The noun is one of the oldest words in English, and its core is simply air that moves.","whyCN":"这个名词是英语最古老的词之一，核心意思不过是「在动的空气」。"},{"no":"02","title":"Force or strength of moving air","titleCN":"风力、风的强度","definition":"the speed or force of the air, often graded on a scale for weather and sailing","definitionCN":"空气的速度或力量，常按天气与航海的分级来衡量","example":"The wind reached gale force before the harbour closed.","exampleCN":"港口关闭前，风力已达到大风级。","why":"Once wind names the moving air, the same word naturally names how strongly it blows.","whyCN":"一旦 wind 指流动的空气，同一个词自然也能指它吹得有多强。"},{"no":"03","title":"Breath or power to breathe","titleCN":"气息、呼吸","definition":"the ability to breathe easily, especially after effort","definitionCN":"顺畅呼吸的能力，尤指用力之后","example":"He stopped at the top of the hill to get his wind back.","exampleCN":"他在山顶停下，好把气缓过来。","why":"Breath was thought of as air moving in and out of the body, so the outdoor word was borrowed for the inner one.","whyCN":"呼吸被看作空气在身体里进出，于是户外的词被借去指体内的空气。"},{"no":"04","title":"A hint or rumour","titleCN":"风声、消息","definition":"a piece of news or a hint that has begun to spread quietly","definitionCN":"开始悄悄传开的一点消息或暗示","example":"The staff got wind of the merger before it was announced.","exampleCN":"员工在合并公布之前就听到了风声。","why":"News was imagined as something carried on the air, arriving before any official statement.","whyCN":"消息被想象成随风而来的东西，比正式声明先到。"},{"no":"05","title":"A tendency or force of change","titleCN":"趋势、变革的力量","definition":"a widespread movement of opinion or events that pushes change in a direction","definitionCN":"推动事情朝某方向改变的普遍舆论或事件趋势","example":"The winds of reform reached even the oldest institutions.","exampleCN":"改革之风甚至吹到了最古老的机构。","why":"The metaphor makes social change a weather system, with direction and force of its own.","whyCN":"这个比喻把社会变化变成天气系统，自带方向与力量。"},{"no":"06","title":"Wind instruments","titleCN":"管乐器","definition":"the group of instruments played by blowing air, such as flutes and trumpets","definitionCN":"靠吹气发声的一组乐器，如长笛与小号","example":"The wind section entered after the strings faded.","exampleCN":"弦乐渐弱之后，管乐声部进来了。","why":"These instruments work by moving air, so players shorten 'wind instruments' to 'the wind'.","whyCN":"这些乐器靠推动空气发声，因此乐手把 wind instruments 缩称为 the wind。"},{"no":"07","title":"To leave someone breathless","titleCN":"动词：使喘不过气","definition":"to hit or exhaust someone so that they cannot breathe easily for a moment","definitionCN":"撞击或消耗某人，使其一时无法顺畅呼吸","example":"The fall winded him for a full minute.","exampleCN":"那一跤让他足足一分钟喘不上气。","why":"The verb reverses the breath sense: instead of having wind, a person has it knocked out.","whyCN":"这个动词反转了气息义：人不是有了气，而是气被打掉了。"},{"no":"08","title":"To twist or coil","titleCN":"动词：缠绕、上发条（读 /waɪnd/）","definition":"to wrap something around an object, or to turn a key or handle to make a mechanism work","definitionCN":"把某物绕在物体上，或转动钥匙、手柄使机械运转","example":"She wound the old clock every Sunday morning.","exampleCN":"她每个星期天早上给那座旧钟上发条。","why":"This is a different word, pronounced with a long vowel, that happens to share the spelling; its core is turning or coiling.","whyCN":"这是另一个词，读长元音，只是拼写相同；其核心义是转动或盘绕。"}],"etymology":{"intro":{"en":"Wind is a native Germanic noun from Old English wind. Its deeper root is reconstructed, and Latin ventus is a genuine cognate from the same source rather than the origin of the English word. The verb meaning 'to twist' is a separate homograph with a long vowel.","cn":"wind 是古英语 wind 传承下来的日耳曼本族名词。其更深词根为重构形式；拉丁语 ventus 是同出该源的真实同源词，而非英语词的来源。意为「缠绕」的动词是另一个同形异音词，读长元音。"},"items":[{"era":"OLD ENGLISH WIND","en":"Wind meant 'moving air' and was already the everyday noun for weather; the same form also served for breath.","cn":"wind 意为「流动的空气」，早已是谈天气的日常名词；同一形式也用于指呼吸。"},{"era":"GERMANIC *WINDAZ","en":"The noun goes back to a Germanic form reconstructed as *windaz, with relatives in Dutch wind and German Wind.","cn":"这个名词上溯到重构的日耳曼形式 *windaz，在荷兰语 wind 与德语 Wind 中有亲属。"},{"era":"INDO-EUROPEAN *H₂WEH₁-","en":"The usual reconstruction is a root meaning 'to blow', written *h₂weh₁-; it is a reconstructed form, not a recorded word.","cn":"通常把词根重构为意为「吹」的 *h₂weh₁-；这是重构形式，不是有记录的实际词。"},{"era":"LATIN VENTUS","en":"Latin ventus 'wind' comes from the same deep root, so it is a cognate; English did not borrow the word from it.","cn":"拉丁语 ventus「风」来自同一深层词根，因此是同源词；英语并非从它借入这个词。"},{"era":"LATER SENSES","en":"Breath, rumour, tendency and the musical sense are later extensions; their exact first dates are uncertain and should not be given as fixed facts.","cn":"呼吸、风声、趋势与音乐义都是后来的延伸；其确切首见年代不确定，不宜当作固定事实。"}]},"similar":{"note":{"en":"Group one holds words that contain wind but mean something else; group two holds actual wind words that differ in strength or setting.","cn":"第一组是含有 wind 字样但意思不同的词；第二组是真正表示风、但力度或场合有别的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"window","ipa":"/ˈwɪndəʊ/","tag":"contains wind","definition":"An opening in a wall for light and air, from Old Norse vindauga 'wind-eye'; it is not a form of wind.","definitionCN":"墙上用于透光和通风的开口，来自古诺尔斯语 vindauga「风眼」；它不是 wind 的词形变化。"},{"word":"windy","ipa":"/ˈwɪndi/","tag":"derived adjective","definition":"The adjective meaning 'exposed to much wind' or 'long-winded'; it is derived from wind, not a separate root.","definitionCN":"形容词，意为「多风的」或「话多的」；由 wind 派生，不是另一个词根。"},{"word":"winded","ipa":"/ˈwɪndɪd/","tag":"breathless","definition":"The past participle meaning 'left out of breath', from the verb sense of wind.","definitionCN":"过去分词，意为「被弄得喘不上气」，来自 wind 的动词义。"},{"word":"winding","ipa":"/ˈwaɪndɪŋ/","tag":"coiling, long vowel","definition":"The participle of the other wind, pronounced with a long vowel: twisting, or following a twisting path.","definitionCN":"另一个 wind 的分词，读长元音：缠绕的，或沿弯曲路径延伸的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"breeze","ipa":"/briːz/","tag":"gentle","definition":"A light, pleasant wind, often from the sea; wind itself can be any strength.","definitionCN":"轻柔宜人的风，常指海风；wind 则可指任何强度。"},{"word":"gale","ipa":"/ɡeɪl/","tag":"very strong","definition":"A very strong wind, especially one graded on the Beaufort scale; it is a level of wind, not a different phenomenon.","definitionCN":"极强的风，尤指蒲福风级中的一级；它是风的一个等级，不是另一种现象。"},{"word":"gust","ipa":"/ɡʌst/","tag":"brief burst","definition":"A sudden short blast of wind; it is a momentary event within a steadier wind.","definitionCN":"突然而短促的一阵风；是较稳定风中的瞬时事件。"},{"word":"draught","ipa":"/drɑːft/","tag":"indoor current","definition":"A current of cool air inside a building; wind is usually the outdoor weather word.","definitionCN":"建筑内部的冷空气流；wind 通常指户外的天气现象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real native root, a real cognate and real compounds, not invented rhymes.","cn":"正常联想：真实的英语本族词根、真实同源词与真实复合词，而非编造的顺口溜。"},"normal":[{"en":"Old English wind; the same Germanic stock gives Dutch wind and German Wind.","cn":"古英语 wind；同日耳曼词源给出荷兰语 wind 与德语 Wind。"},{"en":"Latin ventus is a cognate, not the source; the two words grew from the same deep root.","cn":"拉丁语 ventus 是同源词而非来源；两个词从同一深层词根长出。"},{"en":"Compounds mark the uses: wind speed, windmill, windbreak, windward.","cn":"复合词标出用法：风速、风车、防风林、迎风。"},{"en":"The phrase 'get wind of' keeps the old image of news arriving on the air.","cn":"「get wind of」保留了消息随风而来的旧意象。"},{"en":"Remember the homograph: the twisting verb is wound and winding, not winded.","cn":"记住同形异音词：缠绕义的过去式是 wound、分词是 winding，不是 winded。"}],"abstract":[{"en":"Picture a flag pulling so hard that the pole leans with it.","cn":"想象旗子拉得那么用力，连旗杆都跟着倾斜。"},{"en":"Picture a rumour crossing a playground faster than any child can run.","cn":"想象一则谣言穿过操场，比任何孩子跑得都快。"},{"en":"Picture an old clock key turning in a slow circle until the spring is tight.","cn":"想象一把旧钟的发条钥匙慢慢转圈，直到弹簧绷紧。"}]},"examples":[{"en":"The wind tore the awning loose before the storm arrived.","cn":"风暴到来之前，风把遮阳篷扯松了。"},{"en":"She stood still until she had her wind again.","cn":"她站住不动，直到气息恢复。"},{"en":"The conductor asked the wind to play softer in the second movement.","cn":"指挥要求管乐在第二乐章吹得更轻。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「温的」——温的空气一动起来，就成了风","word":"wind"},"root":"古英语 wind「流动的空气」，属日耳曼语族，可上溯重构形式 *windaz 与意为「吹」的印欧词根 *h₂weh₁-（重构形式）。拉丁语 ventus 为同源词而非来源。意为「缠绕」的动词是同形异音词，读 /waɪnd/，与本条名词不同源。","sensesIntro":{"en":"Eight senses follow one line: air in motion is first weather, then its strength, then the breath inside a body, then news and social change carried on the air, then the instruments that use it, and finally two verbs, one about breath and one about twisting.","cn":"八个义项沿一条线索展开：运动的空气先是天气，再是它的强度，然后是体内的气息，再是随风传播的消息与社会变化，然后是借空气发声的乐器，最后是两个动词，一个关于气息，一个关于缠绕。"},"semanticMap":{"core":{"en":"CORE IMAGE: grass bent flat in one direction while sand skims the ground.","cn":"核心意象：草被压得倒向一侧，沙粒贴着地面飞掠。"},"chain":["MOVING AIR","FORCE OF AIR","BREATH","RUMOUR","SOCIAL CHANGE","WIND INSTRUMENTS"],"branches":[{"senses":"01 · 02","en":"WEATHER: the moving air and the strength with which it blows.","cn":"天气：流动的空气与它吹出的力量。"},{"senses":"03 · 07","en":"BREATH IN AND OUT: having wind, and having it knocked away.","cn":"气息进出：有气，与气被打掉。"},{"senses":"04 · 05","en":"AIRBORNE NEWS: rumours and reform both travel like weather.","cn":"随风的消息：谣言与改革都像天气一样传播。"},{"senses":"06","en":"BLOWN INSTRUMENTS: music made by moving air through a tube.","cn":"吹奏乐器：让空气穿过管子而发声。"},{"senses":"08","en":"THE HOMOGRAPH: a separate verb of turning and coiling, pronounced long.","cn":"同形异音词：另一个表示转动与盘绕的动词，读长元音。"}]},"affixes":{"intro":{"en":"Wind is a free native root that takes -y, -less, -ward and joins compounds such as windmill and windbreak; a separate homograph wind 'to twist' adds wound and winding.","cn":"wind 是自由的本族词根，可加 -y、-less、-ward，并与 windmill、windbreak 等构成复合词；另有同形异音词 wind「缠绕」，给出 wound 与 winding。"},"latinIntro":{"en":"Latin ventus 'wind' is a cognate from the same deep root, and ventosus 'windy' belongs to that Latin family; neither is the source of the English word.","cn":"拉丁语 ventus「风」是同出深层词根的同源词，ventosus「多风的」属于该拉丁词族；两者都不是英语词的来源。"},"items":[{"word":"wind","structure":"wind (native noun, Old English wind)","meaning":"moving air","meaningCN":"流动的空气","example":"The wind rose with the tide.","exampleCN":"风随潮水一起变大。"},{"word":"wind","structure":"wind (homograph verb, pronounced /waɪnd/)","meaning":"to twist, coil or turn a key","meaningCN":"缠绕；盘绕；转动钥匙","example":"Wind the string around the spool.","exampleCN":"把线绕到线轴上。"},{"word":"windy","structure":"wind + -y (having the quality of)","meaning":"exposed to strong wind","meaningCN":"多风的；风大的","example":"The ridge is windy even in summer.","exampleCN":"这道山脊夏天也多风。"},{"word":"windless","structure":"wind + -less (without)","meaning":"with no wind at all","meaningCN":"无风的","example":"The lake lay windless at dawn.","exampleCN":"黎明时湖面一丝风也没有。"},{"word":"windward","structure":"wind + -ward (toward)","meaning":"on the side the wind blows from","meaningCN":"迎风的一侧","example":"The windward slope gets more rain.","exampleCN":"迎风坡降雨更多。"},{"word":"windmill","structure":"wind + mill (compound noun)","meaning":"a mill driven by wind","meaningCN":"风力驱动的磨坊或风车","example":"The old windmill still turns.","exampleCN":"那座老风车仍在转动。"},{"word":"windbreak","structure":"wind + break (compound noun)","meaning":"a row of trees or a barrier that blocks wind","meaningCN":"挡风的树列或屏障","example":"The poplar windbreak protects the orchard.","exampleCN":"白杨防风林保护着果园。"},{"word":"windswept","structure":"wind + swept (compound adjective)","meaning":"exposed and shaped by wind","meaningCN":"受风侵袭的；被风吹得光秃的","example":"A windswept headland faced the sea.","exampleCN":"一片受风的岬角面向大海。"}],"latinEntries":[{"word":"ventus","structure":"ventus, venti (m., second declension; cognate, not source)","meaning":"wind","meaningCN":"风"},{"word":"ventosus","structure":"ventosus, ventosa, ventosum (adj.; cognate family)","meaning":"windy, full of wind","meaningCN":"多风的；风大的"}]}},{"word":"wind speed","ipa_uk":"/wɪnd spiːd/","ipa_us":"/wɪnd spiːd/","definition_zh":"风速；空气流动的速度；风速等级；设计风速；风速预报值","definition_en":"the rate at which air moves past a point, usually measured in metres per second or knots","core_image":"风杯转速仪在桅杆顶端飞快旋转，表盘上的数字不断向上跳动","scene":"气象站里，观测员盯着桅杆顶端的旋转仪器，说 Wind speed at the mast has doubled since noon.","sceneCN":"这里 wind speed 指「空气经过某一点时的移动速率」（第 1 个义项：可用仪器测出的基本风速）；句意为桅杆处的风速从中午起已经翻倍。图中可辨识物件：桅杆、风杯、读数表盘、记录本。","pos":[{"tag":"n.","zh":"风速；空气流动速率（可数，复数 wind speeds）"}],"collocations":[{"phrase":"high wind speed","zh":"高风速"},{"phrase":"wind speed measurement","zh":"风速测量"},{"phrase":"wind speed forecast","zh":"风速预报"},{"phrase":"maximum wind speed","zh":"最大风速"},{"phrase":"wind speed sensor","zh":"风速传感器"},{"phrase":"wind speed limit","zh":"风速限值"}],"forms":[{"label":"复数","form":"wind speeds"},{"label":"相关名词（风）","form":"wind"},{"label":"相关名词（速度）","form":"speed"},{"label":"相关形容词（快速的）","form":"speedy"},{"label":"相关仪器（风速计）","form":"anemometer"}],"derivatives":[{"word":"speedy","pos":"adj.","zh":"快速的；迅速的"},{"word":"speedily","pos":"adv.","zh":"迅速地"},{"word":"speedometer","pos":"n.","zh":"速度计；里程表"},{"word":"airspeed","pos":"n.","zh":"空速（飞机相对空气的速度）"}],"senses":[{"no":"01","title":"The measured rate of air movement","titleCN":"测得的风速","definition":"the distance air travels past a point in a given unit of time","definitionCN":"单位时间内空气经过某一点所走的距离","example":"The tower recorded a wind speed of fifteen metres per second.","exampleCN":"塔台记录到的风速是每秒十五米。","why":"The compound simply names the speed of the wind, just as water speed names the speed of water.","whyCN":"这个复合词就是「风的速度」，正如 water speed 指水的速度。"},{"no":"02","title":"Units and instruments","titleCN":"风速的计量单位与仪器","definition":"the scales and devices, such as knots, metres per second and anemometers, used to express wind speed","definitionCN":"用来表示风速的单位与装置，如节、米每秒与风速计","example":"Sailors still quote wind speed in knots on the bridge.","exampleCN":"水手在驾驶台上仍用节来表示风速。","why":"Once a quantity is measured regularly, its units and instruments are discussed under the same name.","whyCN":"一个量一旦被常规测量，它的单位与仪器也会用同一个名称来讨论。"},{"no":"03","title":"A step on the Beaufort scale","titleCN":"蒲福风级中的一级","definition":"one of the numbered categories that describe the effects of a given wind speed","definitionCN":"按给定风速描述其影响的分级编号之一","example":"At that wind speed the sea builds whitecaps offshore.","exampleCN":"在这样的风速下，近海会起白浪。","why":"The scale converts a numerical speed into an observable category, but the category is still spoken of as a wind speed.","whyCN":"风级把数字化的速度转换成可观察的类别，但人们仍以风速来称呼这个类别。"},{"no":"04","title":"A design load for structures","titleCN":"结构设计风速","definition":"the wind speed a building, bridge or tower is engineered to withstand","definitionCN":"建筑、桥梁或塔架按设计需要承受的风速","example":"The code sets a design wind speed for every coastal district.","exampleCN":"规范为每个沿海地区规定了设计风速。","why":"Engineering turns the measured quantity into a load, and keeps the same name for the design value.","whyCN":"工程把测得的值变成荷载，而设计值仍沿用同一个名称。"},{"no":"05","title":"Rated speed for a wind turbine","titleCN":"风力发电机的额定风速","definition":"the wind speed at which a turbine reaches its stated power output","definitionCN":"涡轮机达到标称输出功率时的风速","example":"Below the rated wind speed the turbine produces less than its maximum.","exampleCN":"低于额定风速时，涡轮机的发电量达不到最大值。","why":"The energy industry needs a fixed reference point, so it names that point by the wind speed itself.","whyCN":"能源行业需要一个固定参照点，于是直接用风速来命名该点。"},{"no":"06","title":"An operating limit for aircraft and ships","titleCN":"航空与航海的操作风速限制","definition":"the maximum wind speed at which a landing, take-off or manoeuvre is considered safe","definitionCN":"着陆、起飞或操作被认为安全所允许的最大风速","example":"The flight was delayed because the wind speed exceeded the crosswind limit.","exampleCN":"因为风速超过了侧风限值，航班延误了。","why":"Operators work with thresholds, and the threshold is naturally described as a wind speed.","whyCN":"操作者依据阈值行事，而阈值自然就以风速来描述。"},{"no":"07","title":"Change of speed with height","titleCN":"风速随高度的变化","definition":"the increase or decrease in wind speed between one level and another, as in wind shear","definitionCN":"不同高度之间风速的增减，如风切变","example":"Pilots watch for a sharp change in wind speed near the runway.","exampleCN":"飞行员会留意跑道附近风速的急剧变化。","why":"The quantity is compared between two heights, so the phrase appears in the study of gradients and shear.","whyCN":"这个量在两个高度之间作比较，因此该短语出现在梯度与切变研究中。"},{"no":"08","title":"A forecast value","titleCN":"预报风速值","definition":"the wind speed predicted for a place and time in a weather forecast","definitionCN":"天气预报中为某地某时预测的风速","example":"The evening forecast raised the expected wind speed to forty knots.","exampleCN":"晚间预报把预计风速提高到四十节。","why":"Forecasting is about the future value of the same measured quantity, so no new term is needed.","whyCN":"预报说的是同一个被测量在未来的数值，因此不需要新术语。"}],"etymology":{"intro":{"en":"Wind speed is an English compound of two native words. Wind goes back to Old English wind, and speed to Old English spēd, which first meant 'success, prosperity' before it came to mean 'rate of motion'.","cn":"wind speed 是两个英语本族词构成的复合短语。wind 上溯古英语 wind；speed 上溯古英语 spēd，原义为「成功、兴旺」，后来才表示「运动速率」。"},"items":[{"era":"OLD ENGLISH WIND","en":"Wind meant moving air and belongs to the same Germanic stock as Dutch wind and German Wind.","cn":"wind 意为流动的空气，与荷兰语 wind、德语 Wind 同属日耳曼语族。"},{"era":"OLD ENGLISH SPĒD","en":"Spēd meant 'success, good fortune, quickness', with a related verb spōwan 'to prosper'.","cn":"spēd 意为「成功、好运、迅速」，并有相关动词 spōwan「兴旺」。"},{"era":"SEMANTIC SHIFT","en":"During the Middle English period speed narrowed from 'success' to 'swiftness' and then to 'rate of motion', which is the sense used in the compound.","cn":"在中古英语时期，speed 从「成功」收窄为「迅速」，再变为「运动速率」，也就是复合词所用的义项。"},{"era":"METEOROLOGICAL COMPOUND","en":"Wind speed became a standard item in nineteenth-century weather records, once anemometers were read regularly at stations.","cn":"随着测站开始常规读取风速计，wind speed 在 19 世纪的天气记录中成为标准项目。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date only): no exact first citation for the compound is fixed, and the speed word's shift from 'success' has no single recorded date.","cn":"来源不确定（仅首见年代）：这个复合词没有确切的最早书证，speed 从「成功」转为「速率」也没有单一可考的日期。"}]},"similar":{"note":{"en":"Group one holds speed compounds that are easily confused with wind speed; group two holds other ways of naming how fast air or a craft moves.","cn":"第一组是容易与 wind speed 混淆的速度复合词；第二组是表示空气或飞行器运动快慢的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"airspeed","ipa":"/ˈeəspiːd/","tag":"aircraft relative to air","definition":"The speed of an aircraft relative to the surrounding air, not the speed of the air itself.","definitionCN":"飞机相对周围空气的速度，而不是空气本身的速度。"},{"word":"ground speed","ipa":"/ˈɡraʊnd spiːd/","tag":"aircraft over the ground","definition":"The speed of an aircraft relative to the ground, which differs from both airspeed and wind speed.","definitionCN":"飞机相对地面的速度，与空速和风速都不同。"},{"word":"wind direction","ipa":"/wɪnd dəˈrekʃn/","tag":"the other half of wind","definition":"The compass direction from which the wind blows, paired with wind speed in every weather report.","definitionCN":"风吹来的方位，在每份天气报告中与风速并列。"},{"word":"gust speed","ipa":"/ɡʌst spiːd/","tag":"short peak","definition":"The peak speed of a brief blast, often higher than the steady wind speed.","definitionCN":"一阵短促强风的峰值速度，通常高于稳定风速。"}]},{"heading":"NEAR MEANING","entries":[{"word":"velocity","ipa":"/vəˈlɒsəti/","tag":"vector quantity","definition":"Speed in a stated direction; wind velocity includes both the rate and the direction of the air.","definitionCN":"带方向的速度；风的 velocity 同时包含速率与方向。"},{"word":"wind force","ipa":"/wɪnd fɔːs/","tag":"effect scale","definition":"The strength of the wind expressed as a force or Beaufort number rather than a measured rate.","definitionCN":"以力或蒲福风级表示的风的强度，而非测得的速率。"},{"word":"air velocity","ipa":"/eə vəˈlɒsəti/","tag":"technical synonym","definition":"A technical term for the speed of air in a duct or around an object, often used in engineering.","definitionCN":"指管道内或物体周围空气速度的技术术语，常用于工程。"},{"word":"speed of sound","ipa":"/spiːd əv saʊnd/","tag":"different referent","definition":"The rate at which sound travels through a medium, a fixed property rather than a local wind condition.","definitionCN":"声音在介质中传播的速率，是固定属性，而非某地的风况。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real native roots, real units and real weather collocations, not invented rhymes.","cn":"正常联想：两个真实的英语本族词根、真实单位与真实天气搭配，而非编造的顺口溜。"},"normal":[{"en":"wind + speed: literally the speed of the wind, a transparent compound.","cn":"wind + speed：字面就是风的速度，构词完全透明。"},{"en":"Speed once meant 'success'; the modern sense of rate grew out of the idea of getting on quickly.","cn":"speed 原义为「成功」；现代速率义从「事情进展得快」这一想法长出。"},{"en":"Weather reports always pair wind speed with wind direction.","cn":"天气报告总把风速与风向并列。"},{"en":"Units are part of the term: metres per second, knots, kilometres per hour.","cn":"单位是术语的一部分：米每秒、节、公里每小时。"},{"en":"The anemometer is the instrument that turns wind speed into a reading.","cn":"风速计是把风速变成读数的仪器。"}],"abstract":[{"en":"Picture three cups spinning on a pole, each turn counted by a quiet meter.","cn":"想象杆顶三只风杯旋转，每一圈都被一台安静的仪表记下。"},{"en":"Picture a flag that stiffens from limp to straight as the number climbs.","cn":"想象旗子随数字上升，从垂软变得笔直。"},{"en":"Picture a turbine that begins to produce power only after the air reaches one fixed rate.","cn":"想象风机只有在空气达到某个固定速率后才开始发电。"}]},"examples":[{"en":"The anemometer logged a peak wind speed just before the squall.","cn":"风速计在飑线到来前记录到峰值风速。"},{"en":"Engineers tested the bridge model at twice the design wind speed.","cn":"工程师用两倍设计风速测试了桥梁模型。"},{"en":"The forecast warned of a wind speed that could ground small boats.","cn":"预报警告风速可能让小船无法出航。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「风快」——风跑得有多快，就是风速","word":"wind speed"},"root":"复合短语：wind 来自古英语 wind，属日耳曼语族；speed 来自古英语 spēd「成功、兴旺」，中古英语时期转为「迅速、速率」。气象义在 19 世纪风速计常规观测后成为标准项目，确切最早书证不确定。","sensesIntro":{"en":"Eight senses follow one line: the rate of moving air is measured, then expressed in units, graded, designed for, harvested, limited, compared between heights and finally forecast.","cn":"八个义项沿一条线索展开：流动空气的速率先被测量，再以单位表达、分级、用于设计、用于发电、设为限值、在不同高度比较，最后进入预报。"},"semanticMap":{"core":{"en":"CORE IMAGE: three spinning cups on a mast, their turns counted into a number.","cn":"核心意象：桅杆上三只旋转的风杯，转数被折算成一个数字。"},"chain":["RATE OF AIR","UNITS AND GAUGES","BEAUFORT STEP","DESIGN LOAD","TURBINE RATING","FLIGHT LIMIT"],"branches":[{"senses":"01 · 02","en":"MEASURE AND UNITS: a quantity is only useful once its scale is fixed.","cn":"测量与单位：一个量只有定好标尺才有用。"},{"senses":"03","en":"OBSERVABLE GRADE: the Beaufort step turns a number into a visible sea state.","cn":"可观察的等级：蒲福风级把数字变成可见的海况。"},{"senses":"04 · 06","en":"SAFETY THRESHOLDS: buildings and aircraft are both designed against a stated speed.","cn":"安全阈值：建筑与飞机都按某一给定风速来设计。"},{"senses":"05","en":"ENERGY REFERENCE: a turbine's output is pinned to one rated speed.","cn":"能量参照：风机的输出被钉在一个额定风速上。"},{"senses":"07 · 08","en":"COMPARISON AND PREDICTION: speed is compared between heights and projected into the future.","cn":"比较与预测：风速在不同高度间比较，并被投射到未来。"}]},"affixes":{"intro":{"en":"The phrase joins two free roots, and each root has its own suffix family: speed gives speedy and speedometer, while wind gives windy and windless.","cn":"这个短语连接两个自由词根，各自有后缀词族：speed 给出 speedy 与 speedometer，wind 给出 windy 与 windless。"},"latinIntro":{"en":"The compound is fully English, so there is no Latin term behind it. Latin ventus is only a cognate of the wind half, and spēs is not related to speed at all.","cn":"这个复合词完全是英语构成，背后没有拉丁术语。拉丁语 ventus 只是 wind 那一半的同源词，而 spēs 与 speed 毫无关系。"},"items":[{"word":"wind","structure":"wind (native noun)","meaning":"moving air","meaningCN":"流动的空气","example":"The wind shifted to the north.","exampleCN":"风转向北方。"},{"word":"speed","structure":"speed (native noun, Old English spēd)","meaning":"rate of motion","meaningCN":"运动速率","example":"The train gathered speed downhill.","exampleCN":"列车在下坡时加速。"},{"word":"-y","structure":"-y (adjective suffix)","meaning":"having the quality of","meaningCN":"具有某种性质","example":"A speedy reply arrived the same day.","exampleCN":"当天就来了一个迅速的回复。"},{"word":"speedy","structure":"speed + -y (adjective)","meaning":"fast, quick","meaningCN":"快速的","example":"The crew made a speedy repair.","exampleCN":"船员迅速完成了修理。"},{"word":"speedily","structure":"speedy + -ly (adverb)","meaning":"in a fast manner","meaningCN":"迅速地","example":"The leak was speedily sealed.","exampleCN":"漏洞被迅速封住。"},{"word":"speedometer","structure":"speed + -o- + -meter (measuring device)","meaning":"an instrument that shows speed","meaningCN":"显示速度的仪表","example":"The speedometer needle touched eighty.","exampleCN":"速度计指针触到八十。"},{"word":"airspeed","structure":"air + speed (parallel compound)","meaning":"an aircraft's speed relative to the air","meaningCN":"飞机相对空气的速度","example":"Airspeed matters more than ground speed in a head wind.","exampleCN":"逆风时空速比地速更重要。"},{"word":"windswept","structure":"wind + swept (compound adjective)","meaning":"shaped or exposed by wind","meaningCN":"受风塑造或侵袭的","example":"A windswept beach ran north for miles.","exampleCN":"一片受风的海滩向北延伸数英里。"}],"latinEntries":[]}},{"word":"wind direction","ipa_uk":"/wɪnd dəˈrekʃn/","ipa_us":"/wɪnd dəˈrekʃən/","definition_zh":"风向；风吹来的方位；风向观测；风向切变；舆论走向（比喻义）","definition_en":"the compass direction from which the wind blows","core_image":"机场草地上一只橙白条纹的风向袋被风撑满，袋口指向与风来向相反的一侧","scene":"机场草地上，一只橙白相间的风向袋被风吹得笔直，地勤说 The wind direction decides which runway the aircraft will use.","sceneCN":"这里 wind direction 指「风从哪个方位吹来」（第 6 个义项：航空作业中依据风向选择跑道）；句意为风向决定飞机使用哪条跑道。图中可辨识物件：风向袋、跑道、飞机、地勤人员。","pos":[{"tag":"n.","zh":"风向；风吹来的方位（可数，复数 wind directions）"}],"collocations":[{"phrase":"prevailing wind direction","zh":"盛行风向"},{"phrase":"wind direction indicator","zh":"风向指示器"},{"phrase":"wind direction sensor","zh":"风向传感器"},{"phrase":"a change in wind direction","zh":"风向的改变"},{"phrase":"wind direction and speed","zh":"风向与风速"},{"phrase":"record the wind direction","zh":"记录风向"}],"forms":[{"label":"复数","form":"wind directions"},{"label":"相关名词（风）","form":"wind"},{"label":"相关名词（方向）","form":"direction"},{"label":"相关形容词（方向的）","form":"directional"},{"label":"相关仪器（风向标）","form":"wind vane"}],"derivatives":[{"word":"directional","pos":"adj.","zh":"方向的；有方向性的"},{"word":"directly","pos":"adv.","zh":"直接地；径直地"},{"word":"director","pos":"n.","zh":"主管；导演"},{"word":"direct","pos":"v./adj.","zh":"指导；直接的"},{"word":"directionless","pos":"adj.","zh":"没有方向的"}],"senses":[{"no":"01","title":"The direction the wind comes from","titleCN":"风吹来的方位","definition":"the point of the compass from which the air is moving toward the observer","definitionCN":"空气朝观察者移动时所来自的罗盘方位","example":"A northerly wind direction brought cold air down from the hills.","exampleCN":"偏北的风向把冷空气从山上带下来。","why":"Meteorology names wind by where it comes from, not where it goes, so direction is always the source side.","whyCN":"气象学按风的来向而非去向命名，因此风向总是指来源一侧。"},{"no":"02","title":"A compass bearing on the rose","titleCN":"罗盘方位上的风向表示","definition":"the wind direction expressed as one of the compass points or as a bearing in degrees","definitionCN":"用罗盘方位点或角度表示的风向","example":"The log recorded a wind direction of two hundred and seventy degrees.","exampleCN":"日志记录的风向是二百七十度。","why":"To be useful, a direction must be fitted to a scale, and the compass rose supplies that scale.","whyCN":"方向要有用，就必须装进一个刻度，而罗盘方位图提供了这个刻度。"},{"no":"03","title":"A standard weather observation","titleCN":"气象观测的标准项目","definition":"the entry for wind direction in a routine weather report, usually paired with speed","definitionCN":"常规天气报告中关于风向的记录项，通常与风速并列","example":"Every station reports wind direction at the top of the hour.","exampleCN":"每个测站都在整点报告风向。","why":"Observational practice turns a physical fact into a fixed slot in a report, and the slot keeps the name.","whyCN":"观测惯例把一个物理事实变成报告里的固定栏目，栏目沿用这个名称。"},{"no":"04","title":"Read from a vane or windsock","titleCN":"用风向标或风向袋读出风向","definition":"the wind direction shown by an instrument such as a wind vane, a windsock or a sensor","definitionCN":"由风向标、风向袋或传感器显示出的风向","example":"The windsock's wind direction told the pilot the breeze was from the left.","exampleCN":"风向袋显示的风向告诉飞行员，微风来自左侧。","why":"Instruments exist to make the invisible direction visible, and the reading is simply called the wind direction.","whyCN":"仪器的作用是让看不见的方向变得可见，而读数就直接称为风向。"},{"no":"05","title":"Where pollution will drift","titleCN":"污染物扩散的方向","definition":"the direction in which smoke, dust or a gas plume will be carried from a source","definitionCN":"烟、尘或气羽从源头被带往的方向","example":"The wind direction carried the smoke away from the village.","exampleCN":"风向把烟带离了村庄。","why":"Air quality work asks the same question as weather: which way is the air going, and the phrase is reused unchanged.","whyCN":"空气质量工作问的是与天气相同的问题：空气往哪边走，短语原样沿用。"},{"no":"06","title":"A factor in take-off and landing","titleCN":"航空与航海作业中的风向因素","definition":"the direction of the wind relative to a runway, deck or course, which determines the safest heading","definitionCN":"风相对于跑道、甲板或航向的方向，它决定最安全的朝向","example":"The tower changed the active runway when the wind direction shifted.","exampleCN":"风向改变时，塔台更换了使用中的跑道。","why":"Aircraft and ships must meet the wind head-on where possible, so the phrase becomes an operational instruction.","whyCN":"飞机与船只应尽可能迎着风，因此这个短语成了操作指令。"},{"no":"07","title":"Change of direction with height","titleCN":"风向随高度的切变","definition":"the turning of the wind from one level to another, a component of wind shear","definitionCN":"风在不同高度之间发生的转向，是风切变的一部分","example":"A sudden change in wind direction near the surface warned of a downburst.","exampleCN":"近地面风向的突然改变预示着下击暴流。","why":"Comparing direction at two heights turns the phrase into a diagnostic for shear and turbulence.","whyCN":"比较两个高度的风向，使这个短语成为判断切变与颠簸的指标。"},{"no":"08","title":"The way opinion is turning","titleCN":"比喻义：舆论或局势的走向","definition":"the general tendency in which public opinion or events are moving","definitionCN":"公众意见或事件正在移动的总趋势","example":"The wind direction in the committee changed after the report leaked.","exampleCN":"报告泄露后，委员会里的风向变了。","why":"The metaphor treats opinion as weather: it has a direction, and people watch which way it blows.","whyCN":"这个比喻把舆论当成天气：它有方向，人们会观察它往哪边吹。"}],"etymology":{"intro":{"en":"Wind direction joins the native noun wind with direction, a borrowing from Latin directio, built on dirigere 'to set straight'. The compound is an English descriptive phrase used in weather writing.","cn":"wind direction 把本族名词 wind 与借词 direction 组合起来；direction 来自拉丁 directio，由 dirigere「使成直线、引导」构成。这个复合短语是天气文献中的英语描述性说法。"},"items":[{"era":"OLD ENGLISH WIND","en":"Wind meant moving air and belongs to the Germanic stock shared by Dutch wind and German Wind.","cn":"wind 意为流动的空气，与荷兰语 wind、德语 Wind 同属日耳曼语族。"},{"era":"LATIN REGERE","en":"Regere meant 'to rule, guide, keep straight', with the past participle rectus; it also gives English rectangle and correct.","cn":"regere 意为「统治、引导、使保持笔直」，过去分词为 rectus；它还给出英语 rectangle 与 correct。"},{"era":"LATIN DIRIGERE","en":"Dis- 'apart, in different directions' plus regere produced dirigere 'to set straight, guide, direct'.","cn":"dis-「分开、朝各方向」加 regere 构成 dirigere「摆直、引导、指挥」。"},{"era":"LATIN DIRECTIO","en":"The action noun directio 'a setting straight, direction' passed through Old French into English as direction.","cn":"动作名词 directio「摆直、指向」经古法语进入英语，成为 direction。"},{"era":"METEOROLOGICAL USE","en":"Wind direction became a routine entry in station records in the nineteenth century; the exact first use of the English phrase is uncertain.","cn":"风向在 19 世纪成为测站记录中的常规项目；这个英语短语的确切最早使用不确定。"}]},"similar":{"note":{"en":"Group one holds wind compounds that sit beside wind direction in the same reports; group two holds navigation words that also describe where something points.","cn":"第一组是同一批天气报告中与风向并列的风类复合词；第二组是同样描述朝向的航行用词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"wind speed","ipa":"/wɪnd spiːd/","tag":"partner quantity","definition":"The rate at which the air moves, the quantity always reported together with wind direction.","definitionCN":"空气移动的速率，总是与风向一起报告。"},{"word":"wind vane","ipa":"/wɪnd veɪn/","tag":"the instrument","definition":"A device that turns to show wind direction; it displays the direction rather than being it.","definitionCN":"转动以显示风向的装置；它显示方向，而不是方向本身。"},{"word":"wind rose","ipa":"/wɪnd rəʊz/","tag":"graph of directions","definition":"A diagram showing how often the wind blows from each direction at a place.","definitionCN":"显示某地风从各方位吹来频率的图。"},{"word":"wind shear","ipa":"/wɪnd ʃɪə/","tag":"change, not direction","definition":"A change in wind speed or direction over a short distance; it describes the gradient, not a single bearing.","definitionCN":"风速或风向在短距离内的变化；它描述梯度，而非单一方位。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bearing","ipa":"/ˈbeərɪŋ/","tag":"angular position","definition":"The angle of a point measured from north; a wind direction can be given as a bearing.","definitionCN":"从北方量起的角度；风向可以用方位角表示。"},{"word":"heading","ipa":"/ˈhedɪŋ/","tag":"where a craft points","definition":"The direction in which a ship or aircraft is pointing, which may differ from the wind direction.","definitionCN":"船或飞机机头所指的方向，可能与风向不同。"},{"word":"course","ipa":"/kɔːs/","tag":"intended path","definition":"The intended path over the ground, a navigational plan rather than a wind reading.","definitionCN":"计划在地面上走的路径，是航行计划而非风的读数。"},{"word":"orientation","ipa":"/ˌɒriənˈteɪʃn/","tag":"alignment","definition":"The way an object is aligned; it can be chosen, whereas wind direction cannot.","definitionCN":"物体摆放的朝向；它可以被选择，而风向不能。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real native noun, a real Latin root and real weather collocations, not invented rhymes.","cn":"正常联想：真实的英语本族名词、真实的拉丁词根与真实天气搭配，而非编造的顺口溜。"},"normal":[{"en":"Meteorology names the wind by where it comes from, so wind direction points to the source.","cn":"气象学按来向给风命名，因此风向指向来源。"},{"en":"direction comes from dirigere 'to set straight', built on regere 'to guide'.","cn":"direction 来自 dirigere「摆直」，其词根是 regere「引导」。"},{"en":"Reports always pair wind direction with wind speed.","cn":"天气报告总把风向与风速并列。"},{"en":"The instruments have their own names: wind vane, windsock, wind direction sensor.","cn":"仪器各有专名：风向标、风向袋、风向传感器。"},{"en":"The same word serves aviation, sailing and air-quality work without changing shape.","cn":"同一个词服务航空、航海与空气质量工作，形态不变。"}],"abstract":[{"en":"Picture a striped sock standing straight out, showing exactly where the air was born.","cn":"想象一只条纹风向袋笔直伸出，指出空气究竟从哪里来。"},{"en":"Picture smoke leaving a chimney and bending away from the houses.","cn":"想象烟从烟囱冒出，弯向远离房屋的一侧。"},{"en":"Picture a committee that quietly changes its mind after one document is read.","cn":"想象一个委员会在读完一份文件后悄悄改变了主意。"}]},"examples":[{"en":"The observer noted a steady wind direction from the south-west.","cn":"观测员记录了稳定的西南风向。"},{"en":"A shift in wind direction pushed the fire toward the ridge.","cn":"风向的转变把火推向山脊。"},{"en":"The wind rose shows the most common wind direction for each month.","cn":"风玫瑰图显示每个月的常见风向。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「风从哪边来」——风来的那个方位，就是风向","word":"wind direction"},"root":"复合短语：wind 来自古英语 wind，属日耳曼语族；direction 经古法语来自拉丁 directio，由 dirigere「摆直、引导」构成，dirigere = dis- + regere「统治、引导」。气象义在 19 世纪成为常规观测项，确切最早书证不确定。","sensesIntro":{"en":"Eight senses follow one line: the source side of the moving air is measured on a compass, reported, read from instruments, followed by pollution, used by aircraft and ships, compared between heights and finally borrowed for public opinion.","cn":"八个义项沿一条线索展开：流动空气的来源方位先被装进罗盘、写进报告、由仪器读出，再被污染物跟随、被飞机与船只使用、在不同高度比较，最后被借去指舆论。"},"semanticMap":{"core":{"en":"CORE IMAGE: a windsock standing straight out, pointing back to where the air came from.","cn":"核心意象：一只风向袋笔直伸出，指回空气的来源。"},"chain":["SOURCE OF WIND","COMPASS BEARING","STATION REPORT","VANE OR SOCK","POLLUTION DRIFT","RUNWAY CHOICE"],"branches":[{"senses":"01 · 02","en":"SOURCE AND SCALE: the source side is fixed, then fitted to the compass.","cn":"来源与刻度：先定来向，再装进罗盘。"},{"senses":"03 · 04","en":"OBSERVATION: a report slot and an instrument reading both carry the same name.","cn":"观测：报告栏目与仪器读数都沿用同一名称。"},{"senses":"05","en":"FOLLOW THE PLUME: pollution work asks only where the air will carry things.","cn":"跟随羽流：污染工作只问空气会把东西带到哪里。"},{"senses":"06 · 07","en":"OPERATIONS AND SHEAR: runways use one bearing, pilots compare two.","cn":"作业与切变：跑道用一个方位，飞行员比较两个高度。"},{"senses":"08","en":"POLITICAL WEATHER: opinion acquires a direction and people watch it turn.","cn":"政治天气：舆论有了方向，人们观察它转向。"}]},"affixes":{"intro":{"en":"The phrase joins wind with direction, and direction brings a whole Latin family: direct, director, directly and directional.","cn":"这个短语把 wind 与 direction 连接起来，而 direction 带来整个拉丁词族：direct、director、directly、directional。"},"latinIntro":{"en":"Latin regere 'to guide' and its compound dirigere 'to set straight' give directio, the source of direction; the family is regular and well recorded.","cn":"拉丁 regere「引导」及其复合词 dirigere「摆直」给出 directio，即 direction 的来源；这个词族规则且记载完整。"},"items":[{"word":"wind","structure":"wind (native noun)","meaning":"moving air","meaningCN":"流动的空气","example":"The wind came off the sea.","exampleCN":"风从海上吹来。"},{"word":"direction","structure":"directio (Latin action noun) via Old French","meaning":"the line along which something points or moves","meaningCN":"某物所指或所沿的路线","example":"The arrow shows the direction of flow.","exampleCN":"箭头显示流动的方向。"},{"word":"direct","structure":"dirigere + -t (verb and adjective)","meaning":"to guide; straight, without detour","meaningCN":"指导；直接的、不绕路的","example":"The sign directs visitors to the gate.","exampleCN":"标牌指引访客去大门。"},{"word":"director","structure":"direct + -or (person who acts)","meaning":"a person who guides an organization","meaningCN":"指导机构的人","example":"The director approved the new route.","exampleCN":"主管批准了新路线。"},{"word":"directly","structure":"direct + -ly (adverb)","meaning":"straight, without intervening steps","meaningCN":"直接地；径直地","example":"The road runs directly north.","exampleCN":"这条路径直向北。"},{"word":"directional","structure":"direction + -al (relating to)","meaning":"relating to direction","meaningCN":"与方向有关的","example":"The antenna is highly directional.","exampleCN":"这根天线方向性很强。"},{"word":"wind vane","structure":"wind + vane (compound noun)","meaning":"an instrument that shows wind direction","meaningCN":"显示风向的仪器","example":"The brass wind vane creaked on the roof.","exampleCN":"屋顶上的铜风向标吱呀作响。"},{"word":"windsock","structure":"wind + sock (compound noun)","meaning":"a fabric cone that shows wind direction and strength","meaningCN":"显示风向与风力的布制圆锥袋","example":"The windsock hung limp in the calm.","exampleCN":"无风时风向袋垂着。"}],"latinEntries":[{"word":"regere","structure":"regere, rexi, rectum (verb, third conjugation)","meaning":"to rule, guide, keep straight","meaningCN":"统治；引导；使保持笔直"},{"word":"dirigere","structure":"dirigere, direxi, directum (verb, third conjugation)","meaning":"to set straight, guide, direct","meaningCN":"摆直；引导；指挥"},{"word":"directio","structure":"directio, directionis (f., third declension)","meaning":"a setting straight, direction","meaningCN":"摆直；方向"}]}},{"word":"hurricane","ipa_uk":"/ˈhʌrɪkən/","ipa_us":"/ˈhɜːrəkeɪn/","definition_zh":"飓风；北大西洋的强热带气旋；十二级以上的狂风；飓风季；比喻猛烈风波","definition_en":"a violent tropical storm with extremely strong winds, especially one formed over the North Atlantic","core_image":"海面被风撕成白色的水墙，棕榈树几乎贴地，天空是一整片旋转的铅灰色云盘","scene":"海边小镇的广播响起，居民正用木板封住窗户，说 A hurricane is expected to make landfall before midnight.","sceneCN":"这里 hurricane 指「在北大西洋形成的强热带气旋」（第 1 个义项：中心气压极低、风速极大的热带风暴系统）；句意为预计飓风将在午夜前登陆。图中可辨识物件：封窗木板、棕榈树、铅灰色云墙、收音机。","pos":[{"tag":"n.","zh":"飓风；强热带气旋（可数，复数 hurricanes）"},{"tag":"n.","zh":"比喻猛烈的事件风波（如政治飓风）"}],"collocations":[{"phrase":"hurricane season","zh":"飓风季"},{"phrase":"hurricane warning","zh":"飓风警报"},{"phrase":"hurricane force","zh":"飓风级风力"},{"phrase":"the eye of the hurricane","zh":"飓风眼"},{"phrase":"hurricane watch","zh":"飓风观察预警"},{"phrase":"hurricane damage","zh":"飓风造成的破坏"}],"forms":[{"label":"复数","form":"hurricanes"},{"label":"定语用法","form":"hurricane"},{"label":"复合形容词（飓风级的）","form":"hurricane-force"},{"label":"复合名词（防风灯）","form":"hurricane lamp"},{"label":"复合名词（追踪飓风的飞机）","form":"hurricane hunter"}],"derivatives":[{"word":"hurricane-force","pos":"adj.","zh":"飓风级的（风力）"},{"word":"hurricanelike","pos":"adj.","zh":"类似飓风的"},{"word":"hurricane lamp","pos":"n.","zh":"防风灯"},{"word":"hurricane season","pos":"n.","zh":"飓风季"},{"word":"hurricane warning","pos":"n.","zh":"飓风警报"}],"senses":[{"no":"01","title":"A North Atlantic tropical cyclone","titleCN":"北大西洋的强热带气旋","definition":"a tropical cyclone with sustained winds of at least seventy-four miles per hour, formed over the North Atlantic or the eastern Pacific","definitionCN":"在北大西洋或东太平洋形成、持续风速至少每小时七十四英里的热带气旋","example":"The hurricane gathered strength over the warm ocean before turning north.","exampleCN":"飓风在温暖的洋面上积蓄力量，然后转向北方。","why":"The word names a regional kind of storm, so its defining feature is where it forms as much as how hard it blows.","whyCN":"这个词指一种区域性风暴，因此其定义特征既在风力，也在形成海域。"},{"no":"02","title":"Wind of extreme force","titleCN":"十二级以上的狂风","definition":"wind strong enough to be classed at hurricane force on the Beaufort scale, regardless of the storm system","definitionCN":"在蒲福风级上达到飓风级的强风，不论其属于哪个风暴系统","example":"The gusts reached hurricane force on the exposed headland.","exampleCN":"在无遮蔽的岬角上，阵风达到了飓风级。","why":"Sailors used the word for the wind before meteorologists used it for the storm, so the force sense survives on its own.","whyCN":"水手先把这个词用于风，气象学家后才用于风暴，因此「风力」义独立存在。"},{"no":"03","title":"The hurricane season","titleCN":"飓风季","definition":"the annual period, usually June to November in the Atlantic, when such storms are most likely","definitionCN":"这类风暴最可能发生的年度时段，大西洋通常为六月至十一月","example":"Insurance rates rise when the hurricane season begins.","exampleCN":"飓风季开始时，保险费率会上涨。","why":"Seasonal planning turned the storm name into a calendar term, with its own fixed collocations.","whyCN":"季节性规划把风暴之名变成日历术语，并固定了搭配。"},{"no":"04","title":"The eye and the eyewall","titleCN":"飓风眼与眼墙","definition":"the calm clear centre of the storm and the ring of violent winds immediately around it","definitionCN":"风暴中心平静晴朗的区域及其周围一圈猛烈风带","example":"The eye of the hurricane passed directly over the island.","exampleCN":"飓风眼正好从岛上经过。","why":"The structure is so distinctive that the storm's own anatomy is discussed using the same word.","whyCN":"这一结构太有辨识度，人们讨论风暴自身的解剖结构时也用同一个词。"},{"no":"05","title":"A category on the Saffir-Simpson scale","titleCN":"萨菲尔－辛普森等级","definition":"one of five numbered categories that rate a hurricane by its sustained wind speed and expected damage","definitionCN":"按持续风速与预期破坏程度把飓风分为五级中的某一级","example":"The storm was upgraded to a category four hurricane overnight.","exampleCN":"这场风暴一夜之间被升为四级飓风。","why":"Forecasters needed a compact severity scale, and the storm word supplies the unit being graded.","whyCN":"预报员需要一个简洁的强度标尺，而风暴之名提供了被分级的单位。"},{"no":"06","title":"A warning to evacuate","titleCN":"飓风警报与疏散","definition":"an official alert that a hurricane is expected in a named area within a set time, often triggering evacuation","definitionCN":"官方通告某地在规定时间内将遭遇飓风，常引发疏散","example":"The hurricane warning sent thousands to higher ground.","exampleCN":"飓风警报让数千人撤往高处。","why":"Emergency management names the alert after the hazard, so the warning is simply 'the hurricane' in official speech.","whyCN":"应急管理按危险源给警报命名，因此在官方话语里警报就叫「飓风」。"},{"no":"07","title":"A figurative storm of events","titleCN":"比喻义：猛烈的风波","definition":"a violent upheaval of criticism, change or emotion that sweeps through an organization or a life","definitionCN":"批评、变化或情绪在组织或人生中横扫而过的猛烈动荡","example":"A hurricane of protest followed the announcement.","exampleCN":"公告之后掀起了一场抗议飓风。","why":"The metaphor keeps the storm's shape: something huge arrives fast, spins everything and leaves damage behind.","whyCN":"这个比喻保留了风暴的形状：巨大的东西快速到来，把一切卷起，再留下破坏。"},{"no":"08","title":"A hurricane lamp","titleCN":"防风灯","definition":"a lamp with a protected flame or bulb that keeps burning in strong wind","definitionCN":"带防护罩、能在强风中继续燃烧或发光的灯","example":"They lit a hurricane lamp when the power failed.","exampleCN":"停电时他们点起一盏防风灯。","why":"The lamp is named for the wind it resists, so 'hurricane' here describes a protection standard rather than a storm.","whyCN":"这种灯因能抗风而得名，因此这里的 hurricane 描述的是防护标准，而不是风暴。"}],"etymology":{"intro":{"en":"Hurricane came into English through Spanish huracán, and the usual account traces it to a Caribbean word recorded as hurakán. The deeper origin is debated, so the safest statement is that the Caribbean source is generally accepted while the pre-Columbian root remains uncertain.","cn":"hurricane 经西班牙语 huracán 进入英语，通常的说法把它上溯到一个加勒比词语 hurakán。更深的来源仍有争议，因此最稳妥的表述是：加勒比来源一般认为是可靠的，而哥伦布时期之前的词根仍不确定。"},"items":[{"era":"CARIBBEAN HURAKÁN","en":"Sources record a Carib or Taino word hurakán for a violent storm; it is generally accepted as the origin, though the spelling and the exact language vary between accounts.","cn":"文献记录了一个加勒比或泰诺语词 hurakán，意为猛烈风暴；一般认为它就是来源，但各家记载的拼写与具体语言并不一致。"},{"era":"SPANISH HURACÁN","en":"Spanish sailors adopted the Caribbean word as huracán and used it for the storms they met in the Caribbean Sea.","cn":"西班牙水手把这个加勒比词采纳为 huracán，用来指他们在加勒比海遇到的风暴。"},{"era":"ENGLISH SIXTEENTH CENTURY","en":"English borrowed the Spanish form in the sixteenth century, first in travel and navigation writing.","cn":"英语在 16 世纪借入西班牙语形式，最早见于旅行与航海文献。"},{"era":"METEOROLOGICAL DEFINITION","en":"In the nineteenth and twentieth centuries the word was fixed to tropical cyclones of the North Atlantic, giving it a precise regional meaning.","cn":"在 19 与 20 世纪，这个词被固定指北大西洋的热带气旋，获得了精确的区域含义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root): the pre-Columbian origin cannot be reconstructed with confidence, and other proposals exist; they should be listed as hypotheses, not chosen as fact.","cn":"来源不确定（更深词根）：哥伦布时期之前的来源无法可靠重构，另有其他假说；这些只应并列，不应择一定为事实。"}]},"similar":{"note":{"en":"Group one holds phrases built on the word hurricane that are not the storm itself; group two holds other storm names and wind words that are constantly confused with it.","cn":"第一组是由 hurricane 构成、但并不指风暴本身的短语；第二组是常与它混淆的其他风暴名与风类词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hurricane lamp","ipa":"/ˈhʌrɪkən læmp/","tag":"an object, not a storm","definition":"A lamp built to keep burning in strong wind; the word describes its protection, not a weather system.","definitionCN":"为在强风中持续燃烧而造的灯；这里的词描述防护性能，而非天气系统。"},{"word":"hurricane-force","ipa":"/ˈhʌrɪkən fɔːs/","tag":"a wind grade","definition":"An adjective for winds of Beaufort twelve or above, which may occur without any tropical storm.","definitionCN":"形容蒲福十二级以上的风，这种风可以在没有热带风暴时出现。"},{"word":"hurricane season","ipa":"/ˈhʌrɪkən ˈsiːzn/","tag":"a calendar period","definition":"The yearly window when such storms are likely; it is a period, not a single event.","definitionCN":"这类风暴可能发生的年度时段；它是一段时间，不是单次事件。"},{"word":"hurricane warning","ipa":"/ˈhʌrɪkən ˈwɔːnɪŋ/","tag":"an official alert","definition":"A formal notice that hurricane conditions are expected; the warning is not the storm.","definitionCN":"预告将出现飓风条件的正式通告；警报并不是风暴本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"typhoon","ipa":"/taɪˈfuːn/","tag":"western Pacific name","definition":"The same kind of tropical cyclone, but the name used in the western North Pacific; region, not strength, separates it from hurricane.","definitionCN":"同类的热带气旋，但用于西北太平洋；区别在海域而非强度。"},{"word":"cyclone","ipa":"/ˈsaɪkləʊn/","tag":"wider term","definition":"The general meteorological term for any rotating low-pressure system, including hurricanes and typhoons.","definitionCN":"指任何旋转低压系统的通用气象术语，包括飓风与台风。"},{"word":"tornado","ipa":"/tɔːˈneɪdəʊ/","tag":"small and land-based","definition":"A much smaller, short-lived vortex formed over land, not a vast tropical storm.","definitionCN":"在陆地上形成的规模小得多、寿命很短的涡旋，不是庞大的热带风暴。"},{"word":"gale","ipa":"/ɡeɪl/","tag":"strong wind only","definition":"A very strong wind, graded on the Beaufort scale, with no organised storm structure.","definitionCN":"极强的风，按蒲福风级划分，没有组织化的风暴结构。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real borrowing path, real storm collocations and real compounds, not invented rhymes.","cn":"正常联想：真实的借词路径、真实风暴搭配与真实复合词，而非编造的顺口溜。"},"normal":[{"en":"Spanish huracán from a Caribbean word hurakán; the borrowing path is the memory hook.","cn":"西班牙语 huracán 来自加勒比词 hurakán；借词路径就是记忆钩子。"},{"en":"Region decides the name: hurricane in the Atlantic, typhoon in the western Pacific, cyclone as the general term.","cn":"海域决定名称：大西洋叫飓风，西北太平洋叫台风，气旋是通称。"},{"en":"Fixed phrases mark the season: hurricane season, hurricane warning, hurricane watch.","cn":"固定搭配标出季节：飓风季、飓风警报、飓风观察预警。"},{"en":"The structure has its own vocabulary: eye, eyewall, storm surge.","cn":"风暴结构有自己的词汇：风眼、眼墙、风暴潮。"},{"en":"A hurricane lamp is named for the wind it resists, not for a storm it contains.","cn":"防风灯因能抗风而得名，而不是因为它装着风暴。"}],"abstract":[{"en":"Picture a city-sized wheel of cloud turning over a warm sea.","cn":"想象一个城市大小的云轮在温暖海面上旋转。"},{"en":"Picture a single calm room at the centre of a roaring building.","cn":"想象一座轰响建筑的中心，有一间安静的房间。"},{"en":"Picture a rumour that arrives like weather and leaves roofs torn open.","cn":"想象一则像天气一样到来的谣言，走后留下掀开的屋顶。"}]},"examples":[{"en":"The hurricane destroyed the pier and flooded the lower streets.","cn":"飓风摧毁了码头，淹没了低处的街道。"},{"en":"Forecasters tracked the hurricane for five days before it turned.","cn":"预报员追踪这场飓风五天之后它才转向。"},{"en":"A hurricane of criticism followed the budget announcement.","cn":"预算公告之后掀起了一阵批评的飓风。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「哈瑞肯」——一个叫哈瑞的名字被狂风卷上了天，就成了飓风","word":"hurricane"},"root":"经西班牙语 huracán 借入英语，一般认为是加勒比（泰诺或加勒比语）词 hurakán「猛烈风暴」；更早词根无法可靠重构，另有其他假说，只宜并列而不选定论。该词无拉丁语同族来源。","sensesIntro":{"en":"Eight senses follow one line: a Caribbean storm word becomes a North Atlantic cyclone, then its wind grade, its season, its anatomy, its severity scale, its warning, its figurative storm and finally an object named for the wind it resists.","cn":"八个义项沿一条线索展开：一个加勒比风暴词先成为北大西洋气旋，再成为风力等级、季节、结构、强度分级、警报、比喻风波，最后变成一个以抗风命名的物件。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wall of white water and palms bent almost flat under a lead-grey sky.","cn":"核心意象：白色水墙、几乎贴地的棕榈，以及铅灰色的天空。"},"chain":["CARIBBEAN STORM WORD","ATLANTIC CYCLONE","EXTREME WIND","STORM ANATOMY","SEVERITY SCALE","EVACUATION ALERT"],"branches":[{"senses":"01 · 02","en":"STORM AND WIND: the name covers both the whole system and its strongest air.","cn":"风暴与风：这个名字既指整个系统，也指它最强的空气。"},{"senses":"03 · 04","en":"SEASON AND STRUCTURE: planners watch the calendar, meteorologists watch the eye.","cn":"季节与结构：规划者看日历，气象学家看风眼。"},{"senses":"05 · 06","en":"SCALE AND WARNING: a number grades the storm, and an alert moves people.","cn":"分级与警报：数字给风暴定级，警报把人撤走。"},{"senses":"07","en":"SOCIAL STORM: the same shape is borrowed for violent public reaction.","cn":"社会风暴：同样的形状被借去形容激烈的公众反应。"},{"senses":"08","en":"THE LAMP: a protected flame is named for the wind it survives.","cn":"防风灯：受保护的火焰以它能扛住的风命名。"}]},"affixes":{"intro":{"en":"Hurricane is a borrowed whole word, so it has no Latin prefix or suffix to split; its family is built by compounding with nouns such as season, lamp and warning.","cn":"hurricane 是整体借入的词，没有可拆的拉丁前缀或后缀；它的词族靠与 season、lamp、warning 等名词复合而成。"},"latinIntro":{"en":"There is no Latin source or Latin cognate for this Caribbean borrowing, so no Latin entries are listed; Latin tempestas is only a semantic equivalent.","cn":"这个加勒比借词没有拉丁语来源，也没有拉丁同族词，因此不列拉丁词条；拉丁语 tempestas 只是语义对应词。"},"items":[{"word":"hurricane","structure":"hurricane (borrowed noun, Spanish huracán)","meaning":"a violent tropical storm","meaningCN":"猛烈的热带风暴","example":"The hurricane approached the coast.","exampleCN":"飓风逼近海岸。"},{"word":"hurricanes","structure":"hurricane + -s (plural)","meaning":"more than one such storm","meaningCN":"多场这样的风暴","example":"Two hurricanes formed in one week.","exampleCN":"一周内形成了两场飓风。"},{"word":"hurricane-force","structure":"hurricane + force (compound adjective)","meaning":"of Beaufort twelve or above","meaningCN":"蒲福十二级以上的","example":"Hurricane-force gusts closed the bridge.","exampleCN":"飓风级阵风使大桥关闭。"},{"word":"hurricane lamp","structure":"hurricane + lamp (compound noun)","meaning":"a lamp that resists strong wind","meaningCN":"能抗强风的灯","example":"The hurricane lamp burned all night.","exampleCN":"防风灯整夜亮着。"},{"word":"hurricane season","structure":"hurricane + season (compound noun)","meaning":"the yearly storm period","meaningCN":"每年的风暴季","example":"The islands prepare before hurricane season.","exampleCN":"群岛在飓风季前做好准备。"},{"word":"hurricane warning","structure":"hurricane + warning (compound noun)","meaning":"an official alert of expected hurricane conditions","meaningCN":"预告将出现飓风条件的官方警报","example":"The hurricane warning covered three counties.","exampleCN":"飓风警报覆盖了三个县。"},{"word":"hurricane eye","structure":"hurricane + eye (compound noun)","meaning":"the calm centre of the storm","meaningCN":"风暴平静的中心","example":"The wind dropped inside the hurricane eye.","exampleCN":"进入飓风眼后风停了。"},{"word":"hurricane hunter","structure":"hurricane + hunter (compound noun)","meaning":"an aircraft that flies into storms to collect data","meaningCN":"飞入风暴采集数据的飞机","example":"A hurricane hunter measured the central pressure.","exampleCN":"一架飓风追踪飞机测量了中心气压。"}],"latinEntries":[]}},{"word":"cyclone","ipa_uk":"/ˈsaɪkləʊn/","ipa_us":"/ˈsaɪkloʊn/","definition_zh":"气旋；热带风暴；低压环流；旋风分离器","definition_en":"a weather system in which winds rotate inward around a low-pressure centre","core_image":"一大团云系绕着中心低压逆时针收紧，风从四面灌入、再被甩向外围","scene":"气象台的屏幕上，一团云系逆时针向内旋紧，值班员指着它说 A cyclone is tightening its grip on the coast tonight.","sceneCN":"这里 cyclone 指「热带风暴系统」（第 1 个义项：暖海面上生成、风绕低压中心旋转的强风暴）；句意为今晚一个气旋正在收紧对海岸的掌控。","pos":[{"tag":"n.","zh":"气旋；热带风暴；低压环流系统"}],"collocations":[{"phrase":"tropical cyclone","zh":"热带气旋"},{"phrase":"extratropical cyclone","zh":"温带气旋"},{"phrase":"cyclone warning","zh":"气旋警报"},{"phrase":"cyclone season","zh":"气旋季"},{"phrase":"cyclone shelter","zh":"避风所；气旋避难所"},{"phrase":"cyclone separator","zh":"旋风分离器"}],"forms":[{"label":"单数（原形）","form":"cyclone"},{"label":"复数","form":"cyclones"},{"label":"形容词","form":"cyclonic"},{"label":"副词","form":"cyclonically"},{"label":"复合名词","form":"cyclone separator"}],"derivatives":[{"word":"cyclonic","pos":"adj.","zh":"气旋的；旋转的"},{"word":"cyclonically","pos":"adv.","zh":"以气旋方式；旋转地"},{"word":"anticyclone","pos":"n.","zh":"反气旋；高气压系统"},{"word":"cyclogenesis","pos":"n.","zh":"气旋生成"},{"word":"cyclolysis","pos":"n.","zh":"气旋消散"}],"senses":[{"no":"01","title":"Tropical storm with rotating winds","titleCN":"热带气旋：风绕低压中心旋转的强风暴","definition":"a violent tropical storm in which strong winds rotate around a centre of low pressure","definitionCN":"强风围绕低压中心旋转的猛烈热带风暴","example":"The cyclone tore roofs off houses along the delta.","exampleCN":"气旋把三角洲一带房屋的屋顶掀掉了。","why":"The Greek root means a wheel or a coil, so the storm is named for the circular path its winds trace.","whyCN":"希腊词根意为轮子或盘绕之物，因此这场风暴是按风的圆形路径命名的。"},{"no":"02","title":"The official name in the Indian Ocean","titleCN":"印度洋与南太平洋的官方称名","definition":"the official term used in the Indian Ocean and South Pacific for a tropical storm of hurricane strength","definitionCN":"印度洋与南太平洋对达到飓风强度的热带风暴所用的正式称名","example":"Cyclone Fani forced the evacuation of millions in Odisha.","exampleCN":"气旋「法尼」迫使奥迪沙邦数百万人撤离。","why":"Storm basins name the same phenomenon differently: hurricane in the Atlantic, typhoon in the Pacific, cyclone in the Indian Ocean.","whyCN":"各风暴海域对同一现象有不同叫法：大西洋叫 hurricane，太平洋叫 typhoon，印度洋叫 cyclone。"},{"no":"03","title":"Extratropical low-pressure system","titleCN":"温带气旋：中纬度的低压系统","definition":"a large low-pressure system outside the tropics whose fronts bring gales and heavy rain","definitionCN":"热带以外的大型低压系统，其锋面带来大风与大雨","example":"An extratropical cyclone brought two days of rain to the region.","exampleCN":"一个温带气旋给该地区带来了两天降雨。","why":"The rotating structure is the defining feature, so the word extends beyond the tropics to any organised low.","whyCN":"旋转结构才是定义特征，因此这个词从热带扩展到任何有组织的低压系统。"},{"no":"04","title":"Cyclonic circulation","titleCN":"气旋式环流：向内旋入的风场","definition":"the inward-spiralling wind pattern around a low-pressure centre, counter-clockwise in the northern hemisphere","definitionCN":"围绕低压中心向内旋入的风场，在北半球呈逆时针方向","example":"Satellite images showed a tight cyclonic circulation near the islands.","exampleCN":"卫星图像显示岛屿附近有一个紧密的气旋式环流。","why":"Here the word names the motion rather than the storm, and the same geometry appears at every scale of low pressure.","whyCN":"这里指的不是风暴本身而是运动形态，同一几何形状出现在各种尺度的低压系统里。"},{"no":"05","title":"The storm as a destructive event","titleCN":"作为灾害事件的风暴","definition":"the storm viewed as an event that strikes a coast with wind, rain and storm surge","definitionCN":"从侵袭海岸、带来狂风、暴雨与风暴潮的事件角度看的风暴","example":"The cyclone left the harbour closed for a week.","exampleCN":"这场气旋让港口关闭了一周。","why":"News reports talk about the event rather than the physics, so the word comes to mean the disaster itself.","whyCN":"新闻报道谈的是事件而非物理机制，因此这个词转而指灾害本身。"},{"no":"06","title":"A low-pressure area on a weather chart","titleCN":"天气图上的低压区","definition":"a low-pressure area marked on a synoptic chart, with closed isobars around its centre","definitionCN":"天气图上以闭合等压线围出中心的低压区","example":"The chart shows a cyclone deepening over the bay.","exampleCN":"天气图显示一个气旋正在海湾上空加深。","why":"Meteorologists label the pressure pattern, not just the storm, and the same word covers both.","whyCN":"气象学家标注的是气压形势而不只是风暴，同一个词覆盖两者。"},{"no":"07","title":"Figurative whirl of events","titleCN":"比喻义：事件或情绪的漩涡","definition":"a rapidly swirling mass of events, emotions or activity that draws people in","definitionCN":"迅速旋转、把人卷进去的事件、情绪或活动","example":"A cyclone of rumours swept through the newsroom.","exampleCN":"一场谣言的漩涡席卷了新闻编辑室。","why":"The metaphor keeps the shape of the weather: everything is pulled inward and spun faster and faster.","whyCN":"这个比喻保留了天气的形状：一切被吸向中心，越转越快。"},{"no":"08","title":"Industrial cyclone separator","titleCN":"工业旋风分离器","definition":"a cone-shaped device that spins dusty air so particles fall out and clean air rises","definitionCN":"让含尘空气旋转、使颗粒落下而洁净空气上升的锥形装置","example":"The sawmill uses a cyclone to collect sawdust from the air.","exampleCN":"锯木厂用旋风分离器从空气中收集锯屑。","why":"Engineers copied the storm's geometry: a spinning vortex throws heavy particles outward and downward.","whyCN":"工程师照搬了风暴的几何：旋转涡流把较重颗粒甩向外侧和下方。"}],"etymology":{"intro":{"en":"Cyclone was coined in the nineteenth century from Greek kyklos 'circle, wheel' and its derivative kykloma 'that which rolls'. The root is Greek, and Latin borrowed the same word as cyclus.","cn":"cyclone 于 19 世纪由希腊语 kyklos「圆、轮」及其派生词 kyklōma「滚动之物」造出。词根属希腊语，拉丁语也借入了同一个词作 cyclus。"},"items":[{"era":"GREEK KYKLOS","en":"Kyklos meant 'circle, wheel' and appears in kyklos trokhos 'wheel'; it is the source of English cycle and cyclical.","cn":"kyklos 意为「圆、轮」，见于 kyklos trokhos「车轮」；它是英语 cycle、cyclical 的来源。"},{"era":"GREEK KYKLOMA","en":"Kykloma, from kykloun 'to move in a circle', named a wheel or a coiled object, and supplied the shape of the second half of the word.","cn":"kyklōma 出自 kykloun「作圆周运动」，指轮子或盘绕之物，提供了这个词后半部分的形态。"},{"era":"LATIN CYCLUS","en":"Latin borrowed the Greek noun as cyclus 'circle, cycle', with the adjective cyclicus; the Latin form kept the k-sound written as c.","cn":"拉丁语借入这个希腊名词作 cyclus「圆、循环」，形容词为 cyclicus；拉丁拼写用 c 记这个 k 音。"},{"era":"ENGLISH NINETEENTH CENTURY","en":"In 1848 a British meteorologist proposed cyclone for the circular storms of the Indian Ocean, forming it on the Greek noun for a whirling thing.","cn":"1848 年一位英国气象学者提议用 cyclone 命名印度洋的圆形风暴，依据的是希腊语中表示旋转之物的名词。"},{"era":"MODERN METEOROLOGY","en":"The word spread to all tropical basins and then to any low-pressure system with closed circulation; the industrial sense came later by analogy.","cn":"这个词随后扩展到所有热带海域，再扩展到任何具有闭合环流的低压系统；工业义则更晚由类比产生。"}]},"similar":{"note":{"en":"The first group contains words that look or sound close to cyclone; the second contains the other names for rotating storms and their opposite.","cn":"第一组是形音相近的词；第二组是旋转风暴的其他名称及其对立面。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cycle","ipa":"/ˈsaɪkl/","tag":"same Greek root","definition":"From Greek kyklos 'circle, wheel' through Latin cyclus: a recurring round of events, or a bicycle. It shares the root but not the storm meaning.","definitionCN":"经拉丁语 cyclus 来自希腊 kyklos「圆、轮」：循环的一轮，或自行车。同根但无风暴义。"},{"word":"cyclist","ipa":"/ˈsaɪklɪst/","tag":"same root, person noun","definition":"A person who rides a cycle; the ending -ist marks a person, so it cannot name a weather system.","definitionCN":"骑自行车的人；后缀 -ist 表人，因此不能指天气系统。"},{"word":"cylinder","ipa":"/ˈsɪlɪndər/","tag":"different Greek root","definition":"From Greek kylindros 'roller', a different root from kyklos; it names a solid with circular ends.","definitionCN":"来自希腊 kylindros「滚子」，与 kyklos 不同根；指两端为圆的立体。"},{"word":"cynical","ipa":"/ˈsɪnɪkl/","tag":"different Greek root","definition":"From Greek kynikos 'dog-like', the root of Cynic philosophy; it has nothing to do with circles or storms.","definitionCN":"来自希腊 kynikos「像狗的」，是犬儒学派词根；与圆或风暴无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hurricane","ipa":"/ˈhʌrɪkən/","tag":"Atlantic name","definition":"The Atlantic and eastern Pacific name for a tropical cyclone with sustained winds of at least 119 km/h.","definitionCN":"大西洋与东太平洋对持续风速至少每小时 119 公里的热带气旋的称名。"},{"word":"typhoon","ipa":"/taɪˈfuːn/","tag":"Pacific name","definition":"The western Pacific name for the same kind of storm; only the basin, not the physics, differs.","definitionCN":"西太平洋对同一类风暴的称名；差别只在海域而不在物理机制。"},{"word":"tornado","ipa":"/tɔːˈneɪdəʊ/","tag":"smaller vortex","definition":"A much smaller, violently rotating column of air reaching the ground from a thundercloud.","definitionCN":"小得多、从雷暴云伸到地面的猛烈旋转空气柱。"},{"word":"anticyclone","ipa":"/ˌæntiˈsaɪkləʊn/","tag":"opposite pressure","definition":"A high-pressure system with outward-spiralling winds; it is the mirror image, not a synonym.","definitionCN":"风向外旋出的高压系统；是镜像对立面而非同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Greek root, real meteorological compounds and the real derived family, not invented rhymes.","cn":"正常联想：希腊词根、真实气象复合词与真实派生词族，而非编造的顺口溜。"},"normal":[{"en":"kyklos 'circle' is the whole word: a storm that runs in circles.","cn":"kyklos「圆」就是全部要义：绕圈跑的风暴。"},{"en":"The same root sits in cycle, bicycle and cyclical.","cn":"同一词根在 cycle、bicycle、cyclical 里。"},{"en":"Basin names sit in a row: hurricane, typhoon, cyclone.","cn":"三个海域的名称并排记：hurricane、typhoon、cyclone。"},{"en":"The adjective is cyclonic, as in cyclonic circulation.","cn":"形容词是 cyclonic，如气旋式环流。"},{"en":"Cyclogenesis is birth, cyclolysis is death, of a cyclone.","cn":"cyclogenesis 是气旋的生成，cyclolysis 是气旋的消散。"}],"abstract":[{"en":"Picture water draining from a basin, faster and faster toward the hole.","cn":"想象水从盆里排出，越靠近洞口转得越快。"},{"en":"Picture a rumour spinning through an office and pulling everyone inward.","cn":"想象一则谣言在办公室里打转，把每个人往里卷。"},{"en":"Picture dust in a cone, thrown to the wall while clean air climbs the middle.","cn":"想象锥体里的粉尘被甩到壁上，干净空气从中间上升。"}]},"examples":[{"en":"The cyclone destroyed the coastal road and cut off three villages.","cn":"气旋毁掉了沿海公路，切断了三个村庄的交通。"},{"en":"Forecasters track a cyclone by its closed isobars and cloud spiral.","cn":"预报员靠闭合等压线和云系螺旋追踪气旋。"},{"en":"A cyclone separator removes most of the dust before the air reaches the filter.","cn":"旋风分离器在空气进入过滤器之前除去大部分粉尘。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「赛克隆」——云团赛跑一样克隆出一圈圈旋转的风","word":"cyclone"},"root":"希腊 kyklos「圆、轮」→ kyklōma「滚动之物」；1848 年由气象学者据此造词命名印度洋的圆形风暴。词根清楚，命名年代有明确记载；与拉丁 cyclus 同源。","sensesIntro":{"en":"Eight senses follow one shape: air spiralling around a low, from a tropical storm and its regional name, through temperate lows, circulation, disaster and chart symbol, to a metaphor and a machine.","cn":"八个义项沿一个形状展开：空气绕低压旋转——从热带风暴及其地域称名，经温带低压、环流、灾害与天气图符号，到比喻义与机器。"},"semanticMap":{"core":{"en":"CORE IMAGE: a spiral of cloud winding inward around a low-pressure eye.","cn":"核心意象：云带绕低压眼向内盘绕的螺旋。"},"chain":["LOW PRESSURE FORMS","WARM OCEAN FEEDS IT","WIND SPIRALS INWARD","STORM GETS A NAME","COAST IS STRUCK","VORTEX IS REUSED"],"branches":[{"senses":"01 · 02","en":"TROPICAL AND NAMED: the same storm is a cyclone everywhere, but only Indian Ocean forecasts use that name officially.","cn":"热带与命名：同一场风暴在各处都是气旋，但只有印度洋的预报正式使用这个名称。"},{"senses":"03 · 06","en":"COLD AND CHARTED: outside the tropics the same low appears as a pressure pattern on the map.","cn":"温带与图面：热带之外同一个低压以图上的气压形势出现。"},{"senses":"04 · 05","en":"MOTION AND IMPACT: the inward spiral is the mechanism, the landfall is the event people remember.","cn":"运动与影响：向内螺旋是机制，登陆是人们记住的事件。"},{"senses":"07","en":"SOCIAL WHIRL: events and feelings can spin inward the way air does.","cn":"社会漩涡：事件与情绪可以像空气那样向内旋转。"},{"senses":"08","en":"MACHINE COPY: industry builds the same vortex in a cone to sort dust from air.","cn":"机器复制：工业在锥体里造出同样的涡流，把粉尘与空气分开。"}]},"affixes":{"intro":{"en":"Cyclone is Greek root plus a Greek-derived ending, with no native English suffix. Its family grows through -ic, -ically, anti- and the combining forms cyclo- and -genesis.","cn":"cyclone 是希腊词根加希腊来源的词尾，没有本土英语后缀。它的词族靠 -ic、-ically、anti- 以及组合成分 cyclo-、-genesis 扩展。"},"latinIntro":{"en":"Latin borrowed the Greek noun as cyclus and formed the adjective cyclicus; those forms are the bridge by which the root reached English spelling.","cn":"拉丁语借入这个希腊名词作 cyclus，并构成形容词 cyclicus；这些形式是词根进入英语拼写的桥梁。"},"items":[{"word":"cyclo-","structure":"cyclo- (Greek combining form from kyklos 'circle')","meaning":"circle; wheel; cyclic","meaningCN":"圆；轮；循环","example":"Cyclo- appears in cyclorama and cyclotron.","exampleCN":"cyclo- 出现在 cyclorama（环形画景）与 cyclotron（回旋加速器）中。"},{"word":"kyklos","structure":"kyklos (Greek noun, second declension)","meaning":"circle, wheel","meaningCN":"圆；轮","example":"The root underlies cycle and encyclopedia.","exampleCN":"这个词根是 cycle 与 encyclopedia 的基础。"},{"word":"-one","structure":"-one (terminal element borrowed with the Greek noun, not a productive suffix)","meaning":"the ending carried over from Greek kykloma","meaningCN":"随希腊名词借入的词尾，并非能产后缀","example":"The ending appears in cyclone but builds no new English words.","exampleCN":"这个词尾只出现在 cyclone 里，不能构成新的英语词。"},{"word":"cyclonic","structure":"cyclone + -ic (relating to)","meaning":"relating to a cyclone or to rotating winds","meaningCN":"气旋的；旋转风的","example":"Cyclonic winds closed the ferry service.","exampleCN":"气旋性大风使渡轮停航。"},{"word":"cyclonically","structure":"cyclonic + -ally (in a manner)","meaning":"in a cyclonic manner","meaningCN":"以气旋方式","example":"The air turned cyclonically around the centre.","exampleCN":"空气绕中心作气旋式旋转。"},{"word":"anticyclone","structure":"anti- 'against, opposite' + cyclone","meaning":"a high-pressure system with outward winds","meaningCN":"风向外流的高压系统","example":"The anticyclone kept the sky clear for a week.","exampleCN":"反气旋让天空连续一周晴朗。"},{"word":"cyclogenesis","structure":"cyclo- + -genesis 'birth, origin'","meaning":"the formation and strengthening of a cyclone","meaningCN":"气旋的生成与加强","example":"Cyclogenesis began over the warm shelf water.","exampleCN":"气旋生成在温暖的陆架海面上开始。"},{"word":"cyclolysis","structure":"cyclo- + -lysis 'loosening, dissolution'","meaning":"the weakening and decay of a cyclone","meaningCN":"气旋的减弱与消散","example":"Cyclolysis followed quickly after landfall.","exampleCN":"登陆之后气旋迅速消散。"}],"latinEntries":[{"word":"cyclus","structure":"cyclus, cycli (m., second declension; borrowed from Greek kyklos)","meaning":"circle, cycle, wheel","meaningCN":"圆；循环；轮"},{"word":"cyclicus","structure":"cyclicus, cyclica, cyclicum (adjective; from Greek kyklikos)","meaning":"circular, of a cycle","meaningCN":"圆的；循环的"}]}},{"word":"typhoon","ipa_uk":"/taɪˈfuːn/","ipa_us":"/taɪˈfuːn/","definition_zh":"台风；西北太平洋热带气旋；台风信号；避风塘","definition_en":"a tropical cyclone of the western North Pacific, with winds rotating around a low-pressure centre","core_image":"暖海面上密云堆成巨大螺旋，中心露出安静的圆孔，边缘雨带像裙摆甩动","scene":"渡轮码头挂起风球，广播反复提醒旅客，值班员说 A typhoon is expected to pass south of the islands tomorrow.","sceneCN":"这里 typhoon 指「西北太平洋的热带气旋」（第 1 个义项：暖海生成、风绕低压中心旋转的强风暴）；句意为预计明天会有一个台风从群岛以南经过。","pos":[{"tag":"n.","zh":"台风；西北太平洋热带气旋"}],"collocations":[{"phrase":"typhoon season","zh":"台风季"},{"phrase":"typhoon warning","zh":"台风警报"},{"phrase":"typhoon signal","zh":"台风信号"},{"phrase":"typhoon shelter","zh":"避风塘"},{"phrase":"super typhoon","zh":"超强台风"},{"phrase":"typhoon eye","zh":"台风眼"}],"forms":[{"label":"单数（原形）","form":"typhoon"},{"label":"复数","form":"typhoons"},{"label":"定语用法（作修饰语）","form":"typhoon"},{"label":"复合形容词（风力达台风级）","form":"typhoon-force"},{"label":"复合名词（超强台风）","form":"super typhoon"}],"derivatives":[{"word":"super typhoon","pos":"n.","zh":"超强台风（持续风速达到规定上限以上的台风）"},{"word":"typhoon shelter","pos":"n.","zh":"避风塘；供船只避风的港湾"},{"word":"typhoon-proof","pos":"adj.","zh":"防台风的；经得起台风侵袭的"},{"word":"typhoon-force","pos":"adj.","zh":"台风级的（形容风力）"},{"word":"typhoon-like","pos":"adj.","zh":"台风般的"}],"senses":[{"no":"01","title":"Tropical cyclone of the western Pacific","titleCN":"台风：西北太平洋的热带气旋","definition":"a tropical cyclone that forms in the western North Pacific or the South China Sea","definitionCN":"在西北太平洋或南海生成的热带气旋","example":"The typhoon gathered strength over the warm Kuroshio current.","exampleCN":"台风在温暖的黒潮上空积蓄力量。","why":"This is the technical sense: a warm-core storm whose winds circle a low-pressure eye.","whyCN":"这是技术义：一个暖核风暴，风绕着低压眼区旋转。"},{"no":"02","title":"The Pacific name for a hurricane","titleCN":"飓风在太平洋的称名","definition":"the basin-specific name for a storm that Atlantic forecasters would call a hurricane","definitionCN":"大西洋预报员称为飓风的同一类风暴在太平洋海域的名称","example":"The same storm would be called a typhoon west of the date line.","exampleCN":"同一场风暴在日期变更线以西就会被称为台风。","why":"Basins keep separate naming lists, so the label changes with longitude while the physics does not.","whyCN":"各海域各有命名表，因此名称随经度改变，而物理机制不变。"},{"no":"03","title":"A landfall disaster","titleCN":"登陆成灾的台风事件","definition":"the storm viewed as the event that brings storm surge, landslides and flooding to a coast","definitionCN":"从给海岸带来风暴潮、滑坡与洪水的灾害事件角度看的台风","example":"The typhoon flooded the low-lying districts within hours.","exampleCN":"台风在几小时内淹没了低洼城区。","why":"News and insurance talk about the event, so the word shifts from the system to its consequences.","whyCN":"新闻与保险谈的是事件，因此这个词从天气系统转向其后果。"},{"no":"04","title":"Any violent windstorm in older usage","titleCN":"旧用法：泛指猛烈的风暴","definition":"in older literary and nautical writing, any violent revolving storm at sea","definitionCN":"在较早的文学与航海文字中，泛指海上任何猛烈的旋转风暴","example":"Sailors in the old logs feared every typhoon as a matter of course.","exampleCN":"旧航海日志里的水手理所当然地畏惧每一场风暴。","why":"Before storms were classified by basin, the word covered any great tempest, and that broad sense survives in literary prose.","whyCN":"在按海域分类之前，这个词涵盖任何大风暴，这一宽泛义仍留在文学语言里。"},{"no":"05","title":"The yearly typhoon season","titleCN":"每年的台风季","definition":"the annual period, roughly summer and autumn, when typhoons are most frequent","definitionCN":"台风最频繁的年度时段，大致为夏秋两季","example":"Building work stops during the typhoon season.","exampleCN":"建筑施工在台风季停工。","why":"The word names the season by its dominant weather, a common pattern with weather nouns.","whyCN":"这个词用主导天气给季节命名，这是天气名词常见的模式。"},{"no":"06","title":"A sheltered anchorage","titleCN":"避风塘：供船只避风的港湾","definition":"a harbour or cove where boats take refuge from a storm, as in the Hong Kong place name Typhoon Shelter","definitionCN":"船只躲避风暴的港湾或小湾，如香港地名中的「避风塘」","example":"The fishing fleet waited out the storm in a typhoon shelter.","exampleCN":"渔船队在避风塘里等风暴过去。","why":"A place gets its name from the weather it defends against, and the phrase became a fixed noun.","whyCN":"一个地方以它所抵御的天气得名，这个短语便固定成了名词。"},{"no":"07","title":"Figurative storm of criticism","titleCN":"比喻义：批评或情绪的暴风","definition":"a sudden, overwhelming outburst of criticism, anger or emotion","definitionCN":"批评、愤怒或情绪的突然而压倒性的爆发","example":"A typhoon of criticism met the proposal on social media.","exampleCN":"这项提案在社交媒体上遭遇了一场批评的暴风。","why":"The metaphor borrows the storm's force and spin: it arrives suddenly and leaves nothing standing.","whyCN":"这个比喻借用了风暴的力量与旋转：突然到来，所过之处一片狼藉。"},{"no":"08","title":"Official warning signals","titleCN":"官方台风信号","definition":"the numbered signal hoisted by weather services to warn of approaching typhoon winds","definitionCN":"气象部门为预警逼近的台风风力而悬挂的编号信号","example":"Schools closed when the typhoon signal reached the highest level.","exampleCN":"台风信号升到最高级别时学校停课。","why":"The signal is named for the storm it announces, so the word also appears in the fixed administrative phrase.","whyCN":"信号以它所预告的风暴命名，因此这个词也出现在固定的行政用语里。"}],"etymology":{"intro":{"en":"Typhoon reached English through Portuguese, and the chain behind it runs to Arabic and probably to Greek. A resemblance to a Chinese word for 'great wind' is real but its role is disputed, so this entry separates what is established from what is only suggested.","cn":"typhoon 经葡萄牙语进入英语，其上游可追到阿拉伯语，并很可能再追到希腊语。它与汉语中表示「大风」的词形相似确实存在，但作用有争议，因此这里把已确立的部分与仅为推测的部分分开说明。"},"items":[{"era":"GREEK TYPHON","en":"Greek Typhōn was the name of a monstrous storm-giant, and the common noun typhōn could mean a whirlwind; its link to typhein 'to smoke' is often proposed but not certain.","cn":"希腊语 Typhōn 是风暴巨人提丰的名字，普通名词 typhōn 可指旋风；它与 typhein「冒烟」的联系常被提出，但并不确定。"},{"era":"ARABIC TUFAN","en":"Arabic ṭūfān means 'deluge, flood, storm'. Whether it is inherited within Arabic or borrowed from Greek typhōn is disputed.","cn":"阿拉伯语 ṭūfān 意为「洪水、暴雨、风暴」。它是阿拉伯语内部继承还是借自希腊 typhōn，存在争议。"},{"era":"PORTUGUESE TUFAO","en":"Portuguese tufão 'typhoon' is the immediate source for English, taken from Arabic during the age of Indian Ocean trade.","cn":"葡萄牙语 tufão「台风」是英语的直接来源，印度洋贸易时代从阿拉伯语借入。"},{"era":"ENGLISH SIXTEENTH CENTURY","en":"English records the word in the late sixteenth century in accounts of voyages to the East; early spellings vary between tufan, tuffon and typhon.","cn":"英语在 16 世纪晚期的东方航行记载中收录此词；早期拼写有 tufan、tuffon、typhon 等变体。"},{"era":"CHINESE RESEMBLANCE","en":"The modern spelling resembles Cantonese tai fung 'great wind', and some writers treat Chinese as a second source. Standard references regard the resemblance as parallel rather than proven, so the origin is not settled on this point.","cn":"现代拼写与粤语「大风」相近，有些作者把汉语视为第二来源。通行词源资料认为这只是并行相似而非已证实的来源，因此这一点上来源不确定。"}]},"similar":{"note":{"en":"Group one collects words that merely look or sound like typhoon; group two collects the basin names and the smaller vortices.","cn":"第一组只是形音相近的词；第二组是各海域的名称与更小的涡旋。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tycoon","ipa":"/taɪˈkuːn/","tag":"Japanese source","definition":"From Japanese taikun 'great lord': a wealthy business leader. The ending is -coon, not -phoon, and the root is unrelated.","definitionCN":"来自日语 taikun「大君」：指富有的商界巨头。词尾是 -coon 而非 -phoon，词根无关。"},{"word":"typhus","ipa":"/ˈtaɪfəs/","tag":"Greek typhos","definition":"From Greek typhos 'smoke, stupor', the name of a infectious fever; the root is smoke, not a storm.","definitionCN":"来自希腊 typhos「烟、昏沉」，是一种传染性热病的名称；词根是烟，不是风暴。"},{"word":"typhoid","ipa":"/ˈtaɪfɔɪd/","tag":"same typhos root","definition":"typhos 'smoke, stupor' plus -oid 'like'; it names a fever and shares no storm meaning.","definitionCN":"typhos「烟、昏沉」加 -oid「像」；指一种热病，没有风暴义。"},{"word":"typhon","ipa":"/ˈtaɪfɒn/","tag":"the Greek source word","definition":"The Greek proper name and common noun behind the modern word, kept in English mainly for the mythological giant.","definitionCN":"现代词背后的希腊专名与普通名词，英语中主要保留指神话巨人的用法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hurricane","ipa":"/ˈhʌrɪkən/","tag":"Atlantic name","definition":"The Atlantic and eastern Pacific name for a tropical cyclone; identical in structure, different in basin.","definitionCN":"大西洋与东太平洋对热带气旋的称名；结构相同，海域不同。"},{"word":"cyclone","ipa":"/ˈsaɪkləʊn/","tag":"Indian Ocean name","definition":"The Indian Ocean and South Pacific name for the same class of storm, or any closed low-pressure circulation.","definitionCN":"印度洋与南太平洋对同类风暴的称名，也指任何闭合低压环流。"},{"word":"tornado","ipa":"/tɔːˈneɪdəʊ/","tag":"much smaller","definition":"A narrow, violent vortex touching the ground from a thundercloud, far smaller than a typhoon.","definitionCN":"从雷暴云触地的狭窄猛烈涡旋，比台风小得多。"},{"word":"storm","ipa":"/stɔːm/","tag":"general term","definition":"The general word for disturbed weather with strong wind; typhoon is the specific tropical subtype.","definitionCN":"强风扰动天气的通称；台风是其特定的热带子类。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real basin names, real fixed phrases and the real compound family, not invented rhymes.","cn":"正常联想：真实的海域名、真实固定搭配与真实复合词族，而非编造的顺口溜。"},"normal":[{"en":"Three basins, three names: hurricane, typhoon, cyclone.","cn":"三个海域三个名称：hurricane、typhoon、cyclone。"},{"en":"Typhoon belongs to the western North Pacific and the South China Sea.","cn":"台风属于西北太平洋与南海。"},{"en":"Fixed phrases: typhoon season, typhoon warning, typhoon shelter.","cn":"固定搭配：台风季、台风警报、避风塘。"},{"en":"Super typhoon is the stronger grade above typhoon.","cn":"super typhoon 是台风之上的更强等级。"},{"en":"Typhoon-force winds are the strongest wind term in forecasts.","cn":"typhoon-force 是预报里最强的风力用语。"}],"abstract":[{"en":"Picture a whirlpool of cloud with a calm hole at its centre.","cn":"想象一个云的漩涡，中心有一个平静的孔。"},{"en":"Picture a fishing boat hiding in a narrow cove while the sea outside boils.","cn":"想象一条渔船躲在狭窄的小湾里，外面的海在翻腾。"},{"en":"Picture a wave of criticism arriving as fast as weather.","cn":"想象一阵批评像天气一样迅速压过来。"}]},"examples":[{"en":"The typhoon weakened to a tropical storm before reaching the coast.","cn":"台风在到达海岸之前减弱为热带风暴。"},{"en":"Typhoon season in the western Pacific peaks from July to October.","cn":"西北太平洋的台风季在七月到十月达到高峰。"},{"en":"Boats crowded into the typhoon shelter as the signal was raised.","cn":"信号升起时，船只纷纷挤进避风塘。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「台轰」——台风登陆时轰然一声，风球高挂","word":"typhoon"},"root":"经葡萄牙语 tufão 借自阿拉伯语 ṭūfān「洪水、风暴」，更早一般推测与希腊 typhōn「旋风、提丰」有关；阿拉伯语这一环是否借自希腊语尚有争议。现代拼写与汉语「大风」相近，但是否影响拼写来源不确定。","sensesIntro":{"en":"Eight senses follow the storm from open sea to harbour: the system, its basin name, its landfall, the older broad use, the season, the shelter, the metaphor and the warning signal.","cn":"八个义项跟着风暴从外海走到港湾：系统本身、海域名称、登陆成灾、旧时的宽泛用法、季节、避风塘、比喻义与警报信号。"},"semanticMap":{"core":{"en":"CORE IMAGE: a huge cloud spiral over warm water with a calm eye at its centre.","cn":"核心意象：暖水上方巨大的云螺旋，中心是平静的眼区。"},"chain":["WARM SEA HEATS AIR","LOW PRESSURE DEEPENS","WIND SPIRALS TIGHT","EYE OPENS","COAST IS HIT","HARBOUR IS SOUGHT"],"branches":[{"senses":"01 · 02","en":"SYSTEM AND NAME: one storm physics, three basin labels; typhoon is the western Pacific label.","cn":"系统与名称：一套风暴物理，三个海域标签；typhoon 是西太平洋的标签。"},{"senses":"03 · 04","en":"EVENT AND OLD WORD: the modern disaster report and the older any-storm use are two views of the same violence.","cn":"事件与旧词：现代灾害报道与旧时的泛称，是同一暴力的两种视角。"},{"senses":"05 · 08","en":"CALENDAR AND SIGNAL: the season and the numbered warning are both administrative frames around the storm.","cn":"日历与信号：季节与编号警报都是围绕风暴的行政框架。"},{"senses":"06","en":"SHELTER: the place named after the storm it defends against.","cn":"避风处：以它所抵御的风暴命名的地点。"},{"senses":"07","en":"SOCIAL STORM: criticism and anger arrive with the same sudden force.","cn":"社会风暴：批评与愤怒以同样的突然力量到来。"}]},"affixes":{"intro":{"en":"Typhoon is a whole borrowed word, not an English prefix-root-suffix build. Its productive life is in compounds: super typhoon, typhoon shelter, typhoon-proof, typhoon-force.","cn":"typhoon 是整体借入的词，不是英语的前缀—词根—后缀结构。它的构词活力体现在复合词：super typhoon、typhoon shelter、typhoon-proof、typhoon-force。"},"latinIntro":{"en":"There is no Latin cognate family here: the word travelled by Arabic and Portuguese, and Latin holds only the borrowed proper name Typhon, which is not a derivational base for the English word.","cn":"这里没有拉丁同族词：这个词经阿拉伯语与葡萄牙语传来，拉丁语只有借入的专名 Typhon，而它并不是英语词的派生基础。"},"items":[{"word":"super typhoon","structure":"super- 'above, beyond' + typhoon","meaning":"a typhoon above the top sustained-wind category","meaningCN":"超过最高持续风速等级的台风","example":"Super typhoons are labelled with a separate category.","exampleCN":"超强台风用单独的分类标注。"},{"word":"typhoon shelter","structure":"typhoon + shelter (compound noun)","meaning":"a harbour where boats refuge from storms","meaningCN":"船只躲避风暴的港湾","example":"The old typhoon shelter is now lined with restaurants.","exampleCN":"旧避风塘如今沿岸开满餐馆。"},{"word":"typhoon-proof","structure":"typhoon + -proof 'resistant to'","meaning":"built to resist typhoon winds","meaningCN":"能抵御台风大风的","example":"The new bridge is typhoon-proof.","exampleCN":"新桥能抗台风。"},{"word":"typhoon-force","structure":"typhoon + force 'strength of wind'","meaning":"of wind at typhoon strength","meaningCN":"风力达台风级的","example":"Typhoon-force gusts brought down the power lines.","exampleCN":"台风级阵风刮倒了电线。"},{"word":"typhoon-like","structure":"typhoon + -like 'resembling'","meaning":"resembling a typhoon","meaningCN":"台风般的","example":"A typhoon-like swirl appeared on the radar.","exampleCN":"雷达上出现了一个台风般的涡旋。"},{"word":"-phoon","structure":"the terminal element of the borrowed word, not a productive suffix","meaning":"no independent meaning in English","meaningCN":"在英语中没有独立含义","example":"No English word is built with -phoon.","exampleCN":"没有英语词用 -phoon 构成。"},{"word":"tufão","structure":"Portuguese tufão, the immediate borrowing source","meaning":"typhoon","meaningCN":"台风","example":"Portuguese traders carried the word east and west.","exampleCN":"葡萄牙商人把这个词东西传播。"},{"word":"ṭūfān","structure":"Arabic ṭūfān 'deluge, storm'","meaning":"flood, violent storm","meaningCN":"洪水；猛烈风暴","example":"The Arabic noun named a destructive flood.","exampleCN":"这个阿拉伯名词指毁灭性的洪水。"}],"latinEntries":[]}},{"word":"tornado","ipa_uk":"/tɔːˈneɪdəʊ/","ipa_us":"/tɔrˈneɪdoʊ/","definition_zh":"龙卷风；陆龙卷；（旧义）雷暴；旋风般的一阵","definition_en":"a violently rotating column of air extending from a thundercloud to the ground","core_image":"漏斗状的黑云从雷暴底部垂到地面，所过之处尘土、木板与树枝被卷上天","scene":"警报器在镇上响起，人们抱着孩子跑向地下室，广播员喊道 A tornado touched down in the wheat field west of town.","sceneCN":"这里 tornado 指「从雷暴云伸到地面的旋转空气柱」（第 1 个义项：气象学意义上的陆龙卷）；句意为一个龙卷风在镇子西边的小麦田里触地。","pos":[{"tag":"n.","zh":"龙卷风；陆龙卷；旋风般的一阵"}],"collocations":[{"phrase":"tornado warning","zh":"龙卷风警报（已发现龙卷风）"},{"phrase":"tornado watch","zh":"龙卷风警戒（条件可能形成）"},{"phrase":"tornado alley","zh":"龙卷风走廊"},{"phrase":"tornado season","zh":"龙卷风季"},{"phrase":"tornado siren","zh":"龙卷风警报器"},{"phrase":"tornado damage","zh":"龙卷风造成的破坏"}],"forms":[{"label":"单数（原形）","form":"tornado"},{"label":"复数（常用）","form":"tornadoes"},{"label":"复数（变体）","form":"tornados"},{"label":"形容词","form":"tornadic"},{"label":"复合名词","form":"tornado warning"}],"derivatives":[{"word":"tornadic","pos":"adj.","zh":"龙卷风的；具有龙卷风特征的"},{"word":"tornadogenesis","pos":"n.","zh":"龙卷风生成"},{"word":"tornado-like","pos":"adj.","zh":"龙卷风般的"},{"word":"tornado-proof","pos":"adj.","zh":"防龙卷风的"},{"word":"tornado-prone","pos":"adj.","zh":"易发龙卷风的"}],"senses":[{"no":"01","title":"Rotating column touching the ground","titleCN":"陆龙卷：触地的旋转空气柱","definition":"a violently rotating column of air in contact with both a thundercloud and the ground","definitionCN":"同时接触雷暴云与地面的猛烈旋转空气柱","example":"The tornado flattened two barns in less than a minute.","exampleCN":"龙卷风不到一分钟就推平了两座谷仓。","why":"The meteorological definition turns on ground contact: a funnel that never touches down is not counted as one.","whyCN":"气象学定义的关键在是否触地：始终没触地的漏斗云不算龙卷风。"},{"no":"02","title":"Any violent whirlwind","titleCN":"泛指猛烈的旋风","definition":"in everyday speech, any destructive whirling wind, whatever its origin","definitionCN":"日常口语中泛指任何破坏性的旋转风，不论其成因","example":"A tornado of dust crossed the road and blinded the drivers.","exampleCN":"一团尘土旋风横过公路，让司机们看不见路。","why":"Ordinary speakers name the visible violence rather than the classification, so the word widens beyond the technical sense.","whyCN":"普通人按可见的暴力命名，而不按分类，因此这个词超出技术义。"},{"no":"03","title":"Old sense: a thunderstorm","titleCN":"旧义：雷暴","definition":"in sixteenth- and seventeenth-century English, a violent thunderstorm rather than a funnel","definitionCN":"在 16 与 17 世纪英语中，指猛烈的雷暴而非漏斗云","example":"In the old chronicle a tornado broke the masts of three ships.","exampleCN":"在那部旧编年史里，一场雷暴折断了三艘船的桅杆。","why":"The word came from Spanish for a thunderstorm; the modern funnel sense narrowed from that wider weather event much later.","whyCN":"这个词来自西班牙语中「雷暴」的说法；现代漏斗义是后来从这一更宽的天气事件收窄出来的。"},{"no":"04","title":"West African squall line","titleCN":"西非常见用法：飑线雷暴","definition":"in West African English, a line of violent thunderstorms with sudden cool wind","definitionCN":"西非英语中指伴随骤起凉风的强雷暴线","example":"The harmattan tornado rolled in from the savannah at dusk.","exampleCN":"黄昏时，来自稀树草原的雷暴飑线滚滚而来。","why":"Regional usage kept the older broad sense, so the same word names a thunder line on another continent.","whyCN":"地域用法保留了较早的宽泛义，因此同一个词在另一块大陆指雷暴线。"},{"no":"05","title":"The disaster event","titleCN":"作为灾害事件的龙卷风","definition":"the storm viewed as an event that destroys buildings and takes lives","definitionCN":"从摧毁建筑、夺走生命的灾害事件角度看的龙卷风","example":"The tornado killed eleven people on the edge of the city.","exampleCN":"这场龙卷风在城市边缘夺走了十一条生命。","why":"Reports and insurance claims treat the vortex as a single catastrophic event, and the word follows that usage.","whyCN":"报道与保险理赔把涡旋当作单一灾难点，这个词也随之这样用。"},{"no":"06","title":"Figurative burst","titleCN":"比喻义：爆发般的一阵","definition":"a sudden overwhelming burst of applause, criticism or emotion","definitionCN":"掌声、批评或情绪突然而压倒性的一阵爆发","example":"A tornado of applause met the singer at the end of the song.","exampleCN":"歌曲结束时，一阵暴风般的掌声迎向歌手。","why":"The metaphor keeps the shape: something arrives spinning, fast, and sweeps everything up.","whyCN":"这个比喻保留了形状：某物旋转着快速到来，把一切卷起。"},{"no":"07","title":"Tornado season","titleCN":"龙卷风季","definition":"the spring period in which tornadoes are most frequent in a region","definitionCN":"某地区龙卷风最频繁的春季时段","example":"The plains grow quiet again after tornado season ends.","exampleCN":"龙卷风季结束后，平原又安静下来。","why":"The season is named for its dominant hazard, a common pattern in weather vocabulary.","whyCN":"季节以主导灾害命名，这是天气词汇常见的模式。"},{"no":"08","title":"The aircraft name","titleCN":"专名义：狂风战斗机","definition":"a twin-engine combat aircraft produced in Europe, known by the proper name Tornado","definitionCN":"欧洲联合研制的双发战斗机，以专名 Tornado（狂风）称呼","example":"The Tornado flew low over the valley on a training sortie.","exampleCN":"狂风战斗机在一次训练飞行中低空掠过山谷。","why":"Weapon names borrow the force of natural phenomena, so the storm word becomes a proper name for a machine.","whyCN":"武器命名借用自然现象的威力，因此风暴词成了机器的专名。"}],"etymology":{"intro":{"en":"Tornado is a blend of two Spanish weather words: tronada 'thunderstorm', from tronar 'to thunder', and tornado 'turned, rotating', from tornar 'to turn'. English borrowed it as a word for a thunderstorm and only later narrowed it to the funnel.","cn":"tornado 由两个西班牙语天气词混合而成：tronada「雷暴」（来自 tronar「打雷」）与 tornado「旋转的」（来自 tornar「转」）。英语借入时指雷暴，后来才收窄为漏斗云。"},"items":[{"era":"LATIN TONARE","en":"Latin tonare 'to thunder', with the noun tonitrus 'thunder', supplied the first half of the Spanish word.","cn":"拉丁语 tonare「打雷」及其名词 tonitrus「雷」提供了西班牙语词的前半部分。"},{"era":"SPANISH TRONADA","en":"Spanish tronada meant 'thunderstorm', built on tronar 'to thunder'; it named the whole storm, not a funnel.","cn":"西班牙语 tronada 意为「雷暴」，由 tronar「打雷」构成；它指整场风暴，而非漏斗。"},{"era":"SPANISH TORNADO","en":"Separately, tornar 'to turn' (from Latin tornare) produced tornado 'turned, rotating'; English speakers blended the two Spanish forms.","cn":"另一方面，tornar「转」（来自拉丁 tornare）构成 tornado「旋转的」；英语使用者把两个西班牙语形式混合起来。"},{"era":"ENGLISH SEVENTEENTH CENTURY","en":"Early English records use tornado for a violent thunderstorm at sea, especially in accounts of the Caribbean and the Atlantic.","cn":"早期英语记载用 tornado 指海上猛烈的雷暴，尤见于加勒比与大西洋的记述。"},{"era":"MODERN METEOROLOGY","en":"The narrow funnel sense established itself in the nineteenth century, once observers began requiring contact with the ground.","cn":"狭窄的漏斗义在 19 世纪确立，因为观测者开始要求它必须触地。"}]},"similar":{"note":{"en":"The first group looks similar in spelling but comes from other roots; the second group holds the rotating-wind family and its synonyms.","cn":"第一组拼写相近但词根不同；第二组是旋转风家族及其同义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"torpedo","ipa":"/tɔːˈpiːdəʊ/","tag":"Latin numbness","definition":"From Latin torpedo 'numbness, the numb fish'; it names a underwater weapon, with no turning or thunder in its root.","definitionCN":"来自拉丁 torpedo「麻木、电鱼」；指水下武器，词根里没有转或雷。"},{"word":"toreador","ipa":"/ˌtɔːriəˈdɔː/","tag":"Spanish bullfighter","definition":"From Spanish torear 'to fight bulls', from toro 'bull'; the ending -dor marks an agent, not a storm.","definitionCN":"来自西班牙语 torear「斗牛」，源于 toro「公牛」；词尾 -dor 表施事者，不是风暴。"},{"word":"torn","ipa":"/tɔːn/","tag":"participle of tear","definition":"The past participle of tear 'to rip'; it looks close but belongs to a completely different verb.","definitionCN":"tear「撕」的过去分词；形近但属于完全不同的动词。"},{"word":"torrent","ipa":"/ˈtɒrənt/","tag":"Latin scorching","definition":"From Latin torrens 'rushing, burning', from torrere 'to scorch'; it names a fast stream, not a wind.","definitionCN":"来自拉丁 torrens「奔流、灼烧」，源于 torrere「烤焦」；指急流，不是风。"}]},{"heading":"NEAR MEANING","entries":[{"word":"whirlwind","ipa":"/ˈwɜːlwɪnd/","tag":"general vortex","definition":"A general term for a rapidly rotating mass of air, often smaller and less organised than a tornado.","definitionCN":"快速旋转气团的通称，通常比龙卷风更小、更有组织性更弱。"},{"word":"cyclone","ipa":"/ˈsaɪkləʊn/","tag":"large system","definition":"A large low-pressure system with rotating winds, hundreds of times wider than a tornado.","definitionCN":"带旋转风的大型低压系统，宽度可达龙卷风的数百倍。"},{"word":"hurricane","ipa":"/ˈhʌrɪkən/","tag":"tropical storm","definition":"A tropical storm of the Atlantic with sustained winds above 119 km/h; a different scale of phenomenon.","definitionCN":"大西洋持续风速超过每小时 119 公里的热带风暴；现象尺度不同。"},{"word":"twister","ipa":"/ˈtwɪstə/","tag":"informal synonym","definition":"An informal American word for a tornado, used mostly in news headlines and speech.","definitionCN":"美式口语中对龙卷风的说法，多用于新闻标题与口语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Spanish blend, real meteorological terms and the real compound family, not invented rhymes.","cn":"正常联想：西班牙语混合来源、真实气象术语与真实复合词族，而非编造的顺口溜。"},"normal":[{"en":"tronada 'thunderstorm' plus tornado 'turned': a storm that turns.","cn":"tronada「雷暴」加 tornado「旋转的」：一场会转的风暴。"},{"en":"The same thunder root sits in detonate and tonitrus.","cn":"同一个「雷」词根在 detonate 与 tonitrus 里。"},{"en":"Warning means it has been seen; watch means it might form.","cn":"warning 表示已经发现；watch 表示可能形成。"},{"en":"Tornado alley is the plains strip where they are most frequent.","cn":"tornado alley 是龙卷风最频繁的平原狭长地带。"},{"en":"The plural is usually tornadoes, sometimes tornados.","cn":"复数通常写 tornadoes，有时写 tornados。"}],"abstract":[{"en":"Picture a black funnel stitching the cloud to the ground.","cn":"想象一个黑色漏斗把云和地面缝在一起。"},{"en":"Picture straw driven into a wooden post by the wind.","cn":"想象一根稻草被风钉进木柱。"},{"en":"Picture applause arriving like weather through a theatre.","cn":"想象掌声像天气一样扫过剧场。"}]},"examples":[{"en":"A tornado watch was issued for the whole county by noon.","cn":"到中午时，整个县都发布了龙卷风警戒。"},{"en":"The tornado lifted a truck and dropped it in the next field.","cn":"龙卷风把一辆卡车卷起，又把它扔到隔壁田里。"},{"en":"Meteorologists count a funnel as a tornado only when it touches the ground.","cn":"气象学家只有在漏斗云触地时才把它算作龙卷风。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「陀螺转」——像陀螺一样贴地狂转的风","word":"tornado"},"root":"西班牙语 tronada「雷暴」（tronar「打雷」，拉丁 tonare「打雷」）与 tornado「旋转的」（tornar「转」，拉丁 tornare「转」）混合而成。英语 17 世纪借入时指海上雷暴，19 世纪才专指触地的漏斗云；词源清楚，义项收窄的年代有明确记载。","sensesIntro":{"en":"Eight senses follow one funnel: the technical vortex, the everyday whirlwind, the old thunderstorm sense, the West African squall, the disaster, the metaphor, the season and the aircraft name.","cn":"八个义项沿一个漏斗展开：技术涡旋、日常旋风、旧雷暴义、西非飑线、灾害事件、比喻义、龙卷风季与飞机专名。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dark funnel hanging from a thundercloud and stirring dust at the ground.","cn":"核心意象：黑色漏斗从雷暴云垂下，在地面搅起尘土。"},"chain":["WARM AIR RISES FAST","SPIN TIGHTENS","FUNNEL TOUCHES DOWN","DEBRIS IS LIFTED","TOWN IS STRUCK","SIREN SOUNDS"],"branches":[{"senses":"01 · 02","en":"TECHNICAL AND EVERYDAY: one strict definition with ground contact, one loose name for any visible whirl.","cn":"技术与日常：一个是要求触地的严格定义，一个是任何可见旋风的宽泛叫法。"},{"senses":"03 · 04","en":"TWO OLD WEATHER SENSES: the English thunderstorm of the seventeenth century and the West African squall line keep the wider meaning.","cn":"两个旧的天气义：17 世纪英语的雷暴与西非的飑线保留了更宽的含义。"},{"senses":"05 · 07","en":"DISASTER AND CALENDAR: the event that destroys and the season that schedules it.","cn":"灾害与日历：造成破坏的事件与为它排定时间的季节。"},{"senses":"06","en":"SOCIAL BURST: applause and criticism can arrive with the same spin.","cn":"社会爆发：掌声与批评能以同样的旋转到来。"},{"senses":"08","en":"NAME REUSED: the storm word becomes a proper name for a combat aircraft.","cn":"名称再用：风暴词成为战斗机的专名。"}]},"affixes":{"intro":{"en":"Tornado has no English prefix or suffix; it is a borrowed Spanish blend. Its derivatives are compounds and the learned adjective tornadic.","cn":"tornado 没有英语前缀或后缀；它是借入的西班牙语混合词。其派生形式是复合词与学术形容词 tornadic。"},"latinIntro":{"en":"Two Latin families meet in this word: tonare 'to thunder' and tornare 'to turn'. Both are genuine and both are visible in the Spanish forms.","cn":"这个词里汇合了两个拉丁词族：tonare「打雷」与 tornare「转」。两者都真实存在，且都能在西班牙语形式中看到。"},"items":[{"word":"tronar","structure":"Spanish tronar 'to thunder', from Latin tonare","meaning":"to thunder","meaningCN":"打雷","example":"Spanish tronar 'to thunder' is the source of tronada, the older word for a storm.","exampleCN":"西班牙语 tronar「打雷」是 tronada（较早的风暴说法）的来源。"},{"word":"tornar","structure":"Spanish tornar 'to turn', from Latin tornare","meaning":"to turn, to return","meaningCN":"转动；返回","example":"Spanish tornar 'to turn' gives tornado its rotating sense.","exampleCN":"西班牙语 tornar「转」赋予 tornado 旋转的含义。"},{"word":"-ado","structure":"-ado (Spanish past-participle ending)","meaning":"having been acted on; -ed","meaningCN":"已被……的；相当于 -ed","example":"The ending makes tornado literally 'turned'.","exampleCN":"这个词尾使 tornado 字面上就是「被转动的」。"},{"word":"tornadic","structure":"tornado + -ic (relating to)","meaning":"relating to a tornado","meaningCN":"龙卷风的","example":"Tornadic winds are the strongest on the Plains.","exampleCN":"龙卷风风力是平原上最强的。"},{"word":"tornadogenesis","structure":"tornado + -genesis 'birth'","meaning":"the formation of a tornado","meaningCN":"龙卷风的生成","example":"Tornadogenesis began along the dry line.","exampleCN":"龙卷风生成在干线一带开始。"},{"word":"tornado-like","structure":"tornado + -like 'resembling'","meaning":"resembling a tornado","meaningCN":"龙卷风般的","example":"A tornado-like vortex formed over the lake.","exampleCN":"湖面上形成了一个龙卷风般的涡旋。"},{"word":"tornado-proof","structure":"tornado + -proof 'resistant to'","meaning":"built to resist tornado winds","meaningCN":"防龙卷风的","example":"The shelter is tornado-proof.","exampleCN":"这个避难所是防龙卷风的。"},{"word":"tornado-prone","structure":"tornado + -prone 'likely to suffer'","meaning":"often hit by tornadoes","meaningCN":"易受龙卷风袭击的","example":"The county is tornado-prone in spring.","exampleCN":"这个县春季易受龙卷风袭击。"}],"latinEntries":[{"word":"tonare","structure":"tonare, tonui, tonitum (verb, first conjugation)","meaning":"to thunder","meaningCN":"打雷"},{"word":"tonitrus","structure":"tonitrus, tonitrus (m., fourth declension)","meaning":"thunder","meaningCN":"雷；雷声"},{"word":"tornare","structure":"tornare, tornavi, tornatum (verb, first conjugation)","meaning":"to turn, to turn in a lathe","meaningCN":"转动；在车床上旋削"}]}},{"word":"whirlwind","ipa_uk":"/ˈwɜːlwɪnd/","ipa_us":"/ˈwɜːrlwɪnd/","definition_zh":"旋风；尘卷风；一连串迅疾的事件；情绪翻涌","definition_en":"a mass of air turning rapidly around a moving centre, often lifting dust or loose material","core_image":"干草场上，风把尘土和草屑拧成一根旋转的柱子，贴着地面横冲过去","scene":"麦场上，一阵风把干草和尘土卷成一根旋转的柱子，老人指着说 A whirlwind crossed the yard and carried the straw over the fence.","sceneCN":"这里 whirlwind 指「绕移动中心快速旋转的气团」（第 1 个义项：能把尘土和轻物卷起的旋风）；句意为一阵旋风穿过院子，把稻草卷过了篱笆。","pos":[{"tag":"n.","zh":"旋风；尘卷风；一连串迅疾之事"},{"tag":"adj.","zh":"旋风式的；极快的（如旋风式旅行）"}],"collocations":[{"phrase":"whirlwind tour","zh":"旋风式旅行；走马观花的一趟"},{"phrase":"whirlwind romance","zh":"闪电式恋情"},{"phrase":"whirlwind of activity","zh":"一连串密集的活动"},{"phrase":"whirlwind of change","zh":"急剧的变化"},{"phrase":"whirlwind of emotions","zh":"翻涌的情绪"},{"phrase":"reap the whirlwind","zh":"自食其果；收获自己种下的恶果"}],"forms":[{"label":"单数（原形）","form":"whirlwind"},{"label":"复数","form":"whirlwinds"},{"label":"定语用法（作形容词）","form":"whirlwind"},{"label":"复合名词（旋风式旅行）","form":"whirlwind tour"},{"label":"复合名词（闪电式恋情）","form":"whirlwind romance"}],"derivatives":[{"word":"whirlwind-like","pos":"adj.","zh":"旋风般的"},{"word":"whirlwind tour","pos":"n.","zh":"旋风式旅行；行程极紧的访问"},{"word":"whirlwind romance","pos":"n.","zh":"闪电式恋情"},{"word":"whirlwind of change","pos":"n.","zh":"急剧的变化"}],"senses":[{"no":"01","title":"Air turning rapidly around a centre","titleCN":"旋风：绕中心快速旋转的气团","definition":"a body of air turning rapidly around a centre that moves across the ground","definitionCN":"绕一个中心快速旋转、并沿地面移动的气团","example":"A whirlwind scattered the dry leaves across the road.","exampleCN":"一阵旋风把干叶子吹散到公路上。","why":"Whirl names the turning and wind names the air, so the compound says exactly what it is: air that spins.","whyCN":"whirl 说「转」，wind 说「空气」，复合词正好说出它是什么：会转的空气。"},{"no":"02","title":"Dust devil","titleCN":"尘卷风：看得见的尘土柱","definition":"a small, short-lived vortex made visible by the dust and debris it lifts","definitionCN":"因卷起尘土与碎屑而可见的小型短命涡旋","example":"Dust devils danced along the empty road at noon.","exampleCN":"正午时分，尘卷风在空荡的公路上跳跃。","why":"Once the vortex lifts loose material, the dust draws its outline, and the word names that visible column.","whyCN":"涡旋卷起松软物质后，尘土勾出它的轮廓，这个词就指那根可见的柱子。"},{"no":"03","title":"A violent tornado-scale vortex","titleCN":"龙卷级的猛烈旋风","definition":"in older and literary usage, a large destructive whirlwind capable of tearing roofs away","definitionCN":"在较早与文学用法中，指能掀掉屋顶的大型破坏性旋风","example":"The whirlwind tore the roof off the barn and flung it into the creek.","exampleCN":"旋风掀掉谷仓的屋顶，把它甩进小河。","why":"Before tornado became the technical term, whirlwind covered the violent end of the scale, and the older sense survives in literature.","whyCN":"在 tornado 成为术语之前，whirlwind 涵盖这一暴力极端，旧义仍留在文学中。"},{"no":"04","title":"Rapid succession of events","titleCN":"比喻义：一连串迅疾的事件","definition":"a rapid, dizzying succession of events that leaves little time to rest","definitionCN":"一连串迅速而令人眩晕、几乎没有喘息时间的事件","example":"The wedding was a whirlwind of meetings, forms and last-minute repairs.","exampleCN":"婚礼成了一连串会面、表格与临时修补。","why":"The metaphor borrows the spin: events arrive faster than they can be sorted, the way dust is swept up.","whyCN":"这个比喻借用了旋转：事件来得比理清更快，就像尘土被卷起。"},{"no":"05","title":"Emotional turmoil","titleCN":"比喻义：情绪翻涌","definition":"a confused, intense swirl of feelings that carries a person along","definitionCN":"把人带着走的一团混乱而强烈的情绪","example":"She left the interview in a whirlwind of relief and doubt.","exampleCN":"她带着宽慰与怀疑交织的翻涌情绪离开了面试。","why":"Feelings are described as air in motion: they circle, collide and refuse to settle.","whyCN":"情绪被说成流动的空气：打转、相撞、不肯平息。"},{"no":"06","title":"Very fast, as an attributive","titleCN":"定语用法：极快的、旋风式的","definition":"used before a noun to mean very fast and tightly packed, as in a whirlwind tour","definitionCN":"置于名词前，表示极快且安排密集，如旋风式旅行","example":"They did a whirlwind tour of three capitals in five days.","exampleCN":"他们五天内旋风式地游了三座首都。","why":"The speed of the vortex becomes the defining quality of the trip, so the noun turns into a modifier.","whyCN":"涡旋的速度成了这趟旅行的定义特征，于是名词变成修饰语。"},{"no":"07","title":"Biblical and literary tempest","titleCN":"圣经与文学中的暴风","definition":"a destructive tempest used as an image of judgment, as in the phrase reap the whirlwind","definitionCN":"作为审判意象的破坏性暴风，如短语「自食其果」所示","example":"The prophet warned that the nation would reap the whirlwind.","exampleCN":"先知警告说，这个民族将自食其果。","why":"Scriptural language uses the storm as a picture of consequences arriving with irresistible force.","whyCN":"圣经语言用风暴比喻以不可阻挡之势到来的后果。"},{"no":"08","title":"A swirling mass of loose material","titleCN":"被卷起的旋转物质团","definition":"the swirling load itself, such as leaves, dust or flame carried up in a circle","definitionCN":"被卷起旋转的物质本身，如树叶、尘土或火焰","example":"A whirlwind of leaves followed the children down the lane.","exampleCN":"一团旋转的树叶跟着孩子们跑下小径。","why":"The container and the contents trade places: the wind is named by the visible mass it carries.","whyCN":"容器与内容互换：风用它携带的可见物质来命名。"}],"etymology":{"intro":{"en":"Whirlwind is a native English compound of whirl and wind. Whirl came from Old Norse, wind from Old English; the compound is recorded from the fourteenth century, and the figurative use is later.","cn":"whirlwind 是英语本土复合词，由 whirl 与 wind 合成。whirl 来自古诺斯语，wind 来自古英语；复合词约 14 世纪见于记载，比喻用法更晚。"},"items":[{"era":"OLD NORSE HVIRFLA","en":"Old Norse hvirfla meant 'to turn round, whirl', and the noun hvirfill named a ring, a circle or a whirlpool.","cn":"古诺斯语 hvirfla 意为「旋转、打转」，名词 hvirfill 指环、圆圈或漩涡。"},{"era":"PROTO-GERMANIC","en":"The ancestor is reconstructed as *hwerb- or *hwerfl- 'to turn'; German wirbeln 'to whirl' and Dutch wervelen descend from the same reconstructed form.","cn":"更早的祖形被重构为 *hwerb- 或 *hwerfl-，意为「转」；德语 wirbeln「旋转」与荷兰语 wervelen 都出自同一重构形式。"},{"era":"OLD ENGLISH WIND","en":"Old English wind 'wind' goes back to Proto-Germanic *windaz, generally connected with a root meaning 'to blow'.","cn":"古英语 wind「风」上溯到原始日耳曼语 *windaz，一般与表示「吹」的词根相联系。"},{"era":"ENGLISH FOURTEENTH CENTURY","en":"The compound whirlwind is recorded in Middle English; the exact first occurrence is uncertain, and the word competed with other native terms for the same weather.","cn":"复合词 whirlwind 见于中古英语；确切的最早书证不确定，这个词曾与其他本土说法竞争同一天气现象。"},{"era":"MODERN ENGLISH","en":"The figurative senses, a whirlwind of events and a whirlwind tour, belong to later literary and journalistic usage.","cn":"比喻义——一连串事件与旋风式旅行——属于较晚的文学与新闻用法。"}]},"similar":{"note":{"en":"The first group is built from the same or similar pieces but means something else; the second group holds the rotating-weather family.","cn":"第一组由相同或相近的成分构成，但意思不同；第二组是旋转天气家族。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"windmill","ipa":"/ˈwɪndmɪl/","tag":"wind + mill","definition":"A building with sails turned by the wind to grind grain or pump water; the second element is a machine, not spinning air.","definitionCN":"用风转动叶片来磨粮或抽水的建筑；第二成分是机器，不是旋转的空气。"},{"word":"window","ipa":"/ˈwɪndəʊ/","tag":"wind + eye","definition":"From Old Norse vindauga 'wind eye', an opening for air and light; it shares wind but not the whirling.","definitionCN":"来自古诺斯语 vindauga「风眼」，通风透光的开口；同有 wind，但没有旋转义。"},{"word":"whirlpool","ipa":"/ˈwɜːlpuːl/","tag":"same whirl, water not air","definition":"A spinning body of water; the same whirl element with pool instead of wind.","definitionCN":"旋转的水体；同一 whirl 成分，但换成 pool 而非 wind。"},{"word":"whirling","ipa":"/ˈwɜːlɪŋ/","tag":"participle of whirl","definition":"The present participle of the verb whirl 'to turn quickly'; it describes the action, not the weather system.","definitionCN":"动词 whirl「快速旋转」的现在分词；描述动作，不是天气系统。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tornado","ipa":"/tɔːˈneɪdəʊ/","tag":"technical vortex","definition":"The technical term for a violent vortex touching the ground from a thundercloud; narrower and more formal than whirlwind.","definitionCN":"从雷暴云触地的猛烈涡旋的技术术语；比 whirlwind 更窄、更正式。"},{"word":"cyclone","ipa":"/ˈsaɪkləʊn/","tag":"large system","definition":"A large low-pressure system whose winds rotate around a centre; far larger than a whirlwind.","definitionCN":"风绕中心旋转的大型低压系统；比旋风大得多。"},{"word":"dust devil","ipa":"/ˈdʌst ˌdevl/","tag":"small dust vortex","definition":"The usual name for a small, fair-weather whirlwind made visible by dust.","definitionCN":"晴好天气下由尘土显形的小型旋风的常用名称。"},{"word":"gust","ipa":"/ɡʌst/","tag":"brief blast","definition":"A sudden brief increase in wind; it pushes in a straight line rather than turning in a circle.","definitionCN":"风的突然短暂加强；是直线推进而非绕圈旋转。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real halves of the compound, real fixed phrases and the real rotating-weather family, not invented rhymes.","cn":"正常联想：复合词两个真实成分、真实固定搭配与真实旋转天气词族，而非编造的顺口溜。"},"normal":[{"en":"whirl 'turn quickly' + wind 'moving air': the word is its own definition.","cn":"whirl「快转」+ wind「流动的空气」：这个词就是自己的定义。"},{"en":"The same whirl sits in whirlpool and whirligig.","cn":"同一个 whirl 在 whirlpool 与 whirligig 里。"},{"en":"Fixed phrases: whirlwind tour, whirlwind romance, whirlwind of change.","cn":"固定搭配：旋风式旅行、闪电式恋情、急剧变化。"},{"en":"Reap the whirlwind means suffer the consequences of what you did.","cn":"reap the whirlwind 意为自食其果。"},{"en":"As an adjective it always means very fast, never calm.","cn":"作形容词时永远表示极快，从不表示平静。"}],"abstract":[{"en":"Picture a straw hat lifted and hung in the air for a moment.","cn":"想象一顶草帽被卷起，在空中悬停片刻。"},{"en":"Picture a week so full that it feels like one long spin.","cn":"想象一周忙得像一场漫长的旋转。"},{"en":"Picture feelings circling so fast that none of them can land.","cn":"想象情绪转得太快，哪一种都落不下来。"}]},"examples":[{"en":"A whirlwind lifted the tarpaulin and dropped it on the shed roof.","cn":"一阵旋风把防水布卷起，又把它扔到棚顶上。"},{"en":"The delegation returned from a whirlwind tour of four cities.","cn":"代表团结束了对四座城市的旋风式访问后返回。"},{"en":"Her first term was a whirlwind of lectures, labs and exams.","cn":"她的第一个学期是一场讲座、实验与考试的旋风。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「涡轮」——涡旋像轮子一样转，转出一阵贴地的风","word":"whirlwind"},"root":"英语本土复合词：whirl 来自古诺斯语 hvirfla「旋转」（更早祖形一般重构为 *hwerb-/*hwerfl-「转」），wind 来自古英语 wind，上溯原始日耳曼语 *windaz。构词与来源清楚；复合词最早书证约 14 世纪，具体年代不确定。","sensesIntro":{"en":"Eight senses follow the same turning: a spinning volume of air, its visible dust column, the violent large vortex, a rush of events, a swirl of feelings, the fast modifier, the biblical tempest and the swirling load itself.","cn":"八个义项沿同一个旋转展开：旋转的气团、可见的尘土柱、猛烈的大涡旋、事件的一阵急转、情绪的翻涌、表示极快的定语、圣经式暴风，以及被卷起旋转的物质本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: dust and straw twisted into a spinning column that travels across a field.","cn":"核心意象：尘土与稻草被拧成一根旋转的柱子，横穿田野移动。"},"chain":["AIR BEGINS TO TURN","DUST IS LIFTED","COLUMN STANDS UP","GROUND IS SCOURED","VISIT RUSHES BY","FEELINGS SPIN"],"branches":[{"senses":"01 · 08","en":"WIND AND LOAD: the spinning air and the material it carries take turns being the referent.","cn":"风与被卷物：旋转的空气与它携带的材料轮流充当所指对象。"},{"senses":"02 · 03","en":"SMALL AND LARGE: a dust devil and a roof-tearing vortex are the two ends of one scale.","cn":"小与大：尘卷风与掀屋顶的涡旋是同一尺度的两端。"},{"senses":"04 · 06","en":"FAST TIME: a rush of events and a whirlwind tour both make time feel spun.","cn":"飞快的时间：事件急转与旋风式旅行都让时间像被旋转起来。"},{"senses":"05","en":"INNER WEATHER: emotions circle and collide like air in a vortex.","cn":"内心天气：情绪像涡旋里的空气一样打转、相撞。"},{"senses":"07","en":"JUDGMENT: scripture turns the storm into an image of consequences.","cn":"审判：圣经把风暴变成后果的意象。"}]},"affixes":{"intro":{"en":"Whirlwind is a compound, not a suffixed word: whirl plus wind. Its productive life is in phrases such as whirlwind tour and whirlwind romance.","cn":"whirlwind 是复合词而非加后缀的词：whirl 加 wind。它的构词活力在 whirlwind tour、whirlwind romance 这类短语里。"},"latinIntro":{"en":"There is no Latin cognate here. Whirl is Germanic and wind is Germanic; Latin expresses the same idea with turbo and vortex, which are semantic counterparts rather than relatives.","cn":"这里没有拉丁同族词。whirl 属日耳曼语，wind 也属日耳曼语；拉丁语用 turbo 与 vortex 表达同一概念，那是语义对应词而非同族词。"},"items":[{"word":"whirl","structure":"whirl (verb and noun, from Old Norse hvirfla)","meaning":"to turn round very fast","meaningCN":"快速旋转","example":"The dancers whirl across the floor.","exampleCN":"舞者在舞池里旋转。"},{"word":"wind","structure":"wind (noun, from Old English wind)","meaning":"moving air","meaningCN":"流动的空气","example":"The wind rose after sunset.","exampleCN":"日落后风大了起来。"},{"word":"whirlpool","structure":"whirl + pool (compound noun)","meaning":"a spinning body of water","meaningCN":"旋转的水体","example":"The boat was pulled toward the whirlpool.","exampleCN":"小船被拉向漩涡。"},{"word":"whirligig","structure":"whirl + gig (reduplicating compound)","meaning":"a spinning toy or a merry-go-round","meaningCN":"旋转玩具；旋转木马","example":"The child spun the whirligig on the path.","exampleCN":"孩子在路上转动旋转玩具。"},{"word":"whirlwind-like","structure":"whirlwind + -like 'resembling'","meaning":"resembling a whirlwind","meaningCN":"旋风般的","example":"A whirlwind-like rush of air crossed the platform.","exampleCN":"一阵旋风般的气流掠过站台。"},{"word":"whirlwind tour","structure":"whirlwind (attributive) + tour","meaning":"a very fast tour with little time in each place","meaningCN":"每处停留极短的快速旅行","example":"The band played a whirlwind tour of six countries.","exampleCN":"乐队在六国做了旋风式巡演。"},{"word":"whirlwind romance","structure":"whirlwind (attributive) + romance","meaning":"a relationship that starts and intensifies very quickly","meaningCN":"开始与升温都极快的恋情","example":"Their whirlwind romance ended in a summer wedding.","exampleCN":"他们的闪电式恋情以一场夏季婚礼结束。"},{"word":"-wind","structure":"the second element of the compound, identical to the noun wind","meaning":"air in motion","meaningCN":"流动的空气","example":"The second half keeps its literal meaning.","exampleCN":"后半部分保留了字面义。"}],"latinEntries":[]}}]);
